def test_quote_row_contract_is_generated_for_both_browser_consumers() -> None:
    manifest = quote_stream_row_contract_manifest()
    helper_source = Path("src/aef_terminal/ui/assets/js/20-live-quote-helpers.js").read_text(
        encoding="utf-8"
    )
    worker_source = Path(
        "src/aef_terminal/ui/assets/workers/quote-stream-shared-worker.js"
    ).read_text(encoding="utf-8")

    assert manifest["version"] == 1
    assert len(manifest["required_fields"]) == len(set(manifest["required_fields"]))
    for field_group in (
        "number_fields",
        "boolean_fields",
        "time_fields",
        "status_fields",
        "text_fields",
        "non_empty_text_fields",
        "nullable_text_fields",
    ):
        assert set(manifest[field_group]) <= set(manifest["required_fields"])
    assert manifest["entitlement_field"] in manifest["required_fields"]
    assert "const SCREENER_QUOTE_FRAME_FIELDS" not in helper_source
    assert "SCREENER_QUOTE_FRAME_CONTRACT.required_fields" in helper_source
    assert "const QUOTE_ROW_REQUIRED_FIELDS" not in worker_source
    assert "QUOTE_ROW_CONTRACT.required_fields" in worker_source


