def test_browser_uuid_v4_uses_secure_random_fallback_without_random_uuid(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/04-browser-identity.js").read_text(
        encoding="utf-8"
    )
    script_path = tmp_path / "browser-uuid-v4.js"
    script_path.write_text(
        "\n".join(
            (
                "const vm = require('node:vm');",
                f"const source = {json.dumps(source)};",
                "const context = { crypto: { getRandomValues(bytes) { for (let index = 0; index < bytes.length; index += 1) bytes[index] = index; return bytes; } } };",
                "vm.createContext(context);",
                "vm.runInContext(source + '\\nresult = createBrowserUuidV4();', context);",
                "console.log(context.result);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    assert result.stdout.strip() == "00010203-0405-4607-8809-0a0b0c0d0e0f"


