def test_chart_and_settings_controls_expose_keyboard_accessibility_contract(
    tmp_path: Path,
) -> None:
    html = martincall_html()
    css = martincall_css_source()
    interaction_source = Path(
        "src/aef_terminal/ui/assets/js/60-interactions-drawings-alerts.js"
    ).read_text(encoding="utf-8")
    chart_source = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(
        encoding="utf-8"
    )
    settings_source = Path("src/aef_terminal/ui/assets/js/70-settings-boot.js").read_text(
        encoding="utf-8"
    )

    for chart_id, label in (("price-chart", "Price chart"), ("volume-chart", "Volume chart")):
        chart_tag = html.split(f'id="{chart_id}"', 1)[1].split(">", 1)[0]
        assert 'role="img"' in chart_tag
        assert 'tabindex="0"' in chart_tag
        assert f'aria-label="{label}"' in chart_tag
        assert 'aria-roledescription="interactive chart"' in chart_tag
        assert 'aria-describedby="chart-keyboard-help chart-accessible-status"' in chart_tag
        assert 'aria-keyshortcuts="ArrowLeft ArrowRight Home End Escape"' in chart_tag
    assert 'id="chart-accessible-status" class="sr-only" role="status" aria-live="polite"' in html
    assert ".sr-only {" in css
    assert 'id="session-price-opacity"' in html
    assert 'aria-label="Price session shading opacity"' in html
    assert 'aria-describedby="session-price-opacity-label"' in html
    assert 'id="session-price-opacity-label" class="muted" for="session-price-opacity"' in html
    assert 'aria-label="Signals range"' in html
    assert 'aria-label="Signal density"' in html
    assert 'setAttribute("aria-valuetext", `${priceSessionOpacity}%`)' in settings_source
    assert 'setAttribute("aria-valuetext", `${volumeSessionOpacity}%`)' in settings_source

    assert "updateAccessibleChartLoadStatus(snapshot);" in chart_source
    keyboard_source = (
        "function updateAccessibleChartLoadStatus(snapshot = state.snapshot)"
        + interaction_source.split(
            "function updateAccessibleChartLoadStatus(snapshot = state.snapshot)", 1
        )[1].split("function setupChartInteractions", 1)[0]
    )
    script_path = tmp_path / "accessible-chart-keyboard.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const listeners = {};",
                "function canvas(id) { return { id, listeners: {}, addEventListener(type, callback) { (this.listeners[type] ||= []).push(callback); }, getBoundingClientRect() { return { width: 500, height: 300 }; } }; }",
                "const price = canvas('price-chart'); const volume = canvas('volume-chart'); const status = { textContent: '', dataset: {} };",
                "const document = { getElementById(id) { return { 'price-chart': price, 'volume-chart': volume, 'chart-accessible-status': status }[id] || null; } };",
                "const bars = [",
                "  { ts: '2026-07-20T13:20:00.000Z', open: 99, high: 101, low: 98, close: 100, volume: 10, closed: true, state: 'confirmed' },",
                "  { ts: '2026-07-20T13:25:00.000Z', open: 100, high: 102, low: 99, close: 101, volume: 20, closed: true, state: 'confirmed' },",
                "  { ts: '2026-07-20T13:30:00.000Z', open: 101, high: 103, low: 100, close: 102, volume: 30, closed: false, state: 'forming' },",
                "];",
                "const state = { symbol: 'ES', timeframe: '5m', snapshot: { bars }, crosshair: { visible: false, source: null, index: null } };",
                "const CHART_LEFT_PAD = 10; const PRICE_AXIS_WIDTH = 50;",
                "const axisTimeFormatter = { format(value) { return value.toISOString(); } };",
                "const fmt = value => Number(value).toFixed(2);",
                "const clamp = (value, low, high) => Math.max(low, Math.min(high, value));",
                "const visibleBars = snapshot => ({ bars: snapshot.bars, allBars: snapshot.bars, start: 0, end: snapshot.bars.length });",
                "const chartVisualSpan = rows => rows.length; const rightGapBars = () => 0;",
                "const chartX = (pad, step) => index => pad.left + step * (index + 0.5);",
                "const priceChartGeometry = () => ({ y: priceValue => 200 - priceValue });",
                "const barIsConfirmedClosed = bar => bar.closed === true && bar.state === 'confirmed';",
                "const barIsLivePreview = bar => bar.closed === false;",
                "let renders = 0; const published = [];",
                "function refreshCrosshairOverlays() { renders += 1; }",
                "function publishLinkedCrosshair(crosshair, options = {}) { published.push({ crosshair: { ...crosshair }, options }); }",
                keyboard_source,
                "function event(key) { return { key, altKey: false, ctrlKey: false, metaKey: false, prevented: false, stopped: false, preventDefault() { this.prevented = true; }, stopPropagation() { this.stopped = true; } }; }",
                "updateAccessibleChartLoadStatus(state.snapshot); assert.equal(status.textContent, 'ES 5m chart loaded. 3 candles available.'); assert.equal(status.dataset.chartState, 'ready');",
                "state.crosshair.visible = true; status.textContent = 'current candle'; updateAccessibleChartLoadStatus(state.snapshot); assert.equal(status.textContent, 'current candle'); state.crosshair.visible = false;",
                "setupAccessibleChartKeyboard();",
                "price.listeners.focus[0]();",
                "assert.equal(state.crosshair.source, 'price'); assert.equal(state.crosshair.index, 2); assert.match(status.textContent, /close 102.00/);",
                "const left = event('ArrowLeft'); price.listeners.keydown[0](left);",
                "assert.equal(state.crosshair.index, 1); assert.equal(left.prevented, true); assert.equal(left.stopped, true);",
                "price.listeners.keydown[0](event('Home')); assert.equal(state.crosshair.index, 0);",
                "price.listeners.keydown[0](event('End')); assert.equal(state.crosshair.index, 2);",
                "volume.listeners.focus[0](); assert.equal(state.crosshair.source, 'volume'); assert.equal(state.crosshair.index, 2);",
                "const escape = event('Escape'); volume.listeners.keydown[0](escape);",
                "assert.equal(state.crosshair.visible, false); assert.equal(status.textContent, 'Chart cursor cleared.');",
                "assert.ok(renders >= 6); assert.equal(published.at(-1).options.visible, false);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


