def test_command_palette_has_one_standard_line_and_one_ruler_action(
    tmp_path: Path,
) -> None:
    html = martincall_html()
    drawing_tools = re.findall(r'data-drawing-tool="([^"]+)"', html)
    source = Path("src/aef_terminal/ui/assets/js/65-command-palette.js").read_text(encoding="utf-8")
    actions_source = (
        "function commandPaletteActions()"
        + source.split("function commandPaletteActions()", 1)[1].split(
            "function commandPaletteFilteredActions",
            1,
        )[0]
    )
    script_path = tmp_path / "command-palette-ruler.js"
    script_path.write_text(
        "\n".join(
            (
                f"const drawingTools = {json.dumps(drawing_tools)};",
                "const document = {",
                "  querySelectorAll(selector) {",
                "    if (selector === '[data-drawing-tool]') {",
                "      return drawingTools.map(tool => ({ dataset: { drawingTool: tool }, title: tool }));",
                "    }",
                "    return [];",
                "  },",
                "  getElementById() { return null; },",
                "};",
                "const TIMEFRAMES = [];",
                "const state = { instruments: [] };",
                "const selectedLineModes = [];",
                "function setDrawingLineMode(mode) { selectedLineModes.push(mode); }",
                "function setDrawingTool() {}",
                actions_source,
                "const check = (value, message) => { if (!value) throw new Error(message); };",
                "const actions = commandPaletteActions();",
                "const ids = actions.map(action => action.id);",
                "check(new Set(ids).size === ids.length, 'command palette action ids must be unique');",
                "const standard = actions.filter(action => action.id === 'drawing:line');",
                "const rulers = actions.filter(action => action.id === 'drawing:ruler');",
                "check(standard.length === 1, 'expected exactly one trend-line action');",
                "check(rulers.length === 1, 'expected exactly one ruler action');",
                "check(standard[0].label === 'Trend line', 'standard action label changed');",
                "check(rulers[0].label === 'Ruler', 'ruler action label changed');",
                "standard[0].run();",
                "rulers[0].run();",
                "check(JSON.stringify(selectedLineModes) === JSON.stringify(['line', 'ruler']), 'line actions must select exact modes');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert drawing_tools.count("line") == 1
    assert result.returncode == 0, result.stderr


