def test_server_settings_failure_retries_latest_queued_values(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/08-server-storage.js").read_text(encoding="utf-8")
    flush_source = (
        "function flushServerSettings"
        + source.split(
            "function flushServerSettings",
            1,
        )[1]
    )

    assert "const SERVER_SETTING_RETRY_MS = 2000;" in source
    assert "succeeded ? 0 : retryDelay" in flush_source

    script_path = tmp_path / "server-settings-retry.js"
    script_path.write_text(
        "\n".join(
            (
                "const SERVER_SETTING_RETRY_MS = 2000;",
                "const serverSettings = {};",
                "const serverSettingQueue = new Map();",
                "const serverSettingLatestMutations = new Map();",
                "const serverSettingAuthoritativeOrders = new Map();",
                "const serverSettingFailures = new Map();",
                "let serverSettingFlushTimer = null;",
                "const serverSettingFlushRequests = new Set();",
                "let serverSettingAuthoritativeRevision = 0;",
                "const SERVER_SETTING_MUTATION_HIGH_WATER_PREFIX = 'mutation-high-water:';",
                "const SERVER_SETTING_WRITER_ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;",
                "const serverSettingWriterId = '123e4567-e89b-42d3-a456-426614174000';",
                "const serverSettingWriterHighWaterKey = SERVER_SETTING_MUTATION_HIGH_WATER_PREFIX + serverSettingWriterId;",
                "let serverSettingWriterSequence = 0; let serverSettingChangedAtMs = 0; let nowTick = 0;",
                "const performance = { timeOrigin: 1700000000000, now() { nowTick += 1; return nowTick; } };",
                "const sessionStorage = { setItem() {}, removeItem() {} };",
                "const localValues = new Map(); const localStorage = { getItem(key) { return localValues.has(key) ? localValues.get(key) : null; }, setItem(key, value) { localValues.set(key, String(value)); } };",
                "function rawLocalStorageSetItem(key, value) { localStorage.setItem(key, value); return true; }",
                "function serverSettingMutationHighWater() { return Number(localStorage.getItem(serverSettingWriterHighWaterKey) || 0); }",
                "function observeServerSettingMutationChangedAtMs(value) { serverSettingChangedAtMs = Math.max(serverSettingChangedAtMs, Number(value)); rawLocalStorageSetItem(serverSettingWriterHighWaterKey, String(serverSettingChangedAtMs)); return serverSettingChangedAtMs; }",
                "function applyServerSettings() {}",
                "function serverSettingMutationOrderIsNewer(candidate, current) { if (!current) return true; if (candidate.changed_at_ms !== current.changed_at_ms) return candidate.changed_at_ms > current.changed_at_ms; if (String(candidate.writer_id || '') !== String(current.writer_id || '')) return String(candidate.writer_id || '') > String(current.writer_id || ''); return candidate.sequence > current.sequence; }",
                "function publishServerSettingMutations() {}",
                "const serverSettingsSaveState = { phase: 'saved', pending: 0, error: '' };",
                "function setServerSettingsSaveState(phase, error = '') { serverSettingsSaveState.phase = phase; serverSettingsSaveState.pending = serverSettingQueue.size; serverSettingsSaveState.error = String(error || ''); }",
                "function isCurrentClientSettingKey(key) { return String(key || '').startsWith('aef:'); } function isBrowserWritableClientSettingKey(key) { return isCurrentClientSettingKey(key); }",
                "function normalizeErrorPayload(payload) { return payload || null; }",
                "function apiErrorMessage(_payload, fallback) { return fallback; }",
                "function requestErrorMessage(error, fallback) { return error?.message || fallback; }",
                "const timers = new Map(); let nextTimerId = 1;",
                "globalThis.window = { setTimeout(fn, delay) { const id = nextTimerId++; timers.set(id, { fn, delay }); return id; }, clearTimeout(id) { timers.delete(id); } };",
                "let rejectFirst; let fetchCalls = 0; const payloads = [];",
                "function settingsAck(body) { return { ok: true, count: body.mutations.length, settings_revision: 1, mutations: body.mutations.map(item => ({ ...item, outcome: 'applied', writer_id: body.writer_id })) }; }",
                "function fetchJson(_url, options) { const body = JSON.parse(options.body); payloads.push(body); fetchCalls += 1; if (fetchCalls === 1) return new Promise((_resolve, reject) => { rejectFirst = reject; }); return Promise.resolve(settingsAck(body)); }",
                "console.warn = () => {};",
                flush_source,
                "(async () => {",
                "  queueServerSetting('aef:a', '1');",
                "  const first = flushServerSettings();",
                "  while (typeof rejectFirst !== 'function') await Promise.resolve();",
                "  queueServerSetting('aef:a', '2');",
                "  queueServerSetting('aef:b', '3');",
                "  rejectFirst(new Error('offline'));",
                "  await first;",
                "  const retry = Array.from(timers.values())[0];",
                "  const queueValues = () => Object.fromEntries(Array.from(serverSettingQueue, ([key, item]) => [key, item.value]));",
                "  const afterFailure = { phase: serverSettingsSaveState.phase, delay: retry?.delay, queue: queueValues() };",
                "  timers.clear();",
                "  await retry.fn();",
                "  console.log(JSON.stringify({ afterFailure, payloads, fetchCalls, queue: queueValues(), phase: serverSettingsSaveState.phase }));",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload == {
        "afterFailure": {"phase": "error", "delay": 2000, "queue": {"aef:a": "2", "aef:b": "3"}},
        "payloads": [
            {
                "writer_id": "123e4567-e89b-42d3-a456-426614174000",
                "mutations": [
                    {
                        "key": "aef:a",
                        "value": "1",
                        "changed_at_ms": 1_700_000_000_002,
                        "sequence": 1,
                    }
                ],
            },
            {
                "writer_id": "123e4567-e89b-42d3-a456-426614174000",
                "mutations": [
                    {
                        "key": "aef:a",
                        "value": "2",
                        "changed_at_ms": 1_700_000_000_003,
                        "sequence": 2,
                    },
                    {
                        "key": "aef:b",
                        "value": "3",
                        "changed_at_ms": 1_700_000_000_004,
                        "sequence": 3,
                    },
                ],
            },
        ],
        "fetchCalls": 2,
        "queue": {},
        "phase": "saved",
    }


def test_server_setting_writer_is_page_unique_and_observes_all_tab_high_waters(
    tmp_path: Path,
) -> None:
    identity_source = Path("src/aef_terminal/ui/assets/js/04-browser-identity.js").read_text(
        encoding="utf-8"
    )
    source = Path("src/aef_terminal/ui/assets/js/08-server-storage.js").read_text(encoding="utf-8")
    reducer_source = Path("src/aef_terminal/ui/assets/js/07-settings-reducer.js").read_text(
        encoding="utf-8"
    )
    writer_pattern_source = reducer_source.split("\n\n", 1)[0]
    initialization_source = source.split("const serverSettings = {};", 1)[0]
    high_water_source = (
        "function localStorageKeys"
        + source.split(
            "function localStorageKeys",
            1,
        )[1].split("function isPrunableLocalStorageKey", 1)[0]
    )
    runtime_source = (
        "window.CLIENT_SETTINGS_CONTRACT_MANIFEST = "
        + json.dumps(
            browser_client_settings_contract_manifest(),
            sort_keys=True,
            separators=(",", ":"),
        )
        + ";\n"
        + identity_source
        + "\n"
        + writer_pattern_source
        + "\n"
        + high_water_source
        + initialization_source
        + """
globalThis.writerState = {
  writerId: serverSettingWriterId,
  sequence: serverSettingWriterSequence,
  changedAtMs: serverSettingChangedAtMs,
};
"""
    )
    script_path = tmp_path / "server-settings-writer-initialization.js"
    script_path.write_text(
        "\n".join(
            (
                "const vm = require('node:vm');",
                f"const runtimeSource = {json.dumps(runtime_source)};",
                "const WRITER_A = '123e4567-e89b-42d3-a456-426614174000';",
                "const WRITER_B = '223e4567-e89b-42d3-a456-426614174000';",
                "const WRITER_C = '323e4567-e89b-42d3-a456-426614174000';",
                "const WRITER_D = '423e4567-e89b-42d3-a456-426614174000';",
                "const PREFIX = 'martincall:settings-mutation-high-water-ms:v1:';",
                "function storage(entries) { const values = new Map(entries); return { values, get length() { return values.size; }, key(index) { return Array.from(values.keys())[index] ?? null; }, getItem(key) { return values.has(key) ? values.get(key) : null; }, setItem(key, value) { values.set(key, String(value)); }, removeItem(key) { values.delete(key); } }; }",
                "function run(randomWriter) {",
                "  const local = storage([[PREFIX + WRITER_A, '1800000000000'], [PREFIX + WRITER_B, '1800000000500']]);",
                "  const context = { localStorage: local, window: { BroadcastChannel: function BroadcastChannel() {} }, crypto: { randomUUID() { return randomWriter; } }, TypeError, Math, Error }; context.globalThis = context;",
                "  vm.runInNewContext(runtimeSource, context);",
                "  return context.writerState;",
                "}",
                "console.log(JSON.stringify({ first: run(WRITER_C), second: run(WRITER_D) }));",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload["first"] == {
        "writerId": "323e4567-e89b-42d3-a456-426614174000",
        "sequence": 0,
        "changedAtMs": 1_800_000_000_500,
    }
    assert payload["second"] == {
        "writerId": "423e4567-e89b-42d3-a456-426614174000",
        "sequence": 0,
        "changedAtMs": 1_800_000_000_500,
    }
    assert "navigator.locks" not in initialization_source


