                "const sessionValues = new Map([['aef:workspace:1:theme', 'light'], ['aef:workspace:1:theme:dirty', '1']]);",
                "const sessionStorage = { setItem(key, value) { sessionValues.set(key, String(value)); }, getItem(key) { return sessionValues.get(key) ?? null; }, removeItem(key) { sessionValues.delete(key); } };",
                "const localValues = new Map(); const localStorage = { getItem(key) { return localValues.has(key) ? localValues.get(key) : null; }, setItem(key, value) { localValues.set(key, String(value)); } };",
                "function rawLocalStorageSetItem(key, value) { localStorage.setItem(key, value); return true; }",
