                "function observeServerSettingMutationChangedAtMs(value) { serverSettingChangedAtMs = Math.max(serverSettingChangedAtMs, Number(value)); rawLocalStorageSetItem(serverSettingWriterHighWaterKey, String(serverSettingChangedAtMs)); return serverSettingChangedAtMs; }",
                "let appliedSnapshot = null; function applyServerSettings(_settings, options) { appliedSnapshot = { value: sessionStorage.getItem('aef:workspace:1:theme'), dirty: sessionStorage.getItem('aef:workspace:1:theme:dirty'), server: serverSettings['aef:workspace:1:theme'], options: { ...(options || {}) } }; }",
                "function serverSettingMutationOrderIsNewer(candidate, current) { if (!current) return true; if (candidate.changed_at_ms !== current.changed_at_ms) return candidate.changed_at_ms > current.changed_at_ms; if (String(candidate.writer_id || '') !== String(current.writer_id || '')) return String(candidate.writer_id || '') > String(current.writer_id || ''); return candidate.sequence > current.sequence; }",
                "function publishServerSettingMutations() {}",
                "const serverSettingsSaveState = { phase: 'saved', pending: 0, error: '' };",
                "function setServerSettingsSaveState(phase, error = '') { serverSettingsSaveState.phase = phase; serverSettingsSaveState.pending = serverSettingQueue.size + serverSettingFlushRequests.size; serverSettingsSaveState.error = String(error || ''); }",
                "function isCurrentClientSettingKey(key) { return String(key || '').startsWith('aef:'); } function isBrowserWritableClientSettingKey(key) { return isCurrentClientSettingKey(key); }",
                "function normalizeErrorPayload(payload) { return payload || null; }",
                "function apiErrorMessage(_payload, fallback) { return fallback; }",
                "function requestErrorMessage(error, fallback) { return error?.message || fallback; }",
                "globalThis.window = { setTimeout() { return 1; }, clearTimeout() {} };",
                "function fetchJson(_url, options) { const body = JSON.parse(options.body); const sent = body.mutations[0]; return Promise.resolve({ ok: true, count: 0, settings_revision: 1, mutations: [{ key: sent.key, value: 'dark', changed_at_ms: sent.changed_at_ms + 1, sequence: 1, writer_id: '223e4567-e89b-42d3-a456-426614174000', outcome: 'rejected' }] }); }",
                "console.warn = () => {};",
                flush_source,
                "(async () => {",
                "  queueServerSetting('aef:workspace:1:theme', 'light');",
