                "const serverSettingWriterId = '123e4567-e89b-42d3-a456-426614174000';",
                "const serverSettingWriterHighWaterKey = SERVER_SETTING_MUTATION_HIGH_WATER_PREFIX + serverSettingWriterId;",
                "let serverSettingWriterSequence = 0; let serverSettingChangedAtMs = 0; let nowTick = 0;",
                "const performance = { timeOrigin: 1700000000000, now() { nowTick += 1; return nowTick; } };",
                "const sessionStorage = { setItem() {}, removeItem() {} };",
                "const localValues = new Map(); const localStorage = { getItem(key) { return localValues.has(key) ? localValues.get(key) : null; }, setItem(key, value) { localValues.set(key, String(value)); } };",
                "function rawLocalStorageSetItem(key, value) { localStorage.setItem(key, value); return true; }",
                "function serverSettingMutationHighWater() { return Number(localStorage.getItem(serverSettingWriterHighWaterKey) || 0); }",
                "function observeServerSettingMutationChangedAtMs(value) { serverSettingChangedAtMs = Math.max(serverSettingChangedAtMs, Number(value)); rawLocalStorageSetItem(serverSettingWriterHighWaterKey, String(serverSettingChangedAtMs)); return serverSettingChangedAtMs; }",
                "function applyServerSettings() {}",
                "function serverSettingMutationOrderIsNewer(candidate, current) { if (!current) return true; if (candidate.changed_at_ms !== current.changed_at_ms) return candidate.changed_at_ms > current.changed_at_ms; if (String(candidate.writer_id || '') !== String(current.writer_id || '')) return String(candidate.writer_id || '') > String(current.writer_id || ''); return candidate.sequence > current.sequence; }",
                "function publishServerSettingMutations() {}",
                "const serverSettingsSaveState = { phase: 'saved', pending: 0, error: '' };",
                "globalThis.CustomEvent = function CustomEvent(_name, options) { this.detail = options.detail; };",
                "const timers = new Map(); let nextTimerId = 1;",
                "globalThis.window = { dispatchEvent() {}, setTimeout(fn, delay) { const id = nextTimerId++; timers.set(id, { fn, delay }); return id; }, clearTimeout(id) { timers.delete(id); } };",
                save_state_source,
                "function isCurrentClientSettingKey(key) { return String(key || '').startsWith('aef:'); } function isBrowserWritableClientSettingKey(key) { return isCurrentClientSettingKey(key); }",
