                "function fetchJson(_url, options) { const body = JSON.parse(options.body); payloads.push(body); return new Promise(resolve => { requests.push({ body, resolve }); }); }",
                "function settingsAck(body) { return { ok: true, count: body.mutations.length, settings_revision: 1, mutations: body.mutations.map(item => ({ ...item, outcome: 'applied', writer_id: body.writer_id })) }; }",
