def test_runtime_drawing_projection_preserves_prior_undo_entry(tmp_path: Path) -> None:
    storage_source = Path("src/aef_terminal/ui/assets/js/60-drawing-storage.js").read_text(
        encoding="utf-8"
    )
    tools_source = Path("src/aef_terminal/ui/assets/js/60-drawing-tools.js").read_text(
        encoding="utf-8"
    )
    history_source = (
        "const DRAWING_HISTORY_LIMIT"
        + storage_source.split(
            "const DRAWING_HISTORY_LIMIT",
            1,
        )[1].split("function loadDrawingsForCurrent", 1)[0]
    )
    update_source = (
        "function updateSelectedDrawing"
        + tools_source.split(
            "function updateSelectedDrawing",
            1,
        )[1].split("function deleteSelectedDrawing", 1)[0]
    )

    assert "{ recordHistory: false }" in update_source
    assert "resetHistory: true" not in update_source

    script_path = tmp_path / "drawing-history-runtime-projection.js"
    script_path.write_text(
        "\n".join(
            (
                "const DRAWING_LOCAL_EDIT_GRACE_MS = 8000;",
                "const state = { instrumentId: 'i1', symbol: 'TEST', timeframe: '5m', snapshot: null, drawing: { objects: [{ id: 'd1', type: 'line', width: 1, anchorProjection: { canonicalGeneration: 1 } }], selectedId: 'd1', persistedCount: 1, deletedIds: {}, drag: null, draft: null }, alerts: { selectedId: null }, optionTargets: { selectedId: null } };",
                "function instrumentRouteFingerprint() { return 'route-1'; }",
                "function scopedObjectSignature(...values) { return JSON.stringify(values); }",
                "function sharedObjectSignature(value) { return JSON.stringify(value); }",
                "function normalizeDrawingObjects(value) { return JSON.parse(JSON.stringify(value)); }",
                "function resolveDrawingAnchorsAgainstSnapshot() {}",
                "function touchChartUserObjectsVersion() {}",
                "function persistDrawingsToServer() {}",
                "function showBrowserToast() {}",
                "function markDrawingDeleted(id) { state.drawing.deletedIds[id] = Date.now(); }",
                "function selectedDrawing() { return state.drawing.objects.find(item => item.id === state.drawing.selectedId) || null; }",
                "function applyDrawingUi() {}",
                "function requestObjectLayerRedraw() {}",
                history_source,
                update_source,
                "const geometryBefore = captureDrawingHistoryState();",
                "state.drawing.objects[0].width = 2;",
                "saveDrawings({ historyBefore: geometryBefore, historyLabel: 'Width' });",
                "if (drawingHistoryState.undo.length !== 1) throw new Error('geometry edit was not recorded');",
                "updateSelectedDrawing({ anchorProjection: { canonicalGeneration: 2 } });",
                "if (drawingHistoryState.undo.length !== 1) throw new Error('runtime projection erased or added history');",
                "if (!undoDrawingMutation()) throw new Error('prior geometry edit could not be undone');",
                "const restored = state.drawing.objects[0];",
                "const geometryResult = { width: restored.width, generation: restored.anchorProjection?.canonicalGeneration, undo: drawingHistoryState.undo.length, redo: drawingHistoryState.redo.length };",
                "state.drawing.objects = []; state.drawing.selectedId = null; state.drawing.deletedIds = {}; state.drawing.persistedCount = 0; resetDrawingHistory();",
                "const beforeAdd = captureDrawingHistoryState();",
                "state.drawing.objects = [{ id: 'd2', type: 'line', width: 1, anchorProjection: { canonicalGeneration: 1 } }]; state.drawing.selectedId = 'd2';",
                "saveDrawings({ historyBefore: beforeAdd, historyLabel: 'Add drawing' });",
                "updateSelectedDrawing({ anchorProjection: { canonicalGeneration: 2 } });",
                "if (!undoDrawingMutation() || state.drawing.objects.length !== 0) throw new Error('added drawing was not undone');",
                "if (!redoDrawingMutation()) throw new Error('added drawing was not restored');",
                "const addRedoResult = { count: state.drawing.objects.length, generation: state.drawing.objects[0]?.anchorProjection?.canonicalGeneration };",
                "console.log(JSON.stringify({ geometryResult, addRedoResult }));",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
