def test_option_target_server_merge_executes_without_legacy_inflight_state(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/59-option-targets.js").read_text(encoding="utf-8")
    identity_source = (
        "function optionTargetScopeKey"
        + source.split(
            "function optionTargetScopeKey",
            1,
        )[1].split("function pruneOptionTargetDeletes", 1)[0]
    )
    tombstone_source = (
        "function pruneOptionTargetDeletes"
        + source.split(
            "function pruneOptionTargetDeletes",
            1,
        )[1].split("function optionTargetDeleteBroadcastKey", 1)[0]
    )
    merge_source = (
        "function mergeOptionTargetsFromServer(serverItems, options = {})"
        + source.split(
            "function mergeOptionTargetsFromServer(serverItems, options = {})",
            1,
        )[1].split("function applyOptionTargetsFromServer", 1)[0]
    )
    script_path = tmp_path / "option-target-merge.js"
    script_path.write_text(
        "\n".join(
            (
                "const OPTION_TARGET_DELETE_TOMBSTONE_MS = 60000;",
                "const state = { instrumentId: 'instrument-a', timeframe: '5m', optionTargets: { items: [], draggingId: '', pendingMutationKeys: {}, deletedIds: {} } };",
                "function exactIdentityText(value) { return typeof value === 'string' ? value.trim() : ''; }",
                "function instrumentRouteFingerprint() { return 'route-a'; }",
                "function instrumentForId(instrumentId) { return instrumentId === 'instrument-a' ? { provider_symbol: 'ES' } : null; }",
                identity_source,
                tombstone_source,
                "function allOptionTargets() { pruneOptionTargetDeletes(); return state.optionTargets.items.filter(item => !optionTargetDeleted(item)); }",
                "function optionTargetMutationPending(item) { const key = optionTargetIdentityKey(item); return Boolean(key && state.optionTargets.pendingMutationKeys[key]); }",
                "function mergeOptionTargetRuntimeFields(local, serverItem) { return serverItem || local; }",
                merge_source,
                "const row = (instrument_id, route_fingerprint, version) => ({ instrument_id, route_fingerprint, id: 'same-id', version });",
                "const localA = row('instrument-a', 'route-a', 'local-a');",
                "const localB = row('instrument-b', 'route-b', 'local-b');",
                "const serverA = row('instrument-a', 'route-a', 'server-a');",
                "const requestScope = { instrumentId: 'instrument-a', routeFingerprint: 'route-a', timeframe: '5m', targetPoint: { ts: '2026-07-22T12:00:00.000Z' } };",
                "if (!optionTargetRequestScopeIsCurrent(requestScope)) process.exit(7);",
                "if (!optionTargetPayloadMatchesRequestScope({ instrument_id: 'instrument-a', route_fingerprint: 'route-a', provider_symbol: 'ES', timeframe: '5m', target_ts: requestScope.targetPoint.ts, target_bar_slot: 42 }, requestScope)) process.exit(8);",
                "if (!optionTargetPayloadMatchesRequestScope({ instrument_id: 'instrument-a', route_fingerprint: 'route-a', provider_symbol: 'NQ', timeframe: '5m', target_ts: requestScope.targetPoint.ts, target_bar_slot: 42 }, requestScope)) process.exit(9);",
                "if (optionTargetPayloadMatchesRequestScope({ instrument_id: 'instrument-a', route_fingerprint: 'route-a' }, requestScope)) process.exit(10);",
                "const providerFailure = { ok: false, message: 'provider unavailable', error: { code: 'OPTION_CONTRACT_UNIVERSE_UNAVAILABLE' } };",
                "const admittedFailure = admitOptionTargetPricingResponse(providerFailure, requestScope, '0dte');",
                "if (admittedFailure.message !== 'provider unavailable' || admittedFailure.error.code !== 'OPTION_CONTRACT_UNIVERSE_UNAVAILABLE' || admittedFailure.target_dte !== '0dte') process.exit(11);",
                "const scopedSuccess = { ok: true, instrument_id: 'instrument-a', route_fingerprint: 'route-a', provider_symbol: 'ES', timeframe: '5m', target_ts: requestScope.targetPoint.ts, target_bar_slot: 42 };",
                "if (admitOptionTargetPricingResponse(scopedSuccess, requestScope, '1dte') !== scopedSuccess) process.exit(12);",
                "const canonicalScope = optionTargetRequestScopeWithServerAxis(requestScope, scopedSuccess);",
                "if (canonicalScope.targetPoint.barSlot !== 42 || requestScope.targetPoint.barSlot !== undefined) process.exit(14);",
                "const wrongScope = admitOptionTargetPricingResponse({ ...scopedSuccess, route_fingerprint: 'route-b' }, requestScope, '1dte');",
                "if (wrongScope.error.code !== 'OPTION_TARGET_RESPONSE_SCOPE_MISMATCH' || wrongScope.target_dte !== '1dte') process.exit(13);",
                "state.optionTargets.items = [localA, localB];",
                "const scopeA = optionTargetScopeKey('instrument-a', 'route-a');",
                "const merged = mergeOptionTargetsFromServer([serverA], { scopeKey: scopeA });",
                "if (merged.length !== 2 || !merged.some(item => item.version === 'server-a') || !merged.some(item => item.version === 'local-b')) process.exit(2);",
                "if (optionTargetIdentityKey(localA) === optionTargetIdentityKey(localB)) process.exit(3);",
                "let duplicateRejected = false; try { mergeOptionTargetsFromServer([serverA, { ...serverA }], { scopeKey: scopeA }); } catch (_) { duplicateRejected = true; }",
                "if (!duplicateRejected) process.exit(6);",
                "markOptionTargetDeleted(localA);",
                "if (!optionTargetDeleted(localA) || optionTargetDeleted(localB)) process.exit(4);",
                "state.optionTargets.items = [localA, localB];",
                "const visible = allOptionTargets();",
                "if (visible.length !== 1 || visible[0].route_fingerprint !== 'route-b') process.exit(5);",
                "state.optionTargets.deletedIds = {}; state.optionTargets.items = [localA, localB];",
                "const clearedA = mergeOptionTargetsFromServer([], { scopeKey: scopeA });",
                "if (clearedA.length !== 1 || clearedA[0].route_fingerprint !== 'route-b') process.exit(6);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


