def test_martincall_asset_delivery_is_minified_and_cacheable() -> None:
    from starlette.requests import Request

    from aef_terminal.ui.routers.assets import (
        _asset_response,
        _immutable_asset_headers,
        _no_cache_headers,
    )

    source_js = martincall_js_source()
    source_css = martincall_css_source()
    delivery_js = ui_asset_services.martincall_js_delivery_sync()
    delivery_css = ui_asset_services.martincall_css_delivery_sync()

    assert len(delivery_js) < len(source_js)
    assert len(delivery_css) < len(source_css)
    assert "function boot()" in delivery_js
    assert ":root" in delivery_css
    assert "immutable" in _immutable_asset_headers()["Cache-Control"]
    assert "no-store" in _no_cache_headers()["Cache-Control"]

    scope = {
        "type": "http",
        "method": "GET",
        "path": "/assets/martincall.js",
        "headers": [(b"accept-encoding", b"gzip")],
    }
    request = Request(scope)
    response = _asset_response("x" * 256, media_type="application/javascript", request=request)
    assert response.headers.get("content-encoding") == "gzip"
    assert "immutable" in response.headers.get("cache-control", "")
    assert response.headers.get("vary") == "Accept-Encoding"

    no_gzip_request = Request(
        {
            **scope,
            "headers": [(b"accept-encoding", b"gzip;q=0, identity;q=1")],
        }
    )
    no_gzip_response = _asset_response(
        "x" * 256,
        media_type="application/javascript",
        request=no_gzip_request,
    )
    assert no_gzip_response.headers.get("content-encoding") is None

    js_gzip = ui_asset_services.martincall_js_gzip_sync()
    assert js_gzip is ui_asset_services.martincall_js_gzip_sync()
    assert gzip.decompress(js_gzip).decode("utf-8") == delivery_js


def test_martincall_asset_delivery_is_singleflight_and_drains_cancelled_worker(
    monkeypatch,
) -> None:
    started = Event()
    release = Event()
    calls: list[str] = []

    def blocking_minify(source: str) -> str:
        calls.append(source)
        started.set()
        assert release.wait(timeout=2.0)
        return "minified"

    monkeypatch.setattr(ui_asset_services, "_JS_SOURCE_CACHE", "source")
    monkeypatch.setattr(ui_asset_services, "_JS_DELIVERY_CACHE", None)
    monkeypatch.setattr(ui_asset_services, "_minify_js_source", blocking_minify)

    async def run() -> None:
        first = asyncio.create_task(ui_asset_services.martincall_js_delivery_async())
        while not started.is_set():
            await asyncio.sleep(0)
        second = asyncio.create_task(ui_asset_services.martincall_js_delivery_async())
        await asyncio.sleep(0)

        first.cancel()
        await asyncio.sleep(0)

        assert not first.done()
        assert not second.done()
        release.set()
        with pytest.raises(asyncio.CancelledError):
            await first
        assert await second == "minified"

    asyncio.run(run())

    assert calls == ["source"]


