def _client_watchlist_store(items, settings: dict | None = None):
    class Store:
        def __init__(self):
            self.items = [dict(item) for item in items]

        def initialize(self):
            return None

        def read_settings(self, scope):
            assert scope == "client"
            return dict(settings or {})

        def read_watchlist_snapshot(self):
            return list(self.items), 0

        def get_full_snapshot_context(self, **kwargs):
            return {
                "bars": list(kwargs["bars"]),
                "bar_slots": None,
                "mtf_context": {},
                "mtf_context_slots": {},
                "mtf_context_quality": {},
            }

        def read_trading_hours(self, *, instrument):
            del instrument
            return None

    return Store()


def _patch_persisted_lookup(monkeypatch):
    instruments = [
        coinbase_btc_payload(),
        ibkr_stock_payload("SPY", con_id=756733),
        ibkr_stock_payload("QQQ", con_id=320227571),
        ibkr_stock_payload("PLTR", con_id=444857942),
        ibkr_stock_payload("NVDA", con_id=4815747),
        *instrument_catalog(),
    ]
    by_instrument_id = {
        route_instrument(instrument).instrument_id: instrument for instrument in instruments
    }

    def lookup(instrument_id):
        if instrument_id not in by_instrument_id:
            raise ValueError(f"missing instrument_id={instrument_id}")
        return by_instrument_id[instrument_id]

    monkeypatch.setattr("aef_terminal.ui.runtime_instruments.lookup_runtime_instrument", lookup)
    monkeypatch.setattr(ui_market_actions, "lookup_runtime_instrument", lookup)


def _test_identity(
    key: str,
    provider: str = "ibkr",
    route: str | None = None,
    *,
    asset_class: str = "stock",
    custom: bool = False,
) -> dict:
    provider_symbol_value = route or key
    identity = {
        "provider": provider,
        "asset_class": asset_class,
    }
    if asset_class == "future":
        identity.update(
            {
                "root": key,
                "identity_scope": "root",
                "current_contract": {
                    "provider_contract_id": f"{provider}:{provider_symbol_value}:current",
                    "contract_key": provider_symbol_value,
                    "local_symbol": provider_symbol_value,
                    "secid": provider_symbol_value,
                },
                "exchange": "CME",
                "currency": "USD",
            }
        )
    else:
        identity["provider_contract_id"] = f"{provider}:{provider_symbol_value}"
    instrument_id = (
        f"{provider}|future_root|{key}|{identity['exchange']}|{identity['currency']}|"
        if asset_class == "future"
        else f"{provider}|contract|{provider}:{provider_symbol_value}"
    )
    payload = {
        "instrument_id": instrument_id,
        "key": key,
        "instrument_key": key,
        "display": key,
        "name": key,
        "provider": provider,
        "provider_symbol": provider_symbol_value,
        "provider_contract_id": ""
        if asset_class == "future"
        else f"{provider}:{provider_symbol_value}",
        "asset_class": asset_class,
        "contract_identity": identity,
        "custom": custom,
    }
    resolved = route_instrument(payload)
    payload["route_fingerprint"] = resolved.fingerprint
    return payload


