def test_trading_hours_refresh_updates_watchlist_and_pending_symbols(monkeypatch) -> None:
    instrument = ibkr_future_payload("ES", con_id=12345)
    route = route_instrument(instrument)
    fetched: list[str] = []
    acknowledged: list[str] = []

    class Store:
        def initialize(self):
            return None

        def read_trading_hours(self, *, instrument):
            assert route_instrument(instrument).fingerprint == route.fingerprint
            return None

        def upsert_trading_hours(self, *_args, **_kwargs):
            return None

    async def fetch_trading_schedule(instrument, **_kwargs):
        provider = instrument["provider"]
        provider_contract_id = (
            (instrument.get("contract_identity") or {})
            .get("current_contract", {})
            .get("provider_contract_id")
        )
        fetched.append(f"{provider}:{provider_contract_id}")
        return {
            "time_zone": "America/New_York",
            "trading_hours": "20260703:0000-20260703:2359",
            "liquid_hours": "20260703:0000-20260703:2359",
        }

    monkeypatch.setattr(route.adapter, "fetch_trading_schedule", fetch_trading_schedule)

    monkeypatch.setattr(
        trading_hours_refresh,
        "peek_pending_provider_trading_hours_refresh",
        lambda provider: ((route.instrument_id, route.fingerprint),) if provider == "ibkr" else (),
    )
    monkeypatch.setattr(
        trading_hours_refresh,
        "acknowledge_provider_trading_hours_refresh",
        lambda _provider, *symbols, expected_generation: acknowledged.extend(symbols),
    )

    deps = trading_hours_refresh.TradingHoursRefreshDeps(
        store_factory=Store,
        server_sleeping=lambda: False,
        selected_instruments=lambda: [coinbase_btc_payload(), instrument],
        logger_warning=lambda *_args, **_kwargs: None,
    )

    asyncio.run(trading_hours_refresh.refresh_trading_hours_once(deps))

    assert fetched == ["ibkr:12345"]
    assert acknowledged == [route.instrument_id, route.fingerprint]


