def test_backend_client_settings_runtime_projection_is_initialized_and_isolated(
    monkeypatch,
) -> None:
    ui_client_settings.configure_client_settings_deps(
        ui_client_settings.ClientSettingsDeps(store_factory=lambda: None)
    )

    with pytest.raises(RuntimeError, match="CLIENT_SETTINGS_RUNTIME_UNAVAILABLE"):
        ui_client_settings.client_settings_snapshot()

    loaded = {"nested": {"enabled": True}, "mode": "initial"}
    mutation_orders = {
        key: {"changed_at_ms": 0, "writer_id": None, "sequence": 0} for key in loaded
    }
    ui_client_settings.publish_client_settings_snapshot(loaded, mutation_orders, 1)
    loaded["nested"]["enabled"] = False
    first = ui_client_settings.client_settings_snapshot()
    first["nested"]["enabled"] = False

    assert ui_client_settings.client_settings_snapshot() == {
        "nested": {"enabled": True},
        "mode": "initial",
    }

    committed = {"mode": "authoritative"}
    ui_client_settings.publish_client_settings_patch(committed, settings_revision=2)
    committed["mode"] = "mutated-after-publish"

    assert ui_client_settings.client_settings_snapshot() == {
        "nested": {"enabled": True},
        "mode": "authoritative",
    }


