def test_backend_client_settings_runtime_projection_rejects_late_older_completion(
    monkeypatch,
) -> None:
    ui_client_settings.publish_client_settings_snapshot(
        {"mode": "initial"},
        {"mode": {"changed_at_ms": 0, "writer_id": None, "sequence": 0}},
        0,
    )
    newer = {
        "mode": {
            "outcome": "applied",
            "value": "newer",
            "changed_at_ms": 200,
            "writer_id": "223e4567-e89b-42d3-a456-426614174000",
            "sequence": 1,
        }
    }
    older = {
        "mode": {
            "outcome": "applied",
            "value": "older",
            "changed_at_ms": 100,
            "writer_id": "123e4567-e89b-42d3-a456-426614174000",
            "sequence": 1,
        }
    }

    ui_client_settings.publish_client_settings_mutations(newer, settings_revision=2)
    ui_client_settings.publish_client_settings_mutations(older, settings_revision=1)
    ui_client_settings.publish_client_settings_mutations(newer, settings_revision=2)

    assert ui_client_settings.client_settings_snapshot()["mode"] == "newer"

    mismatched_replay = {"mode": {**newer["mode"], "value": "wrong"}}
    with pytest.raises(RuntimeError, match="CLIENT_SETTINGS_RUNTIME_REVISION_MISMATCH"):
        ui_client_settings.publish_client_settings_mutations(
            mismatched_replay,
            settings_revision=2,
        )


def test_backend_client_settings_server_commit_resets_browser_order_under_revision() -> None:
    writer_id = "223e4567-e89b-42d3-a456-426614174000"
    ui_client_settings.publish_client_settings_snapshot(
        {"mode": "initial"},
        {"mode": {"changed_at_ms": 0, "writer_id": None, "sequence": 0}},
        0,
    )
    ui_client_settings.publish_client_settings_mutations(
        {
            "mode": {
                "outcome": "applied",
                "value": "browser-old",
                "changed_at_ms": 500,
                "writer_id": writer_id,
                "sequence": 9,
            }
        },
        settings_revision=1,
    )
    ui_client_settings.publish_client_settings_patch(
        {"mode": "server"},
        settings_revision=2,
    )
    ui_client_settings.publish_client_settings_mutations(
        {
            "mode": {
                "outcome": "applied",
                "value": "browser-new",
                "changed_at_ms": 100,
                "writer_id": writer_id,
                "sequence": 1,
            }
        },
        settings_revision=3,
    )

    assert ui_client_settings.client_settings_snapshot()["mode"] == "browser-new"


def test_backend_client_settings_snapshot_reconciliation_fences_deleted_keys() -> None:
    writer_id = "223e4567-e89b-42d3-a456-426614174000"
    ui_client_settings.publish_client_settings_snapshot(
        {"route-key": "present"},
        {"route-key": {"changed_at_ms": 20, "writer_id": writer_id, "sequence": 1}},
        4,
    )
    ui_client_settings.reconcile_client_settings_snapshot({}, {}, 5)
    ui_client_settings.publish_client_settings_mutations(
        {
            "route-key": {
                "outcome": "applied",
                "value": "stale",
                "changed_at_ms": 20,
                "writer_id": writer_id,
                "sequence": 1,
            }
        },
        settings_revision=4,
    )

    assert "route-key" not in ui_client_settings.client_settings_snapshot()


