def test_context_horizontal_line_admits_only_confirmed_drawing_anchors(
    tmp_path: Path,
) -> None:
    context_source = Path("src/aef_terminal/ui/assets/js/60-chart-context-menu.js").read_text(
        encoding="utf-8"
    )
    script_path = tmp_path / "context-horizontal-confirmed-anchors.js"
    script_path.write_text(
        "\n".join(
            (
                """
const added = [];
const confirmedStart = {
  ts: "2026-08-08T09:30:00.000Z",
  session_key: "regular",
  bar_slot: 100,
  closed: true,
  state: "confirmed",
  authoritative: true,
};
const confirmedEnd = {
  ...confirmedStart,
  ts: "2026-08-08T09:35:00.000Z",
  bar_slot: 105,
};
const state = {
  contextMenu: { bar: confirmedEnd, price: 123.5 },
  snapshot: { bars: [confirmedStart, confirmedEnd] },
};
const document = { getElementById() { return null; } };
function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }
function barIsGapPlaceholder(bar) {
  return Boolean(bar && (bar.missing || bar.data_gap || bar.preview_kind === "gap_placeholder"));
}
function barIsConfirmedClosed(bar) {
  return Boolean(
    bar
    && !barIsGapPlaceholder(bar)
    && bar.closed === true
    && (!bar.state || bar.state === "confirmed")
  );
}
function normalizeDrawingPoint(point) {
  if (!point || typeof point.ts !== "string" || !Number.isFinite(point.price)) {
    throw new TypeError("invalid drawing point");
  }
  return { ts: point.ts, price: point.price };
}
function addDrawingObject(object) { added.push(object); }
function priceChartGeometry() {
  return { bars: state.snapshot.bars, allBars: state.snapshot.bars };
}
function drawingAxisFromGeo(geo) { return geo; }
function barSlotForAbsoluteIndex(axis, index) {
  return Number(axis.allBars[index]?.bar_slot);
}
function isLightTheme() { return false; }
function themeColor() { return "unused"; }
""",
                context_source,
                """
function check(condition, message) {
  if (!condition) throw new Error(message);
}
function attempt(bar, bars) {
  state.contextMenu = { bar, price: 123.5 };
  state.snapshot = { bars };
  addHorizontalLineFromContext();
}

addHorizontalLineFromContext();
check(added.length === 1, "confirmed context bars must add one line");
check(added[0].points.length === 2, "line must keep both confirmed anchors");
check(
  added[0].points.every(point => Object.keys(point).sort().join(",") === "price,ts"),
  "durable line anchors must contain only canonical timestamp and price",
);

const forming = {
  ...confirmedEnd,
  ts: "2026-08-08T09:40:00.000Z",
  bar_slot: 110,
  closed: false,
  state: "forming",
};
attempt(forming, [confirmedStart, forming]);
check(added.length === 1, "forming context bars must fail closed");

const gap = {
  ...confirmedEnd,
  ts: "2026-08-08T09:45:00.000Z",
  bar_slot: 115,
  missing: true,
  preview_kind: "gap_placeholder",
};
attempt(gap, [confirmedStart, gap]);
check(added.length === 1, "gap placeholders must fail closed");

const provisional = {
  ...confirmedEnd,
  ts: "2026-08-08T09:50:00.000Z",
  bar_slot: 120,
  authoritative: false,
};
attempt(provisional, [confirmedStart, provisional]);
check(added.length === 1, "non-authoritative bars must fail closed");

const provisionalStart = {
  ...confirmedStart,
  ts: "2026-08-08T09:25:00.000Z",
  authoritative: false,
};
attempt(confirmedEnd, [provisionalStart, confirmedEnd]);
check(added.length === 1, "a provisional session-start anchor must fail closed");

""",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)
    assert result.returncode == 0, result.stderr


