def test_browser_capture_waits_for_exact_ready_and_honors_reconnect_backoff(
    tmp_path: Path,
) -> None:
    capture_source = Path("src/aef_terminal/ui/assets/js/18-browser-capture.js").read_text(
        encoding="utf-8"
    )
    script_path = tmp_path / "browser-capture-handshake.js"
    script_path.write_text(
        "\n".join(
            (
                "const assert = require('node:assert/strict');",
                "const timers = new Map(); let nextTimer = 1;",
                "class FakeWebSocket {",
                "  static CONNECTING = 0; static OPEN = 1; static CLOSING = 2; static CLOSED = 3;",
                "  static instances = [];",
                "  constructor(url) { this.url = url; this.readyState = FakeWebSocket.CONNECTING; this.sent = []; FakeWebSocket.instances.push(this); }",
                "  send(payload) { this.sent.push(payload); }",
                "  close(code, reason) { this.readyState = FakeWebSocket.CLOSED; this.closeCode = code; this.closeReason = reason; }",
                "  open() { this.readyState = FakeWebSocket.OPEN; this.onopen?.(); }",
                "  emit(message) { this.onmessage?.({ data: JSON.stringify(message) }); }",
                "  serverClose() { this.readyState = FakeWebSocket.CLOSED; this.onclose?.({ code: 1006, reason: '', wasClean: false }); }",
                "}",
                "const WebSocket = FakeWebSocket;",
                "const window = {",
                "  location: { protocol: 'http:', host: '127.0.0.1:8000' },",
                "  setTimeout(callback) { const id = nextTimer++; timers.set(id, callback); return id; },",
                "  clearTimeout(id) { timers.delete(id); },",
                "  addEventListener() {},",
                "};",
                "const document = { visibilityState: 'visible', addEventListener() {}, getElementById() { return null; }, querySelector() { return null; } };",
                "const state = {",
                "  instrumentSelectionStatus: { state: 'resolved' }, instrumentId: 'instrument:exact', timeframe: '5m', clientId: 'mc-00000000-0000-4000-8000-000000000001', snapshot: null,",
                "  transport: { browserCapture: { socket: null, key: '', retryTimer: null, ready: false, openedAt: 0, lastStateAt: 0, epoch: 0 } },",
                "};",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function instrumentRouteFingerprint() { return 'route:exact'; }",
                "function closeWebSocketQuietly(socket, reason) { socket.onopen = null; socket.onmessage = null; socket.onerror = null; socket.onclose = null; socket.close(1000, reason); }",
                "function renderCharts() {}",
                capture_source,
                "setupBrowserCapture();",
                "assert.equal(FakeWebSocket.instances.length, 1);",
                "const first = FakeWebSocket.instances[0]; first.open();",
                "assert.equal(first.sent.length, 0, 'client state must wait for exact capture_ready');",
                "first.emit({ type: 'capture_ready', instrument_id: 'instrument:exact', route_fingerprint: 'route:exact', timeframe: '5m' });",
                "assert.equal(state.transport.browserCapture.ready, true);",
                "assert.deepEqual(JSON.parse(first.sent[0]), { type: 'capture_state', visible: true, focused: false, timeframe: '5m' });",
                "first.serverClose();",
                "assert.equal(state.transport.browserCapture.ready, false);",
                "assert.ok(state.transport.browserCapture.retryTimer);",
                "maintainBrowserCaptureConnection(Date.now() + 1000);",
                "assert.equal(FakeWebSocket.instances.length, 1, 'heartbeat must not bypass reconnect backoff');",
                "const retryId = state.transport.browserCapture.retryTimer; const retry = timers.get(retryId); timers.delete(retryId); retry();",
                "assert.equal(FakeWebSocket.instances.length, 2);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


