def test_drawing_magnet_snaps_real_confirmed_bar_without_schedule_axis(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(encoding="utf-8")
    point_source = (
        "function chartPointFromLocal"
        + source.split("function chartPointFromLocal", 1)[1].split(
            "function lineDashForStyle",
            1,
        )[0]
    )
    magnet_radius_source = (
        "function drawingMagnetCandidateRadiusBars"
        + source.split("function drawingMagnetCandidateRadiusBars", 1)[1].split(
            "function chartVisualHitForLocalX", 1
        )[0]
    )
    script_path = tmp_path / "drawing-magnet-confirmed-ordinal.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = { drawing: { magnet: true } };",
                "const clamp = (value, low, high) => Math.max(low, Math.min(high, value));",
                magnet_radius_source,
                "const smoothOffsetBars = () => 0;",
                "const chartVisualHitForLocalX = (_bars, pad, xStep, localX) => ({ index: Math.round((localX - pad.left - xStep * 0.5) / xStep), gap: null });",
                "const maxScreenIndexForAxis = () => 2;",
                "const drawingAxisFromGeo = geo => geo;",
                "const axisSlotStep = () => 5;",
                "const barSlotForAbsoluteIndex = () => null;",
                "const providerFutureAxisIndex = () => ({ byAbsoluteIndex: new Map() });",
                "const hasPriceBar = bar => Number.isFinite(bar?.high) && Number.isFinite(bar?.low);",
                "const barIsConfirmedClosed = bar => bar?.closed === true;",
                "const real = { ts: '2026-08-01T10:00:00Z', high: 105, low: 95, closed: true };",
                "const geo = { bars: [real], allBars: [real], start: 0, pad: { left: 0, top: 0 }, xStep: 10, priceH: 100, minP: 90, maxP: 110, x: index => index * 10 + 5, y: price => (110 - price) * 5 };",
                "const priceChartGeometry = () => geo;",
                point_source,
                "const snapped = chartPointFromLocal(5, 25);",
                "const future = chartPointFromLocal(25, 25);",
                "const denseBars = Array.from({ length: 12 }, (_item, index) => ({ ts: `2026-08-01T10:${String(index).padStart(2, '0')}:00Z`, high: index === 10 ? 100 : 110, low: 90, closed: true }));",
                "geo.bars = denseBars; geo.allBars = denseBars; geo.xStep = 0.5; geo.x = index => index * 0.5 + 0.25; geo.y = price => (110 - price) * 5;",
                "const dense = chartPointFromLocal(0.25, 50);",
                "console.log(JSON.stringify({ snapped, future, dense }));",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload["snapped"] == {
        "ts": "2026-08-01T10:00:00Z",
        "barSlot": 0,
        "price": 105,
        "snapped": True,
        "snapKind": "H",
    }
    assert payload["future"] is None
    assert payload["dense"] == {
        "ts": "2026-08-01T10:10:00Z",
        "barSlot": 50,
        "price": 100,
        "snapped": True,
        "snapKind": "H",
    }


