def test_mobile_pinch_zoom_preserves_midpoint_anchor_from_live_and_history(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/59-chart-navigation.js").read_text(
        encoding="utf-8"
    )
    helper = (
        "function anchoredTimeViewportVirtualOffset("
        + source.split("    function anchoredTimeViewportVirtualOffset(", 1)[1].split(
            "\n    function zoomPrice", 1
        )[0]
    )
    script_path = tmp_path / "pinch-time-viewport.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const DEFAULT_BARS_VISIBLE = 80;",
                "const MAX_BARS_VISIBLE = 6000;",
                "const DEFAULT_RIGHT_GAP_BARS = 6;",
                "const clamp = (value, low, high) => Math.max(low, Math.min(high, value));",
                "const clampRightGapBars = value => clamp(Number(value) || DEFAULT_RIGHT_GAP_BARS, 0, 200);",
                helper,
                "const latestWide = pinchTimeViewport({ startBarsVisible: 80, startVirtualOffset: 0, startRightGapBars: 6, startDistance: 100, currentDistance: 200, startMidpointFraction: 0.5, midpointFraction: 0.5 });",
                "const latestNarrow = pinchTimeViewport({ startBarsVisible: 80, startVirtualOffset: 0, startRightGapBars: 6, startDistance: 100, currentDistance: 50, startMidpointFraction: 0.5, midpointFraction: 0.5 });",
                "const historical = pinchTimeViewport({ startBarsVisible: 80, startVirtualOffset: 20, startRightGapBars: 6, startDistance: 100, currentDistance: 200, startMidpointFraction: 0.5, midpointFraction: 0.5 });",
                "assert.deepEqual(latestWide, { barsVisible: 40, virtualOffset: 20 });",
                "assert.deepEqual(latestNarrow, { barsVisible: 160, virtualOffset: -80 });",
                "assert.deepEqual(historical, { barsVisible: 40, virtualOffset: 40 });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


