def test_object_layer_redraw_scheduler_coalesces_without_full_chart_fallback(
    tmp_path: Path,
) -> None:
    js = martincall_js_source()
    scheduler = (
        "function requestObjectLayerRedraw"
        + js.split(
            "function requestObjectLayerRedraw",
            1,
        )[1].split("function renderChartsNow", 1)[0]
    )
    script_path = tmp_path / "object-layer-redraw.js"
    script_path.write_text(
        "\n".join(
            (
                "const window = globalThis;",
                "const state = { snapshot: { bars: [{ ts: '2026-07-21T00:00:00Z' }] } };",
                "let pendingObjectLayerReason = '';",
                "let pendingObjectLayerOptions = {};",
                "let objectLayerRedrawFrame = 0;",
                "let nextFrame = 1; const frames = new Map();",
                "const telemetry = {}; const renders = []; const runtimeErrors = []; let fullRenders = 0;",
                "window.mcTelemetryInc = key => { telemetry[key] = Number(telemetry[key] || 0) + 1; };",
                "window.mcTelemetrySet = () => {};",
                "function debugStep() {}",
                "function requestAnimationFrame(callback) { const id = nextFrame++; frames.set(id, callback); return id; }",
                "function cancelAnimationFrame(id) { frames.delete(id); }",
                "function flushFrames() { const callbacks = Array.from(frames.values()); frames.clear(); callbacks.forEach(callback => callback()); }",
                "function renderCharts() { fullRenders += 1; }",
                "function showRuntimeError(error, owner) { runtimeErrors.push([error.message, owner]); }",
                "let renderPriceObjects = (_snapshot, options) => { renders.push({ ...options }); return true; };",
                scheduler,
                "requestObjectLayerRedraw('first', { clear: false });",
                "requestObjectLayerRedraw('second', { force: true });",
                "if (frames.size !== 1 || renders.length !== 0) process.exit(1);",
                "flushFrames();",
                "if (renders.length !== 1 || renders[0].clear !== false || renders[0].force !== true) process.exit(2);",
                "requestObjectLayerRedraw('third', { animate: true });",
                "requestObjectLayerRedraw('immediate', { immediate: true, force: true });",
                "if (frames.size !== 0 || renders.length !== 2 || renders[1].animate !== true || renders[1].force !== true) process.exit(3);",
                "renderPriceObjects = undefined;",
                "requestObjectLayerRedraw('missing', { immediate: true });",
                "if (runtimeErrors.length !== 1 || runtimeErrors[0][1] !== 'objectLayerRender') process.exit(4);",
                "if (fullRenders !== 0) process.exit(5);",
                "if (telemetry['render.objects.requested'] !== 5) process.exit(6);",
                "if (telemetry['render.objects.coalesced'] !== 1) process.exit(7);",
                "if (telemetry['render.objects.immediate'] !== 2) process.exit(8);",
                "if (telemetry['render.objects.rendered'] !== 2) process.exit(9);",
                "if (telemetry['render.objects.error'] !== 1) process.exit(10);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_sentiment_labels_render_typed_roles_without_becoming_action_codes(tmp_path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/30-market-panel-runtime.js").read_text()
    helper = (
        "function sentimentActionLabel"
        + source.split("function sentimentActionLabel", 1)[1].split(
            "function renderDirectionSentimentLight", 1
        )[0]
    )
    script_path = tmp_path / "sentiment-labels.js"
    script_path.write_text(
        'const assert = require("node:assert/strict");\n'
        + helper
        + """
assert.equal(sentimentActionLabel({role: "indicator", action: "ARM"}), "ARM");
assert.equal(sentimentActionLabel({role: "market_context", action: "WATCH"}), "CONTEXT");
for (const [phase, label] of Object.entries({execute: "STRATEGY GO", armed: "STRATEGY ARM", impulse_confirmed: "IMPULSE CONTEXT", impulse_developing: "IMPULSE WATCH"})) {
  assert.equal(sentimentActionLabel({role: "market_context", strategy_active: true, strategy_phase: phase}), label);
}
assert.equal(sentimentActionLabel({role: "institutional_edge", phase: "go", direction: "short"}), "EDGE_GO_SHORT");
assert.equal(sentimentActionLabel({role: "institutional_edge", phase: "watch", direction: "long"}), "EDGE_WATCH_LONG");
assert.equal(sentimentActionLabel({role: "indicator", action: "WATCH", blocked_by_context: true}), "REV WATCH");
assert.equal(sentimentActionLabel({role: "tick_flow", action: "WATCH"}), "CONFIRM");
assert.equal(sentimentActionLabel({role: "institutional_edge", action: "EDGE_GO_SHORT"}), "");
"""
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)
    assert result.returncode == 0, result.stderr


