def test_server_setting_order_ticket_failure_preserves_authoritative_value(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/08-server-storage.js").read_text(encoding="utf-8")
    queue_source = (
        "function queueServerSetting"
        + source.split(
            "function queueServerSetting",
            1,
        )[1]
    )
    script_path = tmp_path / "server-setting-order-ticket-failure.js"
    script_path.write_text(
        "\n".join(
            (
                "const serverSettings = { 'aef:a': 'authoritative' };",
                "const serverSettingQueue = new Map();",
                "const serverSettingLatestMutations = new Map();",
                "const serverSettingFailures = new Map();",
                "let serverSettingFlushTimer = null;",
                "let serverSettingWriterSequence = 0;",
                "let serverSettingChangedAtMs = 0;",
                "const serverSettingWriterHighWaterKey = 'high-water';",
                "const performance = { timeOrigin: 1700000000000, now() { return 1; } };",
                "const window = { clearTimeout() {}, setTimeout() { throw new Error('must not schedule'); } };",
                "function isCurrentClientSettingKey(key) { return String(key || '').startsWith('aef:'); } function isBrowserWritableClientSettingKey(key) { return isCurrentClientSettingKey(key); }",
                "function serverSettingMutationHighWater() { return 0; }",
                "function rawLocalStorageSetItem() { return false; }",
                "function requestErrorMessage(error, fallback) { return error?.message || fallback; }",
                "let saveState = null; function setServerSettingsSaveState(phase, error) { saveState = { phase, error }; }",
                queue_source,
                "const result = queueServerSetting('aef:a', 'optimistic');",
                "console.log(JSON.stringify({ result, value: serverSettings['aef:a'], queued: serverSettingQueue.size, latest: serverSettingLatestMutations.size, saveState }));",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    assert json.loads(result.stdout) == {
        "result": None,
        "value": "authoritative",
        "queued": 0,
        "latest": 0,
        "saveState": {
            "phase": "error",
            "error": "SETTINGS_MUTATION_HIGH_WATER_UNAVAILABLE",
        },
    }


