def test_ibkr_data_notice_distinguishes_quote_warmup_from_missing_live_data(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/30-panels-system-health.js").read_text(
        encoding="utf-8"
    )
    configured_endpoint_source = (
        "function ibkrConfiguredEndpoint()"
        + source.split("function ibkrConfiguredEndpoint()", 1)[1].split(
            "function ibkrDataNotice()", 1
        )[0]
    )
    notice_source = "function ibkrDataNotice()" + source.split("function ibkrDataNotice()", 1)[1]

    assert "quote_missing_routes" in notice_source
    assert "quote_missing_route_fingerprints" not in notice_source
    assert "quote_route_errors" not in notice_source
    assert "quoteSubscriptions > 0 && quoteValues === 0" in notice_source
    assert "!ibkr.live_ok" not in notice_source

    script_path = tmp_path / "ibkr-data-notice-contract.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = { dataSource: 'ibkr', serverSleeping: false, symbol: 'ES', routeFingerprint: 'route-es', settings: { ibkrPort: 7497 }, snapshot: { bars: [], meta: {} }, systemHealth: null };",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function providerCapability() { return true; }",
                "function instrumentRouteFingerprint() { return state.routeFingerprint; }",
                "function effectiveDataQuality() { return { status: 'unknown' }; }",
                "function check(value, message) { if (!value) throw new Error(message); }",
                configured_endpoint_source,
                notice_source,
                "const base = { host: 'host.docker.internal', port: 7497, quote_connected: false, chart_connected: false, history_connected: false, connection_in_progress: { quote: false }, quote_subscriptions: 0, quote_values: 0, quote_missing_routes: [], live_issue: '' };",
                "state.systemHealth = { ibkr: { ...base, connection_in_progress: { quote: true } }, runtime_settings: {} };",
                "let notice = ibkrDataNotice();",
                "check(notice.includes('connecting') && notice.includes('warming up'), 'an in-progress quote connection must be presented as warmup');",
                "check(!notice.includes('market-data permissions') && !notice.includes('competing sessions'), 'warmup must not claim a permission or competing-session fault');",
                "state.systemHealth.ibkr = { ...base, chart_connected: true };",
                "notice = ibkrDataNotice();",
                "check(notice.includes('reconnecting') && notice.includes('warming up'), 'a down quote session beside a live chart session must be presented as reconnecting');",
                "check(!notice.includes('market-data permissions') && !notice.includes('competing sessions'), 'reconnect must not claim a missing-data fault');",
                "state.systemHealth.ibkr = { ...base, quote_connected: true };",
                "check(ibkrDataNotice() === '', 'a connected quote session without subscriptions has no missing-data demand');",
                "state.systemHealth.ibkr = { ...base, quote_connected: true, quote_subscriptions: 2 };",
                "notice = ibkrDataNotice();",
                "check(notice.includes('live bid/ask/last is not arriving yet'), 'subscribed connected zero-value state must show the missing-data warning');",
                "check(notice.includes('market-data permissions') && notice.includes('competing sessions'), 'only the real missing-data state may show fault guidance');",
                "state.systemHealth.ibkr = { ...base, quote_connected: true, quote_subscriptions: 2, quote_values: 1, quote_missing_routes: ['route-es'] };",
                "notice = ibkrDataNotice();",
                "check(notice.includes('not arriving for ES'), 'the canonical missing route must produce the route-specific warning');",
                "state.systemHealth.ibkr = { ...base, quote_connected: true, quote_subscriptions: 2, quote_values: 1, quote_missing_route_fingerprints: ['route-es'], quote_route_errors: { 'route-es': 'legacy error' } };",
                "check(ibkrDataNotice() === '', 'retired browser-only route fields must not affect the warning');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


