def test_gex_history_render_lane_filters_capture_mode_and_actual_entitlement(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/50-overlays-gex-history.js").read_text(
        encoding="utf-8"
    )
    helper_source = (
        "function gexHistoryRenderLane"
        + source.split(
            "function gexHistoryRenderLane",
            1,
        )[1].split("function gexHistorySnapshotEndTs", 1)[0]
    )
    script_path = tmp_path / "gex-history-render-lane.js"
    script_path.write_text(
        "\n".join(
            (
                "let captureMode = 'live';",
                "const state = { indicators: { gexContext: { historyView: 'last' } } };",
                "function effectiveGexContextMode() { return captureMode; }",
                "function gexHistoryView(value) { return ['last', '1d', '2d'].includes(value) ? value : '1d'; }",
                "function gexMarketDataEntitlement(payload) { return ['live', 'frozen', 'delayed', 'delayed_frozen'].includes(payload?.market_data_entitlement) ? payload.market_data_entitlement : ''; }",
                "const CHART_VIEW_DAY_MS = 86400000;",
                "function gexHistoryTimestampMs(item) { return Number.isInteger(item?.timestamp_unix_ms) ? item.timestamp_unix_ms : null; }",
                "function gexHistorySnapshotTs(item) { return gexHistoryTimestampMs(item); }",
                helper_source,
                "function gexHistorySnapshotEndTs(item) { return item.timestamp_unix_ms; }",
                "function gexHistoryIntersectsVisible(item, window) { const ts = gexHistoryTimestampMs(item); return Number.isFinite(ts) && ts >= window.start && ts <= window.end; }",
                "const latestTs = Date.parse('2026-07-30T12:00:00.000Z');",
                "const history = [",
                "  { id: 'request-delayed', capture_mode: 'request', market_data_entitlement: 'delayed', comparison_scope: { lane: 'exact' }, timestamp_unix_ms: latestTs },",
                "  { id: 'stream-delayed-old', capture_mode: 'live', market_data_entitlement: 'delayed', comparison_scope: { lane: 'old' }, timestamp_unix_ms: latestTs - 2 * CHART_VIEW_DAY_MS },",
                "  { id: 'stream-delayed', capture_mode: 'live', market_data_entitlement: 'delayed', comparison_scope: { lane: 'exact' }, timestamp_unix_ms: latestTs - 6 * 60 * 60 * 1000 },",
                "  { id: 'stream-delayed-rebased', capture_mode: 'live', market_data_entitlement: 'delayed', comparison_scope: { lane: 'rebased' }, timestamp_unix_ms: latestTs },",
                "  { id: 'stream-realtime', capture_mode: 'live', market_data_entitlement: 'live', comparison_scope: { lane: 'exact' }, timestamp_unix_ms: latestTs },",
                "  { id: 'stream-unknown', capture_mode: 'live', market_data_entitlement: 'unknown', comparison_scope: { lane: 'exact' }, timestamp_unix_ms: latestTs },",
                "];",
                "const gex = { market_data_entitlement: 'delayed', comparison_scope: { lane: 'exact' }, history };",
                "const ids = value => value.map(item => item.id).join(',');",
                "if (ids(gexHistoryRenderLane(gex)) !== 'stream-delayed-rebased') process.exit(1);",
                "state.indicators.gexContext.historyView = '1d';",
                "if (ids(gexHistoryRenderLane(gex)) !== 'stream-delayed,stream-delayed-rebased') process.exit(2);",
                "state.indicators.gexContext.historyView = '2d';",
                "if (ids(gexHistoryRenderLane(gex)) !== 'stream-delayed-old,stream-delayed,stream-delayed-rebased') process.exit(3);",
                "state.indicators.gexContext.historyView = 'last';",
                "captureMode = 'request';",
                "if (ids(gexHistoryRenderLane(gex)) !== 'request-delayed') process.exit(4);",
                "captureMode = 'live';",
                "if (ids(gexHistoryRenderLane({ ...gex, market_data_entitlement: 'live' })) !== 'stream-realtime') process.exit(5);",
                "if (history.length !== 6) process.exit(6);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    assert "gexComparisonScopesEqual" not in helper_source


