def test_chart_only_market_uses_confirmed_provider_history_path(monkeypatch) -> None:
    _patch_persisted_lookup(monkeypatch)
    store = _client_watchlist_store([], {"aef:ibkrPort": "7497"})
    monkeypatch.setattr(
        ui_client_settings,
        "_postgres_store",
        lambda: store,
    )
    monkeypatch.setattr(ui_app, "default_postgres_store", lambda: store)
    calls = {}

    async def fake_chart_load(provider, instrument, interval, range_, timeout, **kwargs):
        assert provider == "ibkr"
        calls.update(
            {
                "symbol": instrument["display"],
                "interval": interval,
                "range": range_,
                "timeout": timeout,
                "refresh_provider": kwargs["refresh_provider"],
            }
        )
        return _confirmed_history(
            [
                Bar(
                    symbol="NVDA",
                    ts=datetime(2026, 6, 1, 18, 0, tzinfo=UTC),
                    open=223.0,
                    high=224.0,
                    low=222.5,
                    close=223.5,
                    volume=1000,
                    timeframe="5m",
                    source="test",
                )
            ]
        )

    monkeypatch.setattr(ui_market_actions, "coalesced_load_confirmed_chart_bars", fake_chart_load)
    market_endpoint = app_route_endpoint("/api/market")
    route = route_instrument(ibkr_stock_payload("NVDA", con_id=4815747))

    snapshot = asyncio.run(
        market_endpoint(
            _market_request(),
            instrument_id=route.instrument_id,
            expected_route_fingerprint=route.fingerprint,
            interval="5m",
            range_="5d",
            chart_only=True,
        )
    )

    assert calls == {
        "symbol": "NVDA",
        "interval": "5m",
        "range": "5d",
        "timeout": 2.0,
        "refresh_provider": False,
    }
    assert snapshot["meta"]["chart_only"] is True

    calls.clear()
    deep_snapshot = asyncio.run(
        market_endpoint(
            _market_request(),
            instrument_id=route.instrument_id,
            expected_route_fingerprint=route.fingerprint,
            interval="5m",
            range_="1mo",
            chart_only=True,
        )
    )

    assert calls == {
        "symbol": "NVDA",
        "interval": "5m",
        "range": "1mo",
        "timeout": 2.0,
        "refresh_provider": False,
    }
    assert deep_snapshot["meta"]["chart_only"] is True


def test_front_facing_market_endpoint_uses_confirmed_history_then_db_analysis(monkeypatch) -> None:
    _patch_persisted_lookup(monkeypatch)
    store = _client_watchlist_store([], {"aef:ibkrPort": "7497"})
    monkeypatch.setattr(
        ui_client_settings,
        "_postgres_store",
        lambda: store,
    )
    monkeypatch.setattr(ui_app, "default_postgres_store", lambda: store)
    chart_calls = {}
    full_calls = {}

    async def fake_chart_load(provider, instrument, interval, range_, timeout, **kwargs):
        assert provider == "ibkr"
        chart_calls.update(
            {
                "symbol": instrument["display"],
                "interval": interval,
                "range": range_,
                "timeout": timeout,
            }
        )
        return _confirmed_history(
            [
                Bar(
                    symbol="SPY",
                    ts=datetime(2026, 6, 1, 18, 0, tzinfo=UTC),
                    open=741.0,
                    high=742.0,
                    low=740.5,
                    close=741.5,
                    volume=1000,
                    timeframe="5m",
                    source="ibkr:db-cache",
                )
            ]
        )

    async def fake_snapshot(**kwargs):
        full_calls.update(kwargs)
        return {
            "ok": True,
            "symbol": kwargs["instrument"]["display"],
            "bars": [{"source": "ibkr:db-cache"}],
            "meta": {"source": "ibkr:db-cache"},
        }

    monkeypatch.setattr(ui_market_actions, "coalesced_load_confirmed_chart_bars", fake_chart_load)
    monkeypatch.setattr(ui_market_actions, "async_build_market_snapshot_from_db", fake_snapshot)
    market_endpoint = app_route_endpoint("/api/market")
    route = route_instrument(ibkr_stock_payload("SPY", con_id=756733))

    chart_snapshot = asyncio.run(
        market_endpoint(
            _market_request(),
            instrument_id=route.instrument_id,
            expected_route_fingerprint=route.fingerprint,
            interval="5m",
            range_="3d",
            chart_only=True,
            queue_analysis=True,
            analysis_client_id="client-1",
            analysis_lease_sequence=1,
        )
    )
    full_snapshot = asyncio.run(
        market_endpoint(
            _market_request(),
            instrument_id=route.instrument_id,
            expected_route_fingerprint=route.fingerprint,
            interval="5m",
            range_="3d",
            chart_only=False,
        )
    )

    assert chart_calls == {"symbol": "SPY", "interval": "5m", "range": "3d", "timeout": 2.0}
    assert "live_refresh" not in full_calls
    chart_sources = {str(bar.get("source") or "") for bar in chart_snapshot.get("bars", [])}
    full_sources = {str(bar.get("source") or "") for bar in full_snapshot.get("bars", [])}
    assert chart_sources == {"ibkr:db-cache"}
    assert full_sources == {"ibkr:db-cache"}


