def test_scheduled_hourly_preview_and_countdown_use_server_slot_not_epoch_phase(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-live-candle-sync.js").read_text(
        encoding="utf-8"
    )
    timestamp_source = (
        "function timestampKey(ts)"
        + source.split(
            "function timestampKey(ts)",
            1,
        )[1].split("function isValidChartStreamPayload", 1)[0]
    )
    revision_source = (
        "function streamBarRevisionMs(bar)"
        + source.split(
            "function streamBarRevisionMs(bar)",
            1,
        )[1].split("function streamBarOrder", 1)[0]
    )
    interval_source = (
        "function intervalMinutesFromState()"
        + source.split(
            "function intervalMinutesFromState()",
            1,
        )[1].split("function latestBarLagsCurrentSlot", 1)[0]
    )
    key_source = (
        "function liveBarPreviewKey(timeframe = state.timeframe)"
        + source.split(
            "function liveBarPreviewKey(timeframe = state.timeframe)",
            1,
        )[1].split("function rememberLiveBarPreview", 1)[0]
    )
    restore_source = (
        "function restoreLiveBarPreview(snapshot)"
        + source.split(
            "function restoreLiveBarPreview(snapshot)",
            1,
        )[1].split("function applyChartBarsToSnapshot", 1)[0]
    )
    script_path = tmp_path / "scheduled-preview-phase.js"
    script_path.write_text(
        "\n".join(
            (
                "const CHART_STREAM_STALE_MS = 20000;",
                "let fixedNow = Date.parse('2026-07-20T13:47:00.000Z');",
                "Date.now = () => fixedNow;",
                "const state = { instrumentId: 'ibkr|stock|SPY', timeframe: '60m', dataSource: 'ibkr', transport: { chart: { expectedLiveSlot: '2026-07-20T13:30:00.000Z', expectedLiveClose: '2026-07-20T14:00:00.000Z' } }, liveBarPreviewCache: {}, chartBarIndexBars: null };",
                "function instrumentRouteFingerprint() { return 'route-fingerprint'; }",
                "function barIsLivePreview(bar) { return Boolean(bar && (bar.closed === false || ['forming', 'awaiting_provider_confirmation'].includes(String(bar.state || '')))); }",
                "function barIsGapPlaceholder(bar) { return Boolean(bar && (bar.missing || bar.data_gap || bar.preview_kind === 'gap_placeholder')); }",
                "function resolveStreamBar(existing, incoming) { return existing?.closed === true ? existing : { ...incoming }; }",
                "function normalizeSnapshotBarSlots(snapshot) { return snapshot; }",
                "function alignChartGuidesToBars() {}",
                "function chartStreamOpen() { return false; }",
                "function syncSnapshotPreviewMeta() {}",
                "function drawingTimestampIdentity(value) { const parsed = Date.parse(value || ''); return Number.isFinite(parsed) ? String(parsed) : ''; }",
                timestamp_source,
                revision_source,
                interval_source,
                key_source,
                restore_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const key = liveBarPreviewKey();",
                "const preview = { ts: '2026-07-20T13:30:00.000Z', bar_slot: 160, bar_slot_authoritative: true, closed: false, state: 'forming', preview_kind: 'provider_bar', preview_ts: '2026-07-20T13:46:55.000Z' };",
                "state.liveBarPreviewCache[key] = [preview];",
                "const snapshot = { bars: [{ ts: '2026-07-20T12:30:00.000Z', bar_slot: 100, closed: true, state: 'confirmed' }], meta: { timeframe: '60m' } };",
                "restoreLiveBarPreview(snapshot);",
                "check(snapshot.bars.some(bar => bar.ts === preview.ts), '13:30 opening-partial provider bucket must survive restore at 13:47');",
                "check(candleCountdownText(fixedNow) === '13:00', '13:30 opening-partial bucket must count down to typed 14:00 close');",
                "state.transport.chart.expectedLiveClose = '';",
                "check(candleCountdownText(fixedNow) === '', 'countdown must be unavailable without an exact server close');",
                "state.transport.chart.expectedLiveSlot = '';",
                "check(candleCountdownText(fixedNow) === '', 'countdown must be unavailable without an exact server slot');",
                "const freshSnapshot = { bars: [{ ts: '2026-07-20T12:30:00.000Z', bar_slot: 100, closed: true }], meta: { timeframe: '60m' } };",
                "state.liveBarPreviewCache[key] = [preview];",
                "restoreLiveBarPreview(freshSnapshot);",
                "check(freshSnapshot.bars.some(bar => bar.ts === preview.ts), 'fresh server preview timestamp may bridge until expected slot arrives');",
                "const staleSnapshot = { bars: [{ ts: '2026-07-20T12:30:00.000Z', bar_slot: 100, closed: true }], meta: { timeframe: '60m' } };",
                "state.liveBarPreviewCache[key] = [{ ...preview, preview_ts: '2026-07-20T12:00:00.000Z' }];",
                "restoreLiveBarPreview(staleSnapshot);",
                "check(!staleSnapshot.bars.some(bar => bar.ts === preview.ts), 'stale preview must not be restored without an exact slot');",
                "fixedNow = Date.parse('2026-07-20T14:35:00.000Z');",
                "state.transport.chart.expectedLiveSlot = '2026-07-20T13:30:00.000Z';",
                "state.transport.chart.expectedLiveClose = '2026-07-20T14:00:00.000Z';",
                "const nextPreview = { ...preview, ts: '2026-07-20T14:00:00.000Z', bar_slot: 220, preview_ts: '2026-07-20T14:34:55.000Z' };",
                "state.liveBarPreviewCache[key] = [nextPreview];",
                "const staleGapSnapshot = { bars: [{ ts: '2026-07-20T13:30:00.000Z', bar_slot: 160, closed: false, state: 'awaiting_provider_confirmation', preview_kind: 'gap_placeholder', missing: true }], meta: { timeframe: '60m' } };",
                "restoreLiveBarPreview(staleGapSnapshot);",
                "check(staleGapSnapshot.bars.some(bar => bar.ts === nextPreview.ts), 'fresh next forming slot must advance a closed stale expected gap');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_quote_preview_promotes_provider_bucket_bounds_atomically(tmp_path: Path) -> None:
    core_source = Path("src/aef_terminal/ui/assets/js/10-core-state.js").read_text(encoding="utf-8")
    source = Path("src/aef_terminal/ui/assets/js/20-live-candle-sync.js").read_text(
        encoding="utf-8"
    )
    identity_source = (
        "function exactIdentityText"
        + core_source.split(
            "function exactIdentityText",
            1,
        )[1].split("const THEME_CSS_VARIABLES", 1)[0]
    )
    normalize_source = (
        "function normalizeChartStreamBarForScope(bar, expectedScope, streamOrder = null)"
        + source.split(
            "function normalizeChartStreamBarForScope(bar, expectedScope, streamOrder = null)",
            1,
        )[1].split("function streamBarKind", 1)[0]
    )
    queue_source = (
        'function queueChartBars(streamBars, streamKey = "", options = {})'
        + source.split(
            'function queueChartBars(streamBars, streamKey = "", options = {})',
            1,
        )[1].split("function renderLoadingCanvases", 1)[0]
    )
    apply_source = (
        "function applyChartBarsToSnapshot(streamBars, options = {})"
        + source.split(
            "function applyChartBarsToSnapshot(streamBars, options = {})",
            1,
        )[1].split("function flushQueuedChartBars", 1)[0]
    )
    script_path = tmp_path / "quote-preview-expected-bounds.js"
    script_path.write_text(
        "\n".join(
            (
                "const window = {};",
                "const state = { instrumentId: 'ibkr|stock|SPY', timeframe: '60m', dataSource: 'ibkr', chartBarQueue: null, transport: { chart: { expectedLiveSlot: '', expectedLiveClose: '' } }, snapshot: null };",
                identity_source,
                "function instrumentRouteFingerprint() { return 'route-fingerprint'; }",
                'function barIsGapPlaceholder(bar) { return Boolean(bar?.missing || bar?.data_gap || bar?.preview_kind === "gap_placeholder" || bar?.source === "gap-placeholder"); }',
                "function barIsConfirmedClosed(bar) { return bar?.closed === true; }",
                "function timestampKey(ts) { return new Date(Date.parse(ts)).toISOString(); }",
                "function resolveStreamBar(existing, incoming) { return incoming || existing; }",
                "function flushQueuedChartBars() {}",
                "function queueMicrotask() {}",
                "function providerCapability() { return true; }",
                normalize_source,
                queue_source,
                apply_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const preview = { instrument_id: state.instrumentId, provider_symbol: 'ES', route_fingerprint: instrumentRouteFingerprint(), timeframe: state.timeframe, ts: '2026-07-20T13:30:00.000Z', expected_close: '2026-07-20T14:00:00.000Z', open: 100, high: 102, low: 99, close: 101, volume: 0, source: 'ibkr:trade-preview', closed: false, state: 'forming', authoritative: false, commit_pending: false };",
                "queueChartBars([preview], 'quote-key', { promoteExpectedBounds: true, streamEpoch: 1, streamSeq: 1 });",
                "check(state.chartBarQueue.expectedLiveSlot === preview.ts, 'quote preview open must be promoted from its accepted bar timestamp');",
                "check(state.chartBarQueue.expectedLiveClose === preview.expected_close, 'quote preview close must be promoted with the open');",
                "const older = { ...preview, ts: '2026-07-20T12:30:00.000Z', expected_close: '2026-07-20T13:30:00.000Z' };",
                "queueChartBars([older], 'quote-key', { promoteExpectedBounds: true, streamEpoch: 1, streamSeq: 2 });",
                "check(state.chartBarQueue.expectedLiveSlot === preview.ts && state.chartBarQueue.expectedLiveClose === preview.expected_close, 'older quote bucket must not regress queued bounds');",
                "state.transport.chart.expectedLiveSlot = preview.ts;",
                "state.transport.chart.expectedLiveClose = preview.expected_close;",
                "applyChartBarsToSnapshot([], { expectedLiveSlot: '2026-07-20T14:00:00.000Z' });",
                "check(state.transport.chart.expectedLiveSlot === '' && state.transport.chart.expectedLiveClose === '', 'partial expected bounds must clear atomically');",
                "state.transport.chart.expectedLiveSlot = preview.ts;",
                "state.transport.chart.expectedLiveClose = preview.expected_close;",
                "applyChartBarsToSnapshot([], { expectedLiveSlot: older.ts, expectedLiveClose: older.expected_close });",
                "check(state.transport.chart.expectedLiveSlot === preview.ts && state.transport.chart.expectedLiveClose === preview.expected_close, 'older complete bounds must not regress accepted state');",
                "applyChartBarsToSnapshot([], { expectedLiveSlot: '2026-07-20T14:00:00.000Z', expectedLiveClose: '2026-07-20T15:00:00.000Z' });",
                "check(state.transport.chart.expectedLiveSlot === '2026-07-20T14:00:00.000Z' && state.transport.chart.expectedLiveClose === '2026-07-20T15:00:00.000Z', 'newer complete bounds must advance together');",
                "applyChartBarsToSnapshot([], { expectedLiveSlot: null, expectedLiveClose: null });",
                "check(state.transport.chart.expectedLiveSlot === '' && state.transport.chart.expectedLiveClose === '', 'explicit empty pair must clear together');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_chart_guides_follow_live_bar_axis_without_calculating_provisional_values(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(encoding="utf-8")
    align_source = (
        "function alignChartGuidesToBars"
        + source.split(
            "function alignChartGuidesToBars",
            1,
        )[1].split("function sliceSnapshotAlignedRange", 1)[0]
    )
    script_path = tmp_path / "chart-guide-live-alignment.js"
    script_path.write_text(
        "\n".join(
            (
                "function timestampKey(ts) { return new Date(Date.parse(ts)).toISOString(); }",
                align_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                'const t0 = "2026-07-19T07:00:00.000Z";',
                'const t1 = "2026-07-19T07:05:00.000Z";',
                'const t2 = "2026-07-19T07:10:00.000Z";',
                'const t3 = "2026-07-19T07:15:00.000Z";',
                "const confirmed = [{ ts: t0 }, { ts: t1 }];",
                'const withForming = [...confirmed, { ts: t2, closed: false, state: "forming" }];',
                'const snapshot = { bars: withForming, chart_guides: { ema: { "20": [100, 101], "233": [90, 91] }, vwap: [{ vwap: 99, sigma: 1 }, { vwap: 100, sigma: 2 }], meta: { bar_count: 2, calculation_bar_count: 2 } } };',
                "alignChartGuidesToBars(snapshot, confirmed, withForming);",
                'check(snapshot.chart_guides.ema["20"].length === 3, "EMA must match the live display axis");',
                'check(snapshot.chart_guides.ema["20"][0] === 100 && snapshot.chart_guides.ema["20"][1] === 101, "confirmed EMA values must remain unchanged");',
                'check(snapshot.chart_guides.ema["20"][2] === null && snapshot.chart_guides.ema["233"][2] === null, "forming bar must not enter EMA calculation");',
                'check(snapshot.chart_guides.vwap.length === 3 && snapshot.chart_guides.vwap[2].vwap === null && snapshot.chart_guides.vwap[2].sigma === null, "forming bar must receive an unavailable VWAP point");',
                'check(snapshot.chart_guides.meta.bar_count === 3 && snapshot.chart_guides.meta.calculation_bar_count === 2, "display count must advance without changing calculation count");',
                'const withInsertedGap = [{ ts: t0 }, { ts: "2026-07-19T07:02:30.000Z", missing: true }, { ts: t1 }, withForming[2]];',
                "alignChartGuidesToBars(snapshot, withForming, withInsertedGap);",
                'check(snapshot.chart_guides.ema["20"].join(",") === "100,,101,", "timestamp projection must survive an internal live insertion");',
                'check(snapshot.chart_guides.vwap[1].vwap === null && snapshot.chart_guides.vwap[3].vwap === null, "gap and forming slots must remain unavailable");',
                "const fullAxis = [{ ts: t0 }, { ts: t1 }, { ts: t2 }, { ts: t3, closed: false, state: 'forming' }];",
                "const fallbackGuides = { ema: { '20': [90, 91, 92, null], '233': [80, 81, 82, null] }, vwap: [{ vwap: 89, sigma: 1 }, { vwap: 90, sigma: 1 }, { vwap: 91, sigma: 1 }, { vwap: null, sigma: null }] };",
                "const partialSnapshot = { bars: fullAxis, chart_guides: { ema: { '20': [201, 202], '233': [null, 302] }, vwap: [{ vwap: 200, sigma: 2 }, { vwap: 201, sigma: 2 }], meta: { bar_count: 2, calculation_bar_count: 2 } } };",
                "alignChartGuidesToBars(partialSnapshot, [{ ts: t1 }, { ts: t2 }], fullAxis, fallbackGuides);",
                "check(partialSnapshot.chart_guides.ema['20'].join(',') === '90,201,202,', 'fresh partial analysis must replace the matching tail and preserve older guide values');",
                "check(partialSnapshot.chart_guides.ema['233'][1] === null, 'a source-owned unavailable value must not revive a stale fallback');",
                "check(partialSnapshot.chart_guides.vwap[0].vwap === 89 && partialSnapshot.chart_guides.vwap[2].vwap === 201, 'VWAP must preserve only timestamps outside the fresh analysis window');",
                "check(partialSnapshot.chart_guides.ema['20'][3] === null && partialSnapshot.chart_guides.vwap[3].vwap === null, 'forming tail must remain unavailable after partial analysis merge');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_analysis_only_chart_response_immediately_merges_fresh_chart_guides(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(encoding="utf-8")
    align_source = (
        "function alignChartGuidesToBars"
        + source.split("function alignChartGuidesToBars", 1)[1].split(
            "function mergeChartGuidesFromChartSnapshot", 1
        )[0]
    )
    merge_source = (
        "function mergeChartGuidesFromChartSnapshot"
        + source.split("function mergeChartGuidesFromChartSnapshot", 1)[1].split(
            "function sliceKnownBarAlignedArray", 1
        )[0]
    )
    analysis_only_branch = source.split(
        "if (options.analysisOnly && snapshot.meta?.chart_only)", 1
    )[1].split("if (!options.historyLoad && bars.length)", 1)[0]
    assert "mergeChartGuidesFromChartSnapshot(snapshot" in analysis_only_branch
    assert "loadMarketAnalysisSnapshot(" in analysis_only_branch
    assert "touchChartBarsVersion" not in merge_source

    script_path = tmp_path / "analysis-only-chart-guides.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const t0 = '2026-08-13T09:18:00.000Z';",
                "const t1 = '2026-08-13T09:23:00.000Z';",
                "const t2 = '2026-08-13T09:28:00.000Z';",
                "const oldGuides = { ema: { '20': [100, null, 999], '233': [90, null, 999] }, vwap: [{ vwap: 99, sigma: 1 }, { vwap: null, sigma: null }, { vwap: 999, sigma: 9 }], meta: { generation: 'old', bar_count: 3, calculation_bar_count: 1 } };",
                "const state = { instrumentId: 'instrument-a', timeframe: '5m', range: '5d', snapshot: { bars: [{ ts: t0, closed: true }, { ts: t1, closed: true }, { ts: t2, closed: false, preview_kind: 'broker_trade' }], chart_guides: oldGuides, indicators: { channel_master: { status: 'ready' } }, meta: { instrument_id: 'instrument-a', route_fingerprint: 'route-a', timeframe: '5m', chart_range: '5d', chart_canonical_revision: 30, analysis_parent_canonical_revision: 29 } }, lastIndicatorAnalysisMergedVersion: 'old-analysis-owner' };",
                "const events = [];",
                "function timestampKey(value) { return value ? new Date(Date.parse(value)).toISOString() : ''; }",
                "function exactIdentityText(value) { return String(value || ''); }",
                "function instrumentRouteFingerprint() { return 'route-a'; }",
                "function snapshotMatchesCurrentRoute() { return true; }",
                "function barIsLivePreview(bar) { return bar?.closed === false; }",
                "function snapshotIdentity(snapshot) { const meta = snapshot?.meta || {}; return { instrumentId: exactIdentityText(meta.instrument_id), routeFingerprint: exactIdentityText(meta.route_fingerprint), timeframe: String(meta.timeframe || state.timeframe || '').trim(), range: String(meta.chart_range || state.range || '').trim() }; }",
                "function sameSnapshotIdentity(left, right) { const a = snapshotIdentity(left); const b = snapshotIdentity(right); return Boolean(a.instrumentId && a.instrumentId === b.instrumentId) && Boolean(a.routeFingerprint && a.routeFingerprint === b.routeFingerprint) && a.timeframe === b.timeframe && (!a.range || !b.range || a.range === b.range); }",
                "let retainedGuideCalls = 0; function retainCanonicalLiveTailChartGuides() { retainedGuideCalls += 1; return true; }",
                "function renderCharts(snapshot, options) { events.push({ type: 'render', generation: snapshot.chart_guides.meta.generation, options }); }",
                align_source,
                merge_source,
                "const fresh = { bars: [{ ts: t0 }, { ts: t1 }], chart_guides: { ema: { '20': [101, 102], '233': [91, 92] }, vwap: [{ vwap: 100, sigma: 1 }, { vwap: 101, sigma: 1 }], meta: { generation: 'fresh-r30', bar_count: 2, calculation_bar_count: 2 } }, meta: { chart_only: true, instrument_id: 'instrument-a', route_fingerprint: 'route-a', timeframe: '5m', chart_range: '5d', chart_canonical_revision: 30 } };",
                "const snapshot = fresh;",
                "const options = { analysisOnly: true, analysisRequireBarTs: t1, analysisCanonicalRevision: 30 };",
                "const queueAnalysis = true;",
                "const requestInstrumentId = 'instrument-a'; const requestRouteFingerprint = 'route-a'; const requestSymbol = 'A'; const requestSource = 'moex'; const requestTimeframe = '5m'; const range = '5d';",
                "function clearUiNotice() { events.push({ type: 'notice-clear' }); }",
                "function marketAnalysisCanPoll() { return true; }",
                "function loadMarketAnalysisSnapshot() { events.push({ type: 'analysis-poll' }); }",
                "function applyAnalysisOnlyBranch() { if (options.analysisOnly && snapshot.meta?.chart_only)"
                + analysis_only_branch
                + " return -1; }",
                "assert.equal(applyAnalysisOnlyBranch(), 0);",
                "assert.deepEqual(state.snapshot.chart_guides.ema['20'], [101, 102, null]);",
                "assert.deepEqual(state.snapshot.chart_guides.ema['233'], [91, 92, null]);",
                "assert.deepEqual(state.snapshot.chart_guides.vwap.map(item => item.vwap), [100, 101, null]);",
                "assert.equal(state.snapshot.chart_guides.meta.generation, 'fresh-r30');",
                "assert.equal(state.snapshot.chart_guides.meta.bar_count, 3);",
                "assert.deepEqual(state.snapshot.indicators, { channel_master: { status: 'ready' } }, 'guide-only merge must preserve heavy analysis');",
                "assert.equal(state.lastIndicatorAnalysisMergedVersion, 'old-analysis-owner', 'fast guides must not claim heavy-analysis ownership');",
                "assert.equal(retainedGuideCalls, 1, 'accepted fresh guides must update the canonical live-tail owner');",
                "assert.deepEqual(events.map(item => item.type), ['notice-clear', 'render', 'analysis-poll'], 'fresh guides must render before the heavy-analysis poll starts');",
                "assert.deepEqual(events[1], { type: 'render', generation: 'fresh-r30', options: { reason: 'chart-guides' } });",
                "const stale = { ...fresh, chart_guides: { ...fresh.chart_guides, meta: { ...fresh.chart_guides.meta, generation: 'stale-r29' } }, meta: { ...fresh.meta, chart_canonical_revision: 29 } };",
                "assert.equal(mergeChartGuidesFromChartSnapshot(stale, { requireBarTs: t1, requireCanonicalRevision: 30 }), false, 'stale canonical guide response must fail closed');",
                "assert.equal(mergeChartGuidesFromChartSnapshot(stale, { requireBarTs: t1 }), false, 'canonical fence must hold even without an explicit required revision');",
                "const wrongScope = { ...fresh, meta: { ...fresh.meta, route_fingerprint: 'route-b' } };",
                "assert.equal(mergeChartGuidesFromChartSnapshot(wrongScope, { requireBarTs: t1, requireCanonicalRevision: 30 }), false, 'guide response from another exact route must fail closed');",
                "assert.equal(mergeChartGuidesFromChartSnapshot(fresh, { requireBarTs: t2, requireCanonicalRevision: 30 }), false, 'response not covering required confirmed bar must fail closed');",
                "assert.equal(events.filter(item => item.type === 'render').length, 1, 'rejected guide payloads must not redraw');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


