def test_fetch_json_timeout_covers_response_body_and_preserves_upstream_abort(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/15-fetch-json.js").read_text(encoding="utf-8")
    abort_source = (
        "function sharedFetchAbortError()"
        + source.split(
            "function sharedFetchAbortError()",
            1,
        )[1].split("function consumeSharedJsonRequest", 1)[0]
    )
    fetch_source = (
        "async function fetchJson(url, options = {})"
        + source.split(
            "async function fetchJson(url, options = {})",
            1,
        )[1]
    )
    script_path = tmp_path / "fetch-json-timeout.js"
    script_path.write_text(
        "\n".join(
            (
                "const inFlightJsonRequests = new Map();",
                "const window = { setTimeout, clearTimeout, mcTelemetryInc() {}, mcTelemetryMax() {} };",
                "function fetchJsonDedupeKey() { return ''; }",
                "function readSharedFetchEnvelope() { return null; }",
                "function writeSharedFetchEnvelope() {}",
                "function normalizeErrorPayload(value) { return value; }",
                "function apiErrorMessage(_value, fallback) { return fallback; }",
                abort_source,
                "async function fetch(url, options) {",
                "  if (url === '/intentional') { const error = new Error('aborted'); error.name = 'AbortError'; throw error; }",
                "  return { ok: true, status: 200, statusText: 'OK', text: () => new Promise((_resolve, reject) => setTimeout(() => { const error = new Error('body aborted'); error.name = 'AbortError'; reject(error); }, 20)) };",
                "}",
                fetch_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "(async () => {",
                "  let timeoutError = null;",
                "  try { await fetchJson('/body-timeout', { timeoutMs: 5 }); } catch (error) { timeoutError = error; }",
                "  check(timeoutError?.name === 'TimeoutError', 'body-read abort must be classified as timeout');",
                "  const upstream = new AbortController(); upstream.abort();",
                "  let upstreamError = null;",
                "  try { await fetchJson('/intentional', { signal: upstream.signal, timeoutMs: 50 }); } catch (error) { upstreamError = error; }",
                "  check(upstreamError?.name === 'AbortError', 'intentional upstream abort must remain AbortError');",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


