def test_history_expansion_restores_exact_left_edge_anchor_without_channel_slot_shift(
    tmp_path: Path,
) -> None:
    navigation_source = Path("src/aef_terminal/ui/assets/js/59-chart-navigation.js").read_text(
        encoding="utf-8"
    )
    anchor_index_source = (
        "function historyAnchorIndex"
        + navigation_source.split(
            "function historyAnchorIndex",
            1,
        )[1].split("function applyHistoryViewportAnchor", 1)[0]
    )
    apply_anchor_source = (
        "function applyHistoryViewportAnchor"
        + navigation_source.split(
            "function applyHistoryViewportAnchor",
            1,
        )[1].split("function updateChartNavigationControls", 1)[0]
    )
    viewport_anchor_source = (
        "function historyViewportAnchor"
        + navigation_source.split(
            "function historyViewportAnchor",
            1,
        )[1].split("function historyAnchorIndex", 1)[0]
    )
    script_path = tmp_path / "history-anchor.js"
    script_path.write_text(
        "\n".join(
            (
                "const DEFAULT_BARS_VISIBLE = 24;",
                "const MAX_BARS_VISIBLE = 10000;",
                "const DEFAULT_RIGHT_GAP_BARS = 0;",
                "const view = { barsVisible: 24, offset: 6, followLatest: false, historyPullOffsetBars: 0, dragActive: false, dragCurrentDeltaBars: 0, dragStartRightGapBars: 0, dragStartOffset: 0, dragStartHistoryPullOffsetBars: 0 };",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function timestampKey(ts) { return new Date(Date.parse(ts)).toISOString(); }",
                "function maxOffsetFor(snapshot) { return Math.max(snapshot.bars.length - view.barsVisible, 0); }",
                "function visibleBars(snapshot) { const end = snapshot.bars.length - view.offset; const start = Math.max(end - view.barsVisible, 0); return { bars: snapshot.bars.slice(start, end), start, end }; }",
                anchor_index_source,
                apply_anchor_source,
                viewport_anchor_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const baseMs = Date.parse('2026-07-01T00:00:00.000Z');",
                "const allBars = Array.from({ length: 51 }, (_item, index) => ({ ts: new Date(baseMs + index * 300000).toISOString(), bar_slot: index }));",
                "const before = { bars: allBars.slice(20, 50) };",
                "const anchor = historyViewportAnchor(before);",
                "check(anchor.ts === allBars[20].ts && anchor.screenIndex === 0, 'left-edge timestamp and screen index must be exact');",
                "const expanded = { bars: allBars.slice() };",
                "check(historyAnchorIndex(expanded.bars, String(Date.parse(anchor.ts))) === 20, 'numeric timestamp keys must resolve to the same canonical bar');",
                "check(applyHistoryViewportAnchor(expanded, { historyAnchorTs: anchor.ts, historyAnchorScreenIndex: anchor.screenIndex, previousBars: before.bars.length, previousOffset: 6 }) === true, 'timestamp anchor must be found');",
                "const visible = visibleBars(expanded);",
                "check(visible.bars[0].ts === anchor.ts, 'history expansion must preserve the exact left edge without a 25% jump');",
                "check(visible.bars[0].bar_slot === 20, 'manual-channel bar_slot geometry must remain unchanged');",
                "const staleRequestAnchor = anchor;",
                "view.offset = 0;",
                "const commitAnchor = historyViewportAnchor(before);",
                "check(commitAnchor.ts === allBars[26].ts, 'test setup must move the viewport while history is loading');",
                "check(applyHistoryViewportAnchor(expanded, { previousSnapshot: before, historyAnchorTs: staleRequestAnchor.ts, historyAnchorScreenIndex: 0, previousBars: before.bars.length, previousOffset: 6 }) === true, 'commit-time anchor must be found');",
                "check(visibleBars(expanded).bars[0].ts === commitAnchor.ts, 'commit-time hand position must override the stale request anchor');",
                "view.offset = 6;",
                "view.historyPullOffsetBars = 5;",
                "view.dragActive = true;",
                "view.dragCurrentDeltaBars = 5;",
                "check(applyHistoryViewportAnchor(expanded, { previousSnapshot: before, previousOffset: 6 }) === true, 'boundary anchor with pending pull must be restored');",
                "check(visibleBars(expanded).bars[0].ts === allBars[15].ts, 'late history commit must reveal exactly the bounded five-bar pull');",
                "check(view.historyPullOffsetBars === 0, 'late history commit must clear invisible pending pull');",
                "check(view.dragStartOffset + view.dragCurrentDeltaBars === view.offset, 'snapshot commit during pointer capture must rebase the active drag');",
                "view.dragActive = false;",
                "view.offset = 6;",
                "check(applyHistoryViewportAnchor(expanded, { historyAnchorTs: 'missing', previousBars: before.bars.length, previousOffset: 6 }) === false, 'missing request anchor must report a fallback');",
                "check(view.offset === 6, 'missing anchor must preserve the current offset instead of jumping by the prepended page size');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_history_demand_is_single_flight_with_one_trailing_latest_intent(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/59-chart-navigation.js").read_text(
        encoding="utf-8"
    )
    demand_source = (
        "function cancelHistoryDemand"
        + source.split("function cancelHistoryDemand", 1)[1].split("function setFollowLatest", 1)[0]
    )
    script_path = tmp_path / "history-single-flight.js"
    script_path.write_text(
        "\n".join(
            (
                "const DEFAULT_BARS_VISIBLE = 120;",
                "const HISTORY_PAGE_MIN_BARS = 300; const HISTORY_PAGE_MAX_BARS = 1000; const HISTORY_PAGE_VIEWPORTS = 2; const HISTORY_PREFETCH_VIEWPORTS = 2;",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function timestampKey(value) { return value; }",
                "let barsConfirmed = true; function barIsConfirmedClosed() { return barsConfirmed; }",
                "function maxOffsetFor(snapshot) { return Math.max(snapshot.bars.length - view.barsVisible, 0); }",
                "let clearCalls = 0; function setUiNotice() {} function clearUiNotice() { clearCalls += 1; } function renderPanel() {}",
                "const state = { notices: {}, snapshot: { bars: Array.from({ length: 600 }, (_item, index) => ({ ts: String(index) })), meta: {} }, requests: { history: { loading: false, exhausted: false, queued: false, abort: null, sequence: 0 } } };",
                "const view = { barsVisible: 120, offset: 480, followLatest: false, historyPullOffsetBars: 0 };",
                "let calls = 0; let active = 0; let maxActive = 0; const releases = [];",
                "function loadHistoryPage() { calls += 1; active += 1; maxActive = Math.max(maxActive, active); return new Promise(resolve => releases.push(() => { active -= 1; resolve(1); })); }",
                demand_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "(async () => {",
                "  maybeLoadMoreHistory(); await Promise.resolve();",
                "  check(calls === 1 && active === 1, 'first demand must start one request');",
                "  maybeLoadMoreHistory(); maybeLoadMoreHistory();",
                "  check(calls === 1 && state.requests.history.queued === true, 'rapid demand must collapse to one trailing intent');",
                "  releases.shift()(); for (let attempt = 0; calls < 2 && attempt < 10; attempt += 1) await new Promise(resolve => setTimeout(resolve, 2));",
                "  check(calls === 2 && maxActive === 1, 'trailing request must start only after the first completes');",
                "  cancelHistoryDemand(); releases.shift()(); await new Promise(resolve => setImmediate(resolve));",
                "  check(calls === 2 && state.requests.history.loading === false && state.requests.history.queued === false, 'release or reversal must clear trailing demand');",
                "  check(clearCalls === 2, 'every settled page must clear a stale loading notice');",
                "  barsConfirmed = false; state.requests.history.exhausted = false; state.snapshot.bars = [{ ts: 'unconfirmed' }]; view.barsVisible = 120; view.offset = 0;",
                "  maybeLoadMoreHistory(); await new Promise(resolve => setImmediate(resolve));",
                "  check(calls === 2 && state.requests.history.loading === false && state.requests.history.queued === false, 'missing cursor must settle without a self-scheduled loop');",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_history_zoom_intent_continues_only_after_real_page_growth(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/59-chart-navigation.js").read_text(
        encoding="utf-8"
    )
    demand_source = (
        "function cancelHistoryDemand"
        + source.split("function cancelHistoryDemand", 1)[1].split("function setFollowLatest", 1)[0]
    )
    script_path = tmp_path / "history-zoom-continuation.js"
    script_path.write_text(
        "\n".join(
            (
                "const DEFAULT_BARS_VISIBLE = 120;",
                "const HISTORY_PAGE_MIN_BARS = 300; const HISTORY_PAGE_MAX_BARS = 1000; const HISTORY_PAGE_VIEWPORTS = 2; const HISTORY_PREFETCH_VIEWPORTS = 2;",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function barIsConfirmedClosed() { return true; }",
                "function maxOffsetFor(snapshot) { return Math.max(snapshot.bars.length - view.barsVisible, 0); }",
                "function setUiNotice() {} function clearUiNotice() {} function renderPanel() {}",
                "const rows = count => Array.from({ length: count }, (_item, index) => ({ ts: String(index) }));",
                "const state = { snapshot: { bars: rows(600), meta: {} }, requests: { history: { loading: false, exhausted: false, queued: false, abort: null, sequence: 0 } } };",
                "const view = { barsVisible: 5000, offset: 0, followLatest: true, historyPullOffsetBars: 0 };",
                "let calls = 0; let active = 0; let maxActive = 0; let noGrowth = false;",
                "async function loadHistoryPage() { calls += 1; active += 1; maxActive = Math.max(maxActive, active); await Promise.resolve(); active -= 1; if (noGrowth) return 0; state.snapshot.bars = rows(state.snapshot.bars.length + 1000); return 1000; }",
                demand_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "async function settle() { for (let attempt = 0; attempt < 80 && (state.requests.history.loading || state.requests.history.queued); attempt += 1) await new Promise(resolve => setTimeout(resolve, 2)); }",
                "(async () => {",
                "  maybeLoadMoreHistory(); await settle();",
                "  check(calls === 6, `5000-bar viewport plus bounded left buffer requires six pages, received ${calls}`);",
                "  check(state.snapshot.bars.length === 6600, 'real page growth must fill the target and one bounded prefetch page');",
                "  check(maxActive === 1 && state.requests.history.loading === false && state.requests.history.queued === false, 'continuation must remain single-flight and settle');",
                "  state.snapshot.bars = rows(600); state.requests.history.exhausted = false; view.barsVisible = 5000; calls = 0; noGrowth = true;",
                "  maybeLoadMoreHistory(); await settle();",
                "  check(calls === 1, 'a no-growth page must stop the exact zoom intent without a fetch loop');",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


