def test_chart_render_projection_preserves_extrema_gaps_and_provisional_bar(
    tmp_path: Path,
) -> None:
    core = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(encoding="utf-8")
    projection_source = (
        "function chartRenderDensityMode"
        + core.split("function chartRenderDensityMode", 1)[1].split(
            "function chartVisualHitForLocalX", 1
        )[0]
    )
    script_path = tmp_path / "chart-render-projection.js"
    script_path.write_text(
        "\n".join(
            (
                "const CHART_CANDLE_DETAIL_MIN_STEP_PX = 2;",
                "const CHART_CANDLE_OVERVIEW_MAX_STEP_PX = 0.75;",
                "const CHART_OVERVIEW_COLUMN_WIDTH_PX = 1;",
                "function intervalMinutesFromState() { return 1; }",
                "function authoritativeVisualBarSlot(bar) { return bar?.bar_slot_authoritative === true ? Number(bar.bar_slot) : null; }",
                "function chartVisualAxis(bars, slotStep = intervalMinutesFromState()) { const step = Math.max(Math.round(Number(slotStep) || 0), 1); const positions = new Array(bars.length); const gaps = []; let position = 0; for (let index = 0; index < bars.length; index += 1) { if (index > 0) { let visualUnits = 1; const previousSlot = authoritativeVisualBarSlot(bars[index - 1]); const currentSlot = authoritativeVisualBarSlot(bars[index]); const slotDelta = currentSlot !== null && previousSlot !== null ? currentSlot - previousSlot : 0; if (slotDelta > step && slotDelta % step === 0) visualUnits = slotDelta / step; position += visualUnits; if (visualUnits > 1) gaps.push({ afterIndex: index }); } positions[index] = position; } return { positions, gaps }; }",
                "function hasPriceBar(bar) { return ['open', 'high', 'low', 'close'].every(field => Number.isFinite(Number(bar?.[field]))); }",
                projection_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const bar = (slot, open, high, low, close, volume, closed = true) => ({ ts: `t${slot}`, open, high, low, close, volume, closed, authoritative: closed, bar_slot: slot, bar_slot_authoritative: true });",
                "const bars = [bar(0, 10, 14, 9, 12, 5), bar(1, 12, 18, 8, 11, 7), bar(4, 11, 13, 6, 7, 9), bar(5, 7, 15, 7, 14, 3, false)];",
                "const centers = [0.10, 0.30, 0.55, 0.65];",
                "const projection = chartRenderProjection(bars, 0.2, index => centers[index]);",
                "check(projection.mode === 'overview', 'subpixel scale must use overview columns');",
                "check(projection.columns.length === 3 && projection.maxSourceBarsPerColumn === 2, 'same-pixel confirmed rows merge, gaps and provisional rows do not');",
                "const first = projection.columns[0];",
                "check(first.sourceStart === 0 && first.sourceEnd === 2 && first.sourceCount === 2, 'column must retain its exact source range');",
                "check(first.renderOpen === 10 && first.renderHigh === 18 && first.renderLow === 8 && first.renderClose === 11 && first.renderVolume === 12, 'column OHLCV envelope must preserve every source bar');",
                "check(first.highSourceIndex === 1 && first.lowSourceIndex === 1, 'column extrema must retain exact source indexes for drawing magnets');",
                "check(projection.columns[1].sourceStart === 2, 'provider gap must start a new render column even inside one pixel');",
                "check(projection.columns[2].provisional === true && projection.columns[2].sourceCount === 1, 'forming candle must remain a separate projection');",
                "check(!('ts' in first) && !('closed' in first) && !('authoritative' in first) && !('bar_slot' in first), 'render columns must never imitate canonical Bar identity');",
                "check(chartRenderProjection(bars, 3, index => index * 3).mode === 'detail', 'wide scale must retain exact candle rendering');",
                "const denseBars = Array.from({ length: 5000 }, (_item, index) => bar(index, index, index + 2, index - 2, index + 1, 1));",
                "const dense = chartRenderProjection(denseBars, 0.2, index => index / 5);",
                "check(dense.columns.length === 1000 && dense.maxSourceBarsPerColumn === 5, '5000 source bars must reduce to the fixed screen-column budget');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


