def test_drawing_projection_refresh_retry_lifecycle_is_bounded_and_scope_aware(
    tmp_path: Path,
) -> None:
    storage_source = Path("src/aef_terminal/ui/assets/js/20-storage-sync.js").read_text(
        encoding="utf-8"
    )
    refresh_state_source = storage_source.split("function sharedObjectSignature", 1)[0]
    apply_source = (
        "function drawingDefinitionSignature(drawings = state.drawing.objects)"
        + storage_source.split(
            "function drawingDefinitionSignature(drawings = state.drawing.objects)", 1
        )[1].split("function applyServerPriceAlerts", 1)[0]
    )
    refresh_source = (
        "async function loadDrawingsFromServerForCurrent(options = {})"
        + storage_source.split(
            "async function loadDrawingsFromServerForCurrent(options = {})",
            1,
        )[1].split("function refreshSharedObjectsFromServer", 1)[0]
    )
    script_path = tmp_path / "drawing-projection-refresh-lifecycle.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "let now = 0; Date.now = () => now;",
                "let nextTimerId = 0; const timers = new Map(); const scheduledDelays = [];",
                "function setTimeout(callback, delay) { const id = ++nextTimerId; timers.set(id, { callback, delay }); scheduledDelays.push(delay); return id; }",
                "function clearTimeout(id) { timers.delete(id); }",
                "async function fireTimer(id) { const timer = timers.get(id); assert.ok(timer, `timer ${id} missing`); timers.delete(id); now += timer.delay; timer.callback(); await new Promise(resolve => setImmediate(resolve)); }",
                "let currentFingerprint = 'route-a'; let localEdit = false; let fetchMode = 'fail'; let fetchCalls = 0; let resolveFetch = null;",
                "const state = { instrumentId: 'instrument-a', timeframe: '5m', symbol: 'A', snapshot: { bars: [], meta: { instrument_id: 'instrument-a', route_fingerprint: 'route-a', timeframe: '5m', chart_canonical_revision: 7 } }, alerts: { syncEpoch: 0 }, drawing: { objects: [], selectedId: null, draft: null, hoverPoint: null, persistedCount: 0 } };",
                "const serverStorageReady = true; const serverPersistedDrawingSignatures = new Map(); const serverDirtyDrawingScopes = new Set(); let serverDrawingSignature = ''; let serverDrawingRuntimeSignature = '';",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function instrumentRouteFingerprint() { return currentFingerprint; }",
                "function drawingProjectionSnapshotReadiness(snapshot) { return { ready: Boolean(snapshot?.meta) }; }",
                "function drawingProjectionSnapshotCacheKey(snapshot) { return JSON.stringify([snapshot?.meta?.instrument_id, snapshot?.meta?.route_fingerprint, snapshot?.meta?.timeframe, snapshot?.meta?.chart_canonical_revision]); }",
                "function localObjectEditActive() { return localEdit; }",
                "function priceAlertWritePendingForScope() { return false; }",
                "async function fetchServerStorage() { fetchCalls += 1; if (fetchMode === 'fail') throw new Error('transient write conflict'); const payload = { drawings: [{ id: 'line-a', type: 'line', points: [] }], alerts: [], instrument_id: state.instrumentId, route_fingerprint: currentFingerprint, interval: state.timeframe }; if (fetchMode === 'deferred') return new Promise(resolve => { resolveFetch = () => resolve(payload); }); return payload; }",
                "function normalizeDrawingObjects(drawings) { return drawings.map(item => ({ ...item })); }",
                "function filterRecentlyDeletedDrawings(drawings) { return drawings; }",
                "function normalizedDrawingAnchorResolution(value) { return value || null; }",
                "function normalizedDrawingAnchorProjection(value) { return value || null; }",
                "function resolveDrawingAnchorsAgainstSnapshot(drawings) { drawings.forEach(item => { item.geometryIntegrity = { status: 'valid', reasons: [] }; }); return true; }",
                "function drawingAnchorValidationPending() { return false; }",
                "function suspiciousIncomingDrawingShrink() { return false; }",
                "function sharedObjectSignature(value) { return JSON.stringify(value || []); }",
                "function durableDrawingObjects(value) { return value.map(item => { const durable = { ...item }; delete durable.anchorResolution; delete durable.anchorProjection; delete durable.geometryIntegrity; return durable; }); }",
                "function scopedObjectSignature(...parts) { return JSON.stringify(parts); }",
                "function resetDrawingHistory() {} function applyDrawingUi() {} function touchChartUserObjectsVersion() {}",
                "function applyServerPriceAlerts() { return false; } function requestObjectLayerRedraw() {} function requestErrorMessage(error) { return error.message; }",
                refresh_state_source,
                apply_source,
                refresh_source,
                "(async () => {",
                "  assert.equal(scheduleDrawingProjectionRefresh(), true); const scopeATimer = drawingProjectionRefreshTimer;",
                "  state.instrumentId = 'instrument-b'; state.timeframe = '15m'; currentFingerprint = 'route-b'; state.snapshot = { bars: [], meta: { instrument_id: 'instrument-b', route_fingerprint: 'route-b', timeframe: '15m', chart_canonical_revision: 2 } };",
                "  assert.equal(scheduleDrawingProjectionRefresh(), true, 'new scope must supersede an old timer'); const scopeBTimer = drawingProjectionRefreshTimer;",
                "  assert.notEqual(scopeBTimer, scopeATimer); assert.equal(timers.has(scopeATimer), false); assert.equal(timers.has(scopeBTimer), true); assert.equal(drawingProjectionRefreshAttempts, 0);",
                "  completeDrawingProjectionRefresh(); assert.equal(timers.size, 0);",
                "  localEdit = true; assert.equal(scheduleDrawingProjectionRefresh(), true); const localEditTimer = drawingProjectionRefreshTimer; await fireTimer(localEditTimer);",
                "  assert.equal(fetchCalls, 0, 'local edit must not start a fetch'); assert.equal(drawingProjectionRefreshAttempts, 0, 'local edit consumed an attempt'); assert.ok(drawingProjectionRefreshTimer);",
                "  localEdit = false; const retryDelayStart = scheduledDelays.length;",
                "  await fireTimer(drawingProjectionRefreshTimer); assert.equal(fetchCalls, 1); assert.equal(drawingProjectionRefreshAttempts, 1);",
                "  await fireTimer(drawingProjectionRefreshTimer); assert.equal(fetchCalls, 2); assert.equal(drawingProjectionRefreshAttempts, 2);",
                "  await fireTimer(drawingProjectionRefreshTimer); assert.equal(fetchCalls, 3); assert.equal(drawingProjectionRefreshAttempts, 3); assert.equal(drawingProjectionRefreshTimer, null);",
                "  assert.deepEqual(scheduledDelays.slice(retryDelayStart), [500, 1000], 'retry backoff was not bounded exponential'); assert.equal(scheduleDrawingProjectionRefresh(), false, 'max attempts did not stop retries');",
                "  fetchMode = 'success'; await loadDrawingsFromServerForCurrent({ force: true, reason: 'drawing_projection_refresh' });",
                "  assert.equal(drawingProjectionRefreshAttempts, 0, 'successful full apply did not reset attempts'); assert.equal(drawingProjectionRefreshScopeKey, ''); assert.equal(state.drawing.objects[0].geometryIntegrity.status, 'valid');",
                "  state.drawing.objects[0].anchorResolution = { status: 'resolved', reasons: [] }; state.drawing.objects[0].anchorProjection = { marker: 'last-valid' }; await loadDrawingsFromServerForCurrent({ force: true, reason: 'drawing_projection_refresh' });",
                "  assert.equal(state.drawing.objects[0].anchorProjection.marker, 'last-valid', 'inconclusive refresh discarded last validated projection');",
                "  assert.equal(scheduleDrawingProjectionRefresh(), true, 'successful apply did not re-arm a later refresh lifecycle');",
                "  completeDrawingProjectionRefresh(); fetchMode = 'deferred'; const staleLoad = loadDrawingsFromServerForCurrent({ force: true, reason: 'drawing_projection_refresh' }); await new Promise(resolve => setImmediate(resolve));",
                "  state.drawing.objects = [{ id: 'line-edited', type: 'line', points: [{ ts: 'new-version' }] }]; resolveFetch(); await staleLoad;",
                "  assert.equal(state.drawing.objects[0].id, 'line-edited', 'stale validation result replaced a newer drawing definition'); assert.ok(drawingProjectionRefreshTimer, 'new drawing definition did not schedule its own validation');",
                "  completeDrawingProjectionRefresh();",
                "})().catch(error => { console.error(error); process.exitCode = 1; });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_channel_geometry_stays_active_until_definitively_invalid(tmp_path: Path) -> None:
    geometry_source = Path("src/aef_terminal/ui/assets/js/60-drawing-geometry.js").read_text(
        encoding="utf-8"
    )
    manager_source = Path("src/aef_terminal/ui/assets/js/60-drawing-manager.js").read_text(
        encoding="utf-8"
    )
    drawing_source = Path("src/aef_terminal/ui/assets/js/60-drawing-tools.js").read_text(
        encoding="utf-8"
    )
    geometry_contract = (
        "function durableDrawingPointReason"
        + geometry_source.split("function durableDrawingPointReason", 1)[1].split(
            "function lineEndpointAtLogicalIndex",
            1,
        )[0]
    )
    manager_contract = (
        "function drawingObjectMeta"
        + manager_source.split("function drawingObjectMeta", 1)[1].split(
            "function renderDrawingManagerTabs",
            1,
        )[0]
    )
    script_path = tmp_path / "channel-geometry-status.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const DRAWING_POINT_COUNTS = { channel: 2 };",
                "const CHANNEL_GHOST_COPIES_DEFAULT = 3; const CHANNEL_GHOST_COPIES_MAX = 10;",
                "function drawingTimestampIdentity(value) { const parsed = Date.parse(value || ''); return Number.isFinite(parsed) ? String(parsed) : ''; }",
                "function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }",
                geometry_contract,
                manager_contract,
                "const ts = '2026-08-13T10:00:00.000Z';",
                "function channel(status, reasons = []) { return { type: 'channel', points: [{ ts, price: 1 }, { ts, price: 2 }], offsetPoint: { ts, price: 3 }, geometryIntegrity: { status, reasons } }; }",
                "for (const status of ['pending', 'syncing', 'unavailable']) { const object = channel(status, ['projection_generation_mismatch']); assert.equal(channelCompromised(object), false); assert.deepEqual(drawingObjectIntegrityReasons(object), []); assert.equal(drawingGeometryRenderable(object), true); assert.equal(drawingObjectMeta(object), 'quarters · ghosts 3 · theme'); }",
                "const invalid = channel('invalid', ['anchor_absent_from_projection']); assert.equal(channelCompromised(invalid), true); assert.deepEqual(drawingObjectIntegrityReasons(invalid), ['anchor_absent_from_projection']); assert.equal(drawingGeometryRenderable(invalid), false); assert.match(drawingObjectMeta(invalid), /^CHECK BAR ANCHORS/);",
                "assert.equal(channelCompromised(channel('valid')), false); assert.equal(drawingGeometryRenderable(channel('valid')), true);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    assert "if (!drawingGeometryRenderable(channelObject))" in drawing_source
    assert (
        "if (!drawingGeometryRenderable(object) || channelCompromised(object)) continue;"
        in (
            drawing_source.split("function hitTestDrawing", 1)[1].split(
                "function hitTestDrawingHandle",
                1,
            )[0]
        )
    )


