def test_ema_and_vwap_stroke_confirmed_path_before_trailing_provisional_point(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(encoding="utf-8")
    ema_source = (
        "function drawEmaLine"
        + source.split("function drawEmaLine", 1)[1].split(
            "function drawEma233",
            1,
        )[0]
    )
    vwap_source = "function drawVwapCurve" + source.split("function drawVwapCurve", 1)[1]
    script_path = tmp_path / "chart-guide-trailing-provisional-render.js"
    script_path.write_text(
        "\n".join(
            (
                'const state = { indicators: { vwap: { enabled: true, bands: false, width: 1, style: "solid", color: "#c084fc", bandColor: "#2962ff" } } };',
                "function chartGuideEmaValues() { return [100, 101, null]; }",
                "function chartGuideVwapSeries() { return [{ vwap: 100, sigma: 1 }, { vwap: 101, sigma: 1 }, { vwap: null, sigma: null }]; }",
                "function finiteSeriesNumber(value) { const numeric = Number(value); return value === null || value === undefined || !Number.isFinite(numeric) ? null : numeric; }",
                "function firstFiniteValue(values) { for (let index = 0; index < values.length; index += 1) { const value = finiteSeriesNumber(values[index]); if (value !== null) return { index, value }; } return null; }",
                "function latestFiniteValue(values) { for (let index = values.length - 1; index >= 0; index -= 1) { const value = finiteSeriesNumber(values[index]); if (value !== null) return { index, value }; } return null; }",
                "function calibratedCanvasColor(value) { return value; }",
                'function css() { return "#ffffff"; }',
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function lineDashForStyle() { return []; }",
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const ctx = { strokes: 0, lines: 0, save() {}, restore() {}, setLineDash() {}, beginPath() {}, moveTo() {}, lineTo() { this.lines += 1; }, stroke() { this.strokes += 1; }, fillText() {} };",
                ema_source,
                vwap_source,
                "const visible = { bars: [{}, {}, {}], start: 0, end: 3 };",
                "drawEmaLine(ctx, {}, visible, value => value, value => value, 20);",
                'check(ctx.lines === 1 && ctx.strokes === 1, "EMA confirmed segment must be stroked before trailing null");',
                "ctx.lines = 0; ctx.strokes = 0;",
                "drawVwapCurve(ctx, {}, visible, value => value, value => value);",
                'check(ctx.lines === 1 && ctx.strokes === 1, "VWAP confirmed segment must be stroked before trailing null");',
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


