                "function debugStep() {}",
                "function runPendingGexMarketRecalc() {}",
                "function compactMarketSnapshot(snapshot) { return snapshot; }",
                "function currentAnalysisBars(snapshot = state.snapshot) { return snapshot.bars || []; }",
                "function normalizeSnapshotBarSlots(snapshot) { return snapshot; }",
                "function isValidMarketSnapshotPayload() { return true; }",
                "function pruneClientHistoryWindow() {}",
                "function renderCharts() {} function renderPanel() {} function renderInstruments() {} function renderTimeframes() {} function applyLayout() {}",
                "function refreshPaperJournal() {} function paperJournalRefreshOptions() { return {}; }",
                "function gexLayerVisible() { return false; } function loadGexContext() {} function clearGexContext() {}",
                "const window = {};",
                "async function fetchJson() { fetchCount += 1; return { indicators: { revision: 8 }, chart_guides: { owner: 'analysis' }, meta: { analysis_only: true, analysis_key: 'analysis-stable', instrument_id: 'instrument-a', route_fingerprint: 'route-a', timeframe: '5m', chart_range: '5d', analysis_ts: t1, analysis_latest_ts: t1, analysis_parent_canonical_revision: 8 } }; }",
                analysis_watermark_source,
