                "  check(fetchCount === 1, 'same-bar r7 analysis falsely suppressed the r8 fetch');",
                "  check(state.snapshot.meta.analysis_parent_canonical_revision === 8, 'real merge did not publish the r8 parent revision');",
                "  check(state.snapshot.chart_guides.owner === 'chart-registration', 'analysis payload replaced the chart-registration guide owner');",
                "  check(state.lastIndicatorAnalysisMergedVersion === `${t1}|r8`, 'real merge did not advance the browser analysis version');",
