def test_missing_analysis_uses_exact_lease_or_one_monotonic_registration(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(encoding="utf-8")
    lease_match_source = (
        "function marketAnalysisLeaseMatchesExactScope"
        + source.split("function marketAnalysisLeaseMatchesExactScope", 1)[1].split(
            "function activateMarketAnalysisLease",
            1,
        )[0]
    )
    missing_refresh_source = (
        "function scheduleAnalysisRefreshAfterMissing"
        + source.split("function scheduleAnalysisRefreshAfterMissing", 1)[1].split(
            "async function loadMarketAnalysisSnapshot",
            1,
        )[0]
    )
    script_path = tmp_path / "analysis-missing-lease-recovery.js"
    script_path.write_text(
        "\n".join(
            (
                "const MARKET_ANALYSIS_MISSING_MAX_ATTEMPTS = 6;",
                "const state = { instrumentId: 'instrument-a', symbol: 'BTC-USD', dataSource: 'coinbase', timeframe: '5m', range: '5d', serverSleeping: false, analysisMissingRefreshKey: '', analysisMissingRecoveryScope: '', analysisMissingRecoveryAttempt: 0, snapshot: { meta: { analysis_key: 'analysis-a' } }, requests: { analysis: { pollAttempt: 1, pollTimer: null, leaseKey: '', leaseActiveSequence: 0, leaseInstrumentId: '', leaseRouteFingerprint: '', leaseSequence: 10 } } };",
                "let routeFingerprint = 'route-a'; let scheduledCallback = null; let timerSequence = 0; let refreshResult = true; let refreshCalls = 0; const registrations = [];",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function instrumentRouteFingerprint() { return routeFingerprint; }",
                "function setTimeout(callback) { scheduledCallback = callback; timerSequence += 1; return timerSequence; }",
                "function clearTimeout() {}",
                "async function refreshRegisteredMarketAnalysis() { refreshCalls += 1; return refreshResult; }",
                "async function load(options) { state.requests.analysis.leaseSequence += 1; registrations.push({ options, sequence: state.requests.analysis.leaseSequence }); return true; }",
                lease_match_source,
                missing_refresh_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "async function runScheduled() { const callback = scheduledCallback; scheduledCallback = null; if (!callback) throw new Error('missing timer callback'); await callback(); }",
                "(async () => {",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === true, 'missing lease did not schedule recovery');",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === false, 'duplicate recovery was scheduled');",
                "  await runScheduled();",
                "  check(refreshCalls === 0 && registrations.length === 1, 'missing lease did not use one normal registration');",
                "  check(registrations[0].options.queueAnalysis === true && registrations[0].options.analysisOnly === true, 'fallback registration did not queue analysis');",
                "  check(registrations[0].options.analysisMissingRecovery === true, 'fallback registration did not preserve its bounded recovery scope');",
                "  check(registrations[0].sequence === 11, 'fallback registration did not allocate the next sequence');",
                "  state.requests.analysis.leaseKey = 'analysis-a'; state.requests.analysis.leaseActiveSequence = 9; state.requests.analysis.leaseInstrumentId = 'instrument-a'; state.requests.analysis.leaseRouteFingerprint = 'route-a';",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === true, 'exact lease refresh was not scheduled'); await runScheduled();",
                "  check(refreshCalls === 1 && registrations.length === 1, 'exact lease did not use refresh exclusively');",
                "  state.requests.analysis.leaseRouteFingerprint = 'route-old';",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === true, 'mismatched lease recovery was not scheduled'); await runScheduled();",
                "  check(refreshCalls === 1 && registrations.length === 2 && registrations[1].sequence === 12, 'mismatched lease did not re-register monotonically');",
                "  state.requests.analysis.leaseRouteFingerprint = 'route-a'; refreshResult = false;",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === true, 'failed exact refresh recovery was not scheduled'); await runScheduled();",
                "  check(refreshCalls === 2 && registrations.length === 3 && registrations[2].sequence === 13, 'failed exact refresh did not fall back once');",
                "  state.requests.analysis.leaseRouteFingerprint = 'route-old';",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === true, 'fifth recovery was not admitted');",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === false, 'repeated fifth checkpoint was not deduplicated'); await runScheduled();",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === true, 'sixth recovery was not admitted'); await runScheduled();",
                "  scheduledCallback = null;",
                "  check(scheduleAnalysisRefreshAfterMissing('instrument-a', 'route-a', 'coinbase', '5m', '5d') === false, 'bounded missing recovery scheduled beyond its attempt limit');",
                "  check(scheduledCallback === null && registrations.length === 5 && registrations[4].sequence === 15, 'bounded recovery created extra or non-monotonic work');",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_analysis_lifecycle_and_history_audit_are_independent(tmp_path: Path) -> None:
    data_source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(
        encoding="utf-8"
    )
    panel_source = Path("src/aef_terminal/ui/assets/js/30-market-panel-runtime.js").read_text(
        encoding="utf-8"
    )
    coverage_source = (
        "function historyCoverageVerificationStatus"
        + data_source.split("function historyCoverageVerificationStatus", 1)[1].split(
            "function instrumentForId",
            1,
        )[0]
    )
    lifecycle_source = (
        "function marketAnalysisLifecyclePresentation"
        + panel_source.split("function marketAnalysisLifecyclePresentation", 1)[1].split(
            "function renderMarketHealthStatus",
            1,
        )[0]
    )
    script_path = tmp_path / "analysis-lifecycle-history-audit.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = { dataSource: 'coinbase' };",
                coverage_source,
                lifecycle_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const coverage = { state: 'unknown', bar_repair: { supported: true, status: 'scheduled', error_code: null }, absence_verification: { supported: false, state: 'unsupported', error_code: 'PROVIDER_ABSENCE_VERIFICATION_UNAVAILABLE' } };",
                "const diagnostic = historyCoverageVerificationStatus(coverage);",
                "check(diagnostic.active === true && diagnostic.concreteRepair === true, 'typed bar repair admission was not projected');",
                "check(diagnostic.absenceSupported === false && diagnostic.absenceState === 'unsupported', 'absence audit was merged into bar repair');",
                "const ready = marketAnalysisLifecyclePresentation({ meta: { analysis_status: 'ready', history_coverage: coverage } });",
                "check(ready.label === 'READY' && ready.tone === 'ok', 'coverage audit changed ready analysis lifecycle');",
                "const missing = marketAnalysisLifecyclePresentation({ meta: { analysis_status: 'missing' } });",
                "check(missing.label === 'MISSING' && missing.tone === 'bad', 'missing analysis lifecycle was hidden by bar quality');",
                "const idle = historyCoverageVerificationStatus({ bar_repair: { supported: true, status: 'not_requested' }, absence_verification: { supported: false, state: 'unsupported' } });",
                "check(idle.active === false && idle.concreteRepair === false, 'non-admitted repair became background work');",
                "const terminal = historyCoverageVerificationStatus({ bar_repair: { supported: true, phase: 'terminal', status: 'fetch_failed', error_code: 'PROVIDER_FETCH_FAILED', requested_from: '2026-07-01T00:00:00Z', requested_to: '2026-07-02T00:00:00Z' }, absence_verification: { supported: false, state: 'unsupported' } });",
                "check(terminal.active === false && terminal.concreteRepair === true && terminal.repairPhase === 'terminal' && terminal.repairErrorCode === 'PROVIDER_FETCH_FAILED' && terminal.repairRequestedFrom.endsWith('Z') && terminal.repairRequestedTo.endsWith('Z'), 'terminal repair outcome was not rendered as finite diagnostics');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_empty_indicator_rows_project_finite_analysis_lifecycle(tmp_path: Path) -> None:
    controls_source = Path(
        "src/aef_terminal/ui/assets/js/30-panels-indicator-controls.js"
    ).read_text(encoding="utf-8")
    data_source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(
        encoding="utf-8"
    )
    panel_source = Path("src/aef_terminal/ui/assets/js/30-market-panel-runtime.js").read_text(
        encoding="utf-8"
    )
    lifecycle_source = (
        "function marketAnalysisLifecyclePresentation"
        + panel_source.split("function marketAnalysisLifecyclePresentation", 1)[1].split(
            "function renderMarketHealthStatus",
            1,
        )[0]
    )
    indicator_state_source = (
        "function indicatorAnalysisLifecycleRuntimeState"
        + controls_source.split("function indicatorAnalysisLifecycleRuntimeState", 1)[1].split(
            "function setupIndicatorRuntimeToggles",
            1,
        )[0]
    )
    lifecycle_projection_source = (
        "function projectMarketAnalysisLifecycle"
        + data_source.split("function projectMarketAnalysisLifecycle", 1)[1].split(
            "function scheduleAnalysisRefreshAfterMissing",
            1,
        )[0]
    )
    script_path = tmp_path / "empty-indicator-analysis-lifecycle.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = { instrumentId: 'instrument-a', snapshot: null };",
                "function normalizeRuntimeAction() { return ''; }",
                "function runtimeActionClass() { return 'ok'; }",
                "function indicatorRuntimeStateForRef(ref) { return ref ? { text: 'SERVICE', actionClass: 'ok', details: 'service state' } : null; }",
                "function exactIdentityText(value) { return String(value || ''); }",
                "function instrumentRouteFingerprint() { return 'route-a'; }",
                "let healthRenderCount = 0; let projectedRow = null;",
                "function renderMarketHealthStatus() { healthRenderCount += 1; }",
                "function renderIndicatorRuntimeStatus(snapshot) { projectedRow = resolveIndicatorRuntimeState(true, true, { state_code: 'no_signal', state: 'READY' }, null, snapshot, 'service_ref'); }",
                lifecycle_source,
                indicator_state_source,
                lifecycle_projection_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const resolve = (status, reason = null) => indicatorRuntimeState(true, true, {}, null, { meta: { analysis_status: status, ...(reason ? { analysis_reason: reason } : {}) } });",
                "check(indicatorRuntimeState(true, true, {}, null, { meta: {} }).text === 'LOAD', 'pre-response state must remain loading');",
                "check(resolve('queued').text === 'QUEUED' && resolve('queued').actionClass === 'warn', 'queued analysis was not projected');",
                "check(resolve('running').text === 'RUNNING', 'running analysis was not projected');",
                "check(resolve('repairing').text === 'REPAIRING', 'bounded recovery was not projected');",
                "const missing = resolve('missing', { code: 'MARKET_ANALYSIS_NOT_FOUND', message: 'Analysis snapshot not found.' });",
                "check(missing.text === 'MISSING' && missing.actionClass === 'bad', 'missing analysis remained loading');",
                "check(missing.details.includes('MARKET_ANALYSIS_NOT_FOUND') && missing.details.includes('Analysis snapshot not found.'), 'missing analysis reason was not exposed');",
                "check(resolve('error', { code: 'MARKET_ANALYSIS_FAILED' }).text === 'ERROR', 'analysis error remained loading');",
                "check(resolve('degraded', { code: 'MARKET_ANALYSIS_TRANSPORT_FAILED' }).text === 'DEGRADED', 'degraded analysis remained loading');",
                "check(resolve('superseded').text === 'DEGRADED', 'superseded analysis was not finite');",
                "const readyMissing = resolve('ready');",
                "check(readyMissing.text === 'MISSING' && readyMissing.details.includes('returned no typed status'), 'ready analysis hid a missing indicator result');",
                "const oldStatus = { state_code: 'no_signal', state: 'READY' };",
                "check(indicatorRuntimeState(true, true, oldStatus, null, { meta: { analysis_status: 'queued', analysis_preserved: true } }).text === 'QUEUED', 'queued refresh exposed a preserved old indicator status');",
                "check(indicatorRuntimeState(true, true, oldStatus, null, { meta: { analysis_status: 'degraded', analysis_preserved: true, analysis_preserved_stale: true, analysis_reason: { code: 'MARKET_ANALYSIS_RUNNING' } } }).text === 'DEGRADED', 'degraded refresh exposed a stale old indicator status');",
                "check(resolveIndicatorRuntimeState(true, true, oldStatus, null, { meta: { analysis_status: 'degraded', analysis_reason: { code: 'MARKET_ANALYSIS_TRANSPORT_FAILED' } } }, 'service_ref').text === 'DEGRADED', 'runtime state ref bypassed the degraded analysis lifecycle');",
                "const typed = indicatorRuntimeState(true, true, { state_code: 'no_signal', state: 'READY' }, null, { meta: { analysis_status: 'ready' } });",
                "check(typed.text === 'NO SIG', 'typed module status lost priority after ready analysis');",
                "check(indicatorRuntimeState(true, true, { state_code: 'blocked_context', reason_code: 'martin_carlo_warmup' }, null, { meta: { analysis_status: 'ready' } }).text === 'WARM', 'warmup was displayed as a healthy no-signal state');",
                "check(indicatorRuntimeState(true, true, { state_code: 'blocked_context', reason_code: 'unsupported_price_domain' }, null, { meta: { analysis_status: 'ready' } }).text === 'UNSUP', 'unsupported price domain was not distinct');",
                "check(indicatorRuntimeState(true, true, { state_code: 'degraded_context', reason_code: 'optional_context_unavailable' }, null, { meta: { analysis_status: 'ready' } }).text === 'DEGRADED', 'degraded optional context was not distinct');",
                "check(resolveIndicatorRuntimeState(true, true, oldStatus, null, { meta: { analysis_status: 'ready' } }, 'service_ref').text === 'SERVICE', 'ready analysis lost the module runtime state ref');",
                "state.snapshot = { meta: {} };",
                "check(projectMarketAnalysisLifecycle({ status: 'error', error: { code: 'MARKET_ANALYSIS_TRANSPORT_FAILED', message: 'Network failed.' } }, 'instrument-a', 'route-a', 'degraded') === true, 'lifecycle projection was rejected');",
                "check(healthRenderCount === 1 && projectedRow?.text === 'DEGRADED', 'lifecycle projection did not refresh the indicator rows');",
                "check(projectedRow.details.includes('MARKET_ANALYSIS_TRANSPORT_FAILED') && projectedRow.details.includes('Network failed.'), 'projected indicator row lost finite failure diagnostics');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


