def test_typed_repair_recovery_owns_history_notice_lifecycle(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-live-stream-connect.js").read_text(
        encoding="utf-8"
    )
    helper_source = (
        "function clearResolvedHistoryNoticeAfterRecovery"
        + source.split("function clearResolvedHistoryNoticeAfterRecovery", 1)[1].split(
            "function connectChartStream",
            1,
        )[0]
    )
    script_path = tmp_path / "clear-loaded-history-notice.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const state = { range: '14d' };",
                "const cleared = [];",
                "let currentCodes = new Set(['HISTORY_REPAIR_PENDING', 'HISTORY_LOADED']);",
                "function clearUiNotice(owner, code) { cleared.push([owner, code]); if (owner !== 'history' || !currentCodes.has(code)) return false; currentCodes.delete(code); return true; }",
                helper_source,
                "const recovery = (status, phase = 'admission', range = '14d') => ({ recovery_complete: true, history_coverage: { requested_range: range, bar_repair: { supported: true, phase, status } }, chart_data_quality: { status: 'session_unknown', signals_ok: false } });",
                "assert.equal(clearResolvedHistoryNoticeAfterRecovery({ ...recovery('committed', 'terminal'), recovery_complete: false }), false);",
                "assert.equal(clearResolvedHistoryNoticeAfterRecovery(recovery('running')), false);",
                "assert.deepEqual([...currentCodes], ['HISTORY_REPAIR_PENDING', 'HISTORY_LOADED']);",
                "assert.equal(clearResolvedHistoryNoticeAfterRecovery(recovery('not_needed', 'idle', '31d')), false);",
                "assert.equal(clearResolvedHistoryNoticeAfterRecovery(recovery('not_needed', 'idle')), true);",
                "assert.deepEqual([...currentCodes], []);",
                "currentCodes = new Set(['HISTORY_LOADED']);",
                "assert.equal(clearResolvedHistoryNoticeAfterRecovery(recovery('committed', 'terminal')), true);",
                "assert.deepEqual([...currentCodes], []);",
                "assert.deepEqual(cleared, [['history', 'HISTORY_REPAIR_PENDING'], ['history', 'HISTORY_LOADED'], ['history', 'HISTORY_REPAIR_PENDING'], ['history', 'HISTORY_LOADED']]);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


