def test_chart_stream_accepts_signed_zero_ohlc_and_rejects_invalid_geometry(tmp_path: Path) -> None:
    core_source = Path("src/aef_terminal/ui/assets/js/10-core-state.js").read_text(encoding="utf-8")
    source = Path("src/aef_terminal/ui/assets/js/20-live-candle-sync.js").read_text(
        encoding="utf-8"
    )
    identity_source = (
        "function exactIdentityText"
        + core_source.split(
            "function exactIdentityText",
            1,
        )[1].split("const THEME_CSS_VARIABLES", 1)[0]
    )
    normalize_source = (
        "function normalizeChartStreamBarForScope(bar, expectedScope, streamOrder = null)"
        + source.split(
            "function normalizeChartStreamBarForScope(bar, expectedScope, streamOrder = null)",
            1,
        )[1].split("function streamBarKind", 1)[0]
    )
    assert 'typeof value !== "number" || !Number.isFinite(value)' in normalize_source
    assert 'typeof rawVolume !== "number"' in normalize_source
    assert "!Number.isFinite(rawVolume) || rawVolume < 0" in normalize_source
    assert 'if (!source || typeof closed !== "boolean") return null;' in normalize_source
    assert (
        '!["forming", "awaiting_provider_confirmation", "confirmed"].includes(lifecycleState)'
        in normalize_source
    )
    assert 'closed !== (lifecycleState === "confirmed")' in normalize_source
    assert "bar?.source ||" not in normalize_source
    assert "bar?.closed !== false" not in normalize_source
    script_path = tmp_path / "signed-stream-bars.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = { instrumentId: 'ibkr|future|CL', timeframe: '5m', dataSource: 'ibkr' };",
                identity_source,
                "function instrumentRouteFingerprint() { return 'route-fingerprint'; }",
                'function barIsGapPlaceholder(bar) { return Boolean(bar?.missing || bar?.data_gap || bar?.preview_kind === "gap_placeholder" || bar?.source === "gap-placeholder"); }',
                normalize_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const base = { instrument_id: state.instrumentId, provider_symbol: 'CL', route_fingerprint: instrumentRouteFingerprint(), timeframe: state.timeframe, ts: '2026-07-20T13:30:00.000Z', volume: 0, source: 'ibkr:chart-live', closed: false, state: 'forming', authoritative: false, commit_pending: false };",
                "const signed = normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: 0, volume: 0 });",
                "check(signed && signed.open === -2 && signed.high === 0 && signed.close === 0, 'signed and zero OHLC must survive normalization');",
                "check(signed.volume === 0, 'zero volume must remain a valid non-negative volume');",
                "check(normalizeStreamBar({ ...base, open: 0, high: 0, low: 0, close: 0 }), 'flat zero bar must be valid');",
                "check(normalizeStreamBar({ ...base, open: null, high: 0, low: -1, close: 0 }) === null, 'missing OHLC must not coerce to zero');",
                "check(normalizeStreamBar({ ...base, open: '-2', high: 0, low: -3, close: 0 }) === null, 'string OHLC must not be coerced');",
                "check(normalizeStreamBar({ ...base, open: -2, high: -3, low: -4, close: -1 }) === null, 'invalid candle geometry must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: -5 }) === null, 'negative volume must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: undefined }) === null, 'missing volume must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: '1' }) === null, 'string volume must not be coerced');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: 1, source: '' }) === null, 'missing source must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: 1, state: undefined }) === null, 'missing lifecycle state must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: 1, closed: true }) === null, 'contradictory lifecycle must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: 1, authoritative: 'false' }) === null, 'string authority must fail closed');",
                "check(normalizeStreamBar({ ...base, open: -2, high: 0, low: -3, close: -1, volume: 1, stream_seq: '1' }) === null, 'string sequence must fail closed');",
                "check(normalizeStreamBar({ ...base, open: 1, high: 1, low: 1, close: 1, volume: 1, source: 'gap-placeholder', missing: true }) === null, 'legacy gap candle rows must be dropped');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_chart_stream_admission_rejects_malformed_frames_before_order_mutation(
    tmp_path: Path,
) -> None:
    core_source = Path("src/aef_terminal/ui/assets/js/10-core-state.js").read_text(encoding="utf-8")
    sync_source = Path("src/aef_terminal/ui/assets/js/20-live-candle-sync.js").read_text(
        encoding="utf-8"
    )
    connect_source = Path("src/aef_terminal/ui/assets/js/20-live-stream-connect.js").read_text(
        encoding="utf-8"
    )
    identity_source = (
        "function exactIdentityText"
        + core_source.split("function exactIdentityText", 1)[1].split(
            "const THEME_CSS_VARIABLES", 1
        )[0]
    )
    admission_source = (
        "function isValidChartStreamPayload(message)"
        + sync_source.split("function isValidChartStreamPayload(message)", 1)[1].split(
            "function normalizeStreamBar", 1
        )[0]
    )
    normalize_source = (
        "function normalizeStreamBar(bar, streamOrder = null)"
        + sync_source.split("function normalizeStreamBar(bar, streamOrder = null)", 1)[1].split(
            "function streamBarKind", 1
        )[0]
    )
    chart_message = connect_source.split("socket.onmessage = event => {", 2)[2].split(
        "socket.onerror = () =>", 1
    )[0]
    admission_index = chart_message.index("const admission = chartStreamMessageAdmission(message);")
    assert admission_index < chart_message.index(
        "state.transport.chart.generation = streamGeneration;"
    )
    assert admission_index < chart_message.index("state.transport.chart.sequence = streamSeq;")
    assert (
        "recoverStaleChartStream(`invalid chart frame: ${admission.reasonCode}`);" in chart_message
    )
    assert 'recoverStaleChartStream("malformed chart stream frame");' in chart_message

    script_path = tmp_path / "chart-stream-admission.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const state = { instrumentId: 'ibkr|future|CL', timeframe: '5m' };",
                identity_source,
                "function instrumentRouteFingerprint() { return 'route-fingerprint'; }",
                'function barIsGapPlaceholder(bar) { return Boolean(bar?.missing || bar?.data_gap || bar?.preview_kind === "gap_placeholder"); }',
                "function isValidFutureAxisPayload() { return true; }",
                admission_source,
                normalize_source,
                "const bar = { instrument_id: state.instrumentId, provider_symbol: 'CL', route_fingerprint: instrumentRouteFingerprint(), timeframe: state.timeframe, ts: '2026-07-20T13:30:00.000Z', open: -2, high: 0, low: -3, close: -1, volume: 10, source: 'ibkr:chart-live', closed: false, state: 'forming', authoritative: false, commit_pending: false };",
                "const frame = { type: 'chart_bars', instrument_id: state.instrumentId, route_fingerprint: instrumentRouteFingerprint(), interval: state.timeframe, consumer_role: 'primary', bars: [bar], stream_generation: 2, stream_seq: 4, canonical_revision: 0, chart_quality_revision: 0, recovery: false, recovery_complete: false };",
                "assert.deepEqual(chartStreamMessageAdmission(frame), { ok: true, messageType: 'chart_bars', streamGeneration: 2, streamSeq: 4, unsequenced: false });",
                "const secondaryFrame = { ...frame, consumer_role: 'secondary_candles', secondary_tail_membership: { limit: 300, timestamps: [] } };",
                "assert.equal(chartStreamMessageAdmission(secondaryFrame).reasonCode, 'consumer_scope_mismatch', 'secondary frame cannot consume primary order');",
                "assert.equal(isValidChartStreamPayload(secondaryFrame), false);",
                "assert.equal(chartStreamMessageAdmission({ ...frame, secondary_tail_membership: { limit: 300, timestamps: [] } }).reasonCode, 'consumer_scope_mismatch');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, bars: [{ ...bar, high: -3 }] }).reasonCode, 'payload_invalid');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, bars: [{ ...bar, missing: true, preview_kind: 'gap_placeholder' }] }).reasonCode, 'payload_invalid');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, chart_data_quality: [] }).reasonCode, 'payload_invalid');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, route_fingerprint: 'wrong-route' }).reasonCode, 'identity_mismatch');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, type: 'unknown' }).reasonCode, 'payload_invalid');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, stream_seq: '4' }).reasonCode, 'sequence_invalid');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, canonical_revision: '0' }).reasonCode, 'payload_invalid');",
                "assert.equal(chartStreamMessageAdmission({ ...frame, bars: [{ ...bar, close: '-1' }] }).reasonCode, 'payload_invalid');",
                "const status = { type: 'chart_status', instrument_id: state.instrumentId, route_fingerprint: instrumentRouteFingerprint(), consumer_role: 'primary', message: 'waiting' };",
                "assert.equal(chartStreamMessageAdmission(status).unsequenced, true);",
                "assert.equal(chartStreamMessageAdmission({ ...status, consumer_role: 'secondary_candles' }).reasonCode, 'consumer_scope_mismatch');",
                "assert.equal(chartStreamMessageAdmission({ ...status, stream_generation: 2 }).reasonCode, 'sequence_invalid');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


