def test_price_axis_hover_draws_route_scoped_signed_percent_scale(tmp_path: Path) -> None:
    price_source = Path("src/aef_terminal/ui/assets/js/52-overlays-price-render.js").read_text(
        encoding="utf-8"
    )
    interaction_source = Path(
        "src/aef_terminal/ui/assets/js/60-interactions-drawings-alerts.js"
    ).read_text(encoding="utf-8")
    manager_source = Path("src/aef_terminal/ui/assets/js/47-canvas-manager.js").read_text(
        encoding="utf-8"
    )
    state_source = Path("src/aef_terminal/ui/assets/js/10-core-state.js").read_text(
        encoding="utf-8"
    )
    percent_source = (
        "function pricePercentScaleValue"
        + price_source.split("function pricePercentScaleValue", 1)[1].split(
            "function drawCurrentPriceMarker", 1
        )[0]
    )
    script_path = tmp_path / "price-percent-scale.js"
    script_path.write_text(
        "\n".join(
            (
                "const CANVAS_MONO_FONT = 'monospace';",
                "function finiteSeriesNumber(value) { if (value === null || value === undefined || value === '') return null; const number = Number(value); return Number.isFinite(number) ? number : null; }",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function css(name) { return name; } function calibratedCanvasColor(value) { return value; }",
                "function rgbaFromCssColor(value, alpha) { return `${value}:${alpha}`; } function isLightTheme() { return false; }",
                "let quote = { price: 100, displayOnly: false, status: 'live' };",
                "function currentChartQuoteDisplay() { return quote; } function currentChartDisplayPrice(_snapshot, _latest, value) { return value?.price ?? null; }",
                "const state = { priceScale: { percentHover: true }, crosshair: { visible: true, source: 'price', price: 110, y: 0 } };",
                percent_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "check(pricePercentScaleValue(110, 100) === 10, 'positive reference above failed');",
                "check(pricePercentScaleValue(90, 100) === -10, 'positive reference below failed');",
                "check(pricePercentScaleValue(-90, -100) === 10, 'signed reference above failed');",
                "check(pricePercentScaleValue(-110, -100) === -10, 'signed reference below failed');",
                "check(pricePercentScaleValue(10, 0) === null, 'zero reference must fail closed');",
                "check(formatPricePercentScaleValue(10) === '+10.00%', 'positive format failed');",
                "check(formatPricePercentScaleValue(-10) === '-10.00%', 'negative format failed');",
                "check(formatPricePercentScaleValue(-0.001) === '0.00%', 'negative zero must normalize');",
                "const latest = { close: 100 }; const visible = { bars: [latest], allBars: [latest], start: 0 }; const snapshot = { bars: [latest] };",
                "check(currentPricePercentScaleReference(snapshot, visible)?.price === 100, 'reference must use current chart display projection');",
                "check(currentPricePercentScaleReference({ bars: [{ close: 90 }, latest] }, { bars: [{ close: 90 }], allBars: [{ close: 90 }, latest], start: 0 }) === null, 'current reference must not leak into panned history');",
                "check(pricePercentScaleRows(110, 90, 100, { top: 0 }, 440).filter(row => row.kind === 'tick').length > 7, 'hover percent scale must be denser than the base price scale');",
                "const calls = []; const ctx = { canvas: { height: 160 }, globalAlpha: 1, fillStyle: '', strokeStyle: '', font: '', textAlign: '', textBaseline: '', lineWidth: 1, save() {}, restore() {}, beginPath() {}, moveTo() {}, lineTo() {}, stroke() {}, fillRect(x, y, width, height) { calls.push({ kind: 'rect', x, y, width, height, color: this.fillStyle }); }, fillText(text, x, y) { calls.push({ kind: 'text', text, x, y, color: this.fillStyle, align: this.textAlign }); } };",
                "drawHoveredPricePercentScale(ctx, snapshot, visible, { left: 14, right: 70, top: 0 }, 120, 110, 90, 300);",
                "const texts = calls.filter(call => call.kind === 'text');",
                "const upper = texts.find(call => call.text === '+10.00%'); const zero = texts.find(call => call.text === '0.00%'); const lower = texts.find(call => call.text === '-10.00%');",
                "check(upper?.color === '--green' && lower?.color === '--red' && zero?.color === '--axis', 'direction colors failed');",
                "check(calls.some(call => call.kind === 'rect' && call.x === 230 && call.width === 70 && call.color === '--chart-bg'), 'percent mode must replace the built-in price-axis strip');",
                "check(texts.every(call => call.align === 'right' && call.x === 294), 'percent labels must be right aligned on the price-axis edge');",
                "const beforeHidden = calls.length; state.priceScale.percentHover = false; drawHoveredPricePercentScale(ctx, snapshot, visible, { left: 14, right: 70, top: 0 }, 120, 110, 90, 300); check(calls.length === beforeHidden, 'scale must hide outside local hover');",
                "state.priceScale.percentHover = true; quote = { price: 100, displayOnly: true, status: 'stale' }; drawHoveredPricePercentScale(ctx, snapshot, visible, { left: 14, right: 70, top: 0 }, 120, 110, 90, 300); check(calls.some(call => call.text === 'STALE REF'), 'display-only reference must be visibly typed');",
                "quote = { price: 0, displayOnly: false, status: 'live' }; const beforeZero = calls.length; drawHoveredPricePercentScale(ctx, snapshot, visible, { left: 14, right: 70, top: 0 }, 120, 110, 90, 300); check(calls.length === beforeZero, 'zero current price must suppress scale');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    assert "priceScale: {\n        percentHover: false," in state_source
    assert 'id: "price-percent-scale"' in manager_source
    assert 'enabled: () => typeof drawHoveredPricePercentScale === "function"' in manager_source
    percent_layer = manager_source.split('id: "price-percent-scale"', 1)[1].split(
        "manager.register", 1
    )[0]
    assert 'phase: "objects"' in percent_layer
    assert manager_source.index('id: "price-percent-scale"') < manager_source.index(
        'id: "price-current-marker"'
    )
    assert manager_source.index('id: "price-percent-scale"') < manager_source.index(
        'id: "price-crosshair-price"'
    )
    mousemove_body = interaction_source.split('canvas.addEventListener("mousemove", event =>', 1)[
        1
    ].split('canvas.addEventListener("mouseleave"', 1)[0]
    mouseleave_body = interaction_source.split('canvas.addEventListener("mouseleave", () =>', 1)[
        1
    ].split('canvas.addEventListener("wheel"', 1)[0]
    assert mousemove_body.index(
        "state.priceScale.percentHover = overPriceAxis;"
    ) < mousemove_body.index("applyFrozenContextCrosshair()")
    assert 'requestObjectLayerRedraw("price percent scale hover"' in mousemove_body
    assert "const hoverChanged" in mousemove_body
    assert "renderCharts(" not in mousemove_body
    assert mouseleave_body.index("state.priceScale.percentHover = false;") < mouseleave_body.index(
        "contextMenuCrosshairLocked()"
    )
    assert 'requestObjectLayerRedraw("price percent scale leave"' in mouseleave_body
    reference_body = percent_source.split("function currentPricePercentScaleReference", 1)[1].split(
        "function pricePercentScaleRows", 1
    )[0]
    assert "currentChartQuoteDisplay(15000)" in reference_body
    assert "currentChartDisplayPrice(snapshot, latest, quote)" in reference_body
    assert "state.lastPrice" not in reference_body
    draw_body = percent_source.split("function drawHoveredPricePercentScale", 1)[1]
    assert "ctx.fillRect(axisX, top - 6, axisWidth, height + 12);" in draw_body
    assert "scaleLeft" not in draw_body
    assert "canvasWidth - 6" in draw_body
    crosshair_body = price_source.split("function drawCrosshairPrice", 1)[1].split(
        "function drawCrosshairVolume", 1
    )[0]
    assert "currentPricePercentScaleReference(snapshot, visible)" in crosshair_body
    assert "pricePercentScaleValue(price, percentReference.price)" in crosshair_body
    assert "formatPricePercentScaleValue(percent)" in crosshair_body
    assert 'ctx.textAlign = "right";' in crosshair_body


def test_chart_stream_runtime_exposes_client_status() -> None:
    runtime = ChartStreamRuntime()
    instrument_id = "ibkr|future_root|ES|CME|USD|"
    key = runtime.stream_key(instrument_id, "5m", "1d", "ibkr|ES|route-v1")

    assert runtime.status()["clients"] == 0
    assert runtime.stream_started(key) == 1
    runtime.note_active_chart(instrument_id, "5m", "1d")
    status = runtime.status()

    assert status["clients"] == 1
    assert status["streams"] == 1
    assert status["hot_coordinators"] == 0
    assert status["active_streams"] == [
        {
            "instrument_id": instrument_id,
            "interval": "5m",
            "range": "1d",
            "route_fingerprint": "ibkr|ES|route-v1",
            "clients": 1,
        }
    ]
    assert status["active_chart"]["instrument_id"] == instrument_id
    assert status["active_chart"]["age_seconds"] >= 0.0
    assert runtime.stream_finished(key) == 0


