def test_vitality_polling_provider_uses_heartbeat_for_transport_health(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/17-vitality-health.js").read_text(encoding="utf-8")
    health_source = (
        "function chartStreamAgeMs()"
        + source.split("function chartStreamAgeMs()", 1)[1].split(
            "function renderVitalityHealth",
            1,
        )[0]
    )
    script_path = tmp_path / "vitality-polling-provider-heartbeat.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const QUOTE_STREAM_STALE_MS = 6000;",
                "const CHART_STREAM_STALE_MS = 20000;",
                "const VITALITY_QUOTE_WARN_RATIO = 0.55;",
                "const now = 100000;",
                "Date.now = () => now;",
                "const document = { visibilityState: 'visible' };",
                "const state = { serverSleeping: false, dataSource: 'tinvest', systemHealth: {}, transport: { quote: { openedAt: now - 1000, lastMessageAt: now - 1000 }, chart: { openedAt: now - 60000, lastMessageAt: now - 1000, lastBarsAt: now - 60000 } } };",
                "function vitalityHealthEnabled() { return true; }",
                "function effectiveDataQuality(meta) { return meta.data_quality || {}; }",
                "function marketSnapshotNotice() { return ''; }",
                "function quoteStreamAgeMs() { return 1000; }",
                "function quoteStreamStale() { return false; }",
                "function quoteStreamOpen() { return true; }",
                "function chartStreamOpen() { return true; }",
                "function providerCapability(_provider, capability) { return capability === 'chart_stream'; }",
                health_source,
                "const freshSnapshot = { meta: { data_quality: { status: 'ok', signals_ok: true }, freshness: { status: 'fresh', bar_age_seconds: 5, stale_threshold_seconds: 300 } } };",
                "assert.equal(chartStreamAgeMs(), 1000);",
                "assert.equal(chartStreamStaleNow(), false);",
                "assert.equal(computeVitalityHealthState(freshSnapshot).state, 'alive');",
                "state.transport.chart.lastMessageAt = 0;",
                "state.transport.chart.lastBarsAt = now - 1000;",
                "assert.equal(chartStreamAgeMs(), 60000);",
                "assert.equal(chartStreamStaleNow(), true);",
                "assert.equal(computeVitalityHealthState(freshSnapshot).state, 'dead');",
                "state.transport.chart.lastMessageAt = now - 1000;",
                "const staleBarSnapshot = { meta: { data_quality: { status: 'ok', signals_ok: true }, freshness: { status: 'stale', bar_age_seconds: 400, stale_threshold_seconds: 300 } } };",
                "assert.equal(chartStreamStaleNow(), false);",
                "assert.equal(computeVitalityHealthState(staleBarSnapshot).state, 'dead');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


def test_vitality_transport_health_obeys_active_provider_capabilities(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/17-vitality-health.js").read_text(encoding="utf-8")
    health_source = (
        "function computeVitalityHealthState(snapshot = state.snapshot)"
        + source.split(
            "function computeVitalityHealthState(snapshot = state.snapshot)",
            1,
        )[1].split("function renderVitalityHealth", 1)[0]
    )
    script_path = tmp_path / "vitality-provider-capabilities.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const QUOTE_STREAM_STALE_MS = 6000;",
                "const VITALITY_QUOTE_WARN_RATIO = 0.55;",
                "const document = { visibilityState: 'visible' };",
                "const now = 100000;",
                "const state = { serverSleeping: false, dataSource: 'tinvest', systemHealth: {}, transport: { quote: { openedAt: now - 60000, lastMessageAt: now - 60000 }, chart: { openedAt: now - 60000, lastMessageAt: now - 1000, retryTimer: null } } };",
                "const capabilities = new Set(['chart_stream']);",
                "const calls = { quoteAge: 0, quoteStale: 0, quoteOpen: 0 };",
                "const transport = { chartAge: 1000, chartStale: false, chartOpen: true, quoteStale: true, quoteOpen: true };",
                "function vitalityHealthEnabled() { return true; }",
                "function effectiveDataQuality(meta) { return meta.data_quality || {}; }",
                "function marketSnapshotNotice(snapshot) { return snapshot.meta.data_quality.warning || ''; }",
                "function providerCapability(_provider, capability) { return capabilities.has(capability); }",
                "function quoteStreamAgeMs() { calls.quoteAge += 1; return 60000; }",
                "function quoteStreamStale() { calls.quoteStale += 1; return transport.quoteStale; }",
                "function quoteStreamOpen() { calls.quoteOpen += 1; return transport.quoteOpen; }",
                "function chartStreamAgeMs() { return transport.chartAge; }",
                "function chartStreamStaleNow() { return transport.chartStale; }",
                "function chartStreamOpen() { return transport.chartOpen; }",
                health_source,
                "const freshSnapshot = { meta: { data_quality: { status: 'ok', signals_ok: true }, freshness: { status: 'fresh', bar_age_seconds: 10, stale_threshold_seconds: 300 } } };",
                "state.transport.chart.openedAt = 0;",
                "state.transport.chart.lastMessageAt = 0;",
                "transport.chartOpen = false;",
                "const initialChart = computeVitalityHealthState(freshSnapshot);",
                "assert.equal(initialChart.state, 'warn');",
                "assert.equal(initialChart.lines.includes('Chart transport: disconnected'), true);",
                "state.transport.chart.openedAt = now - 60000;",
                "state.transport.chart.lastMessageAt = now - 1000;",
                "transport.chartOpen = true;",
                "const warning = 'SESSION_UNKNOWN: provider trading-session metadata is unavailable.';",
                "const sessionUnknown = { meta: { data_quality: { status: 'session_unknown', signals_ok: false, session_unknown: true, warning }, freshness: { status: 'fresh', bar_age_seconds: 10, stale_threshold_seconds: 300 } } };",
                "const model = computeVitalityHealthState(sessionUnknown);",
                "assert.equal(model.state, 'warn');",
                "assert.deepEqual(calls, { quoteAge: 0, quoteStale: 0, quoteOpen: 0 });",
                "assert.equal(model.lines.some(line => line.startsWith('Quote ')), false);",
                "assert.equal(model.lines.includes('Chart stream age: 1s'), true);",
                "assert.equal(model.lines.includes('Chart transport: connected'), true);",
                "assert.equal([...model.lines, model.error || ''].filter(line => line === warning).length, 1);",
                "assert.equal(model.error, '');",
                "transport.chartOpen = false;",
                "state.transport.chart.openedAt = 0;",
                "state.transport.chart.lastMessageAt = 0;",
                "state.transport.chart.retryTimer = {};",
                "const disconnectedChart = computeVitalityHealthState(sessionUnknown);",
                "assert.equal(disconnectedChart.state, 'dead');",
                "assert.equal(disconnectedChart.lines.includes('Chart transport: disconnected'), true);",
                "assert.equal(disconnectedChart.error, 'Live transport is stale or disconnected.');",
                "capabilities.add('live_quote_polling');",
                "transport.chartOpen = true;",
                "state.transport.chart.openedAt = now - 60000;",
                "state.transport.chart.lastMessageAt = now - 1000;",
                "state.transport.chart.retryTimer = null;",
                "const quoteCapable = computeVitalityHealthState(freshSnapshot);",
                "assert.equal(quoteCapable.state, 'dead');",
                "assert.equal(quoteCapable.lines.includes('Quote stream age: 60s'), true);",
                "assert.equal(quoteCapable.lines.includes('Quote transport: connected'), true);",
                "assert.deepEqual(calls, { quoteAge: 1, quoteStale: 1, quoteOpen: 1 });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


def test_vitality_health_separates_entry_gates_from_system_failures(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/17-vitality-health.js").read_text(encoding="utf-8")
    health_source = (
        "function computeVitalityHealthState(snapshot = state.snapshot)"
        + source.split(
            "function computeVitalityHealthState(snapshot = state.snapshot)",
            1,
        )[1].split("function renderVitalityHealth", 1)[0]
    )
    script_path = tmp_path / "vitality-health-entry-gates.js"
    script_path.write_text(
        "\n".join(
            (
                "const QUOTE_STREAM_STALE_MS = 1000;",
                "const VITALITY_QUOTE_WARN_RATIO = 0.55;",
                "const document = { visibilityState: 'visible' };",
                "const state = { serverSleeping: false, dataSource: 'ibkr', systemHealth: {}, transport: { quote: { openedAt: 1, lastMessageAt: 1 }, chart: { openedAt: 0, lastBarsAt: 0 } } };",
                "const transport = { quoteAge: 0, quoteStale: false, quoteConnected: true, chartAge: Infinity, chartStale: false };",
                "function vitalityHealthEnabled() { return true; }",
                "function effectiveDataQuality(meta) { return meta.data_quality || {}; }",
                "function marketSnapshotNotice() { return ''; }",
                "function quoteStreamAgeMs() { return transport.quoteAge; }",
                "function quoteStreamStale() { return transport.quoteStale; }",
                "function chartStreamAgeMs() { return transport.chartAge; }",
                "function chartStreamStaleNow() { return transport.chartStale; }",
                "function providerCapability() { return true; }",
                "function quoteStreamOpen() { return transport.quoteConnected; }",
                health_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const fresh = { status: 'ok', bar_age_seconds: 10, stale_threshold_seconds: 1200 };",
                "const old = { status: 'stale', bar_age_seconds: 86400, stale_threshold_seconds: 1200 };",
                "const snapshot = (data_quality, freshness = fresh) => ({ meta: { data_quality, freshness } });",
                "const closed = computeVitalityHealthState(snapshot({ status: 'market_closed', signals_ok: false, market_closed: true, warning: 'MARKET CLOSED' }, old));",
                "check(closed.state === 'warn', `typed market close became ${closed.state}`);",
                "const warmup = computeVitalityHealthState(snapshot({ status: 'session_warmup', signals_ok: false, session_warmup: true }, old));",
                "check(warmup.state === 'warn', `typed session warmup became ${warmup.state}`);",
                "const untypedWarmup = computeVitalityHealthState(snapshot({ status: 'session_warmup', signals_ok: false }, old));",
                "check(untypedWarmup.state === 'dead', 'untyped warmup bypassed stale health');",
                "const unknown = computeVitalityHealthState(snapshot({ status: 'session_unknown', signals_ok: false, session_unknown: true }, old));",
                "check(unknown.state === 'warn', `typed unknown session became ${unknown.state}`);",
                "const entryBlocked = computeVitalityHealthState(snapshot({ status: 'execution_blocked', signals_ok: false }));",
                "check(entryBlocked.state === 'warn', `entry gate became ${entryBlocked.state}`);",
                "const stale = computeVitalityHealthState(snapshot({ status: 'stale', signals_ok: false }, old));",
                "check(stale.state === 'dead', 'open-market stale data was not critical');",
                "const noData = computeVitalityHealthState(snapshot({ status: 'no_data', signals_ok: false, empty_history: true }));",
                "check(noData.state === 'dead', 'missing confirmed data was not critical');",
                "const failed = computeVitalityHealthState(snapshot({ status: 'provider_error', signals_ok: false }));",
                "check(failed.state === 'dead', 'provider error was not critical');",
                "transport.quoteConnected = false;",
                "const disconnected = computeVitalityHealthState(snapshot({ status: 'ok', signals_ok: true }));",
                "check(disconnected.state === 'dead', 'disconnected live transport was not critical');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


