def test_quote_snapshot_and_delta_merge_modes_preserve_exact_scope(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-live-quote-helpers.js").read_text(
        encoding="utf-8"
    )
    merge_source = (
        "function screenerRowIdentityKey"
        + source.split(
            "function screenerRowIdentityKey",
            1,
        )[1].split("function instrumentRouteFingerprint", 1)[0]
    )
    frame_contract_source = source.split("function rowHasLiveQuote", 1)[0]
    handler_source = (
        "function handleQuoteSnapshotRows"
        + source.split("function handleQuoteSnapshotRows", 1)[1].split(
            "function snapshotMatchesCurrentRoute",
            1,
        )[0]
    )
    script_path = tmp_path / "quote-merge-modes.js"
    script_path.write_text(
        "\n".join(
            (
                "let now = 20000; Date.now = () => now;",
                "const window = { QUOTE_STREAM_ROW_CONTRACT_MANIFEST: "
                f"{json.dumps(quote_stream_row_contract_manifest(), separators=(',', ':'))} }};",
                "const LIVE_QUOTE_DISPLAY_TTL_MS = 5000;",
                "const state = { transport: { quote: { cacheEpoch: '', cacheGeneration: 0 } }, screener: [",
                "  { instrument_id: 'outside', route_fingerprint: 'r0', price: 1, _updated_at: 1 },",
                "  { instrument_id: 'a', route_fingerprint: 'r1', price: 2, trend_points: [1], _updated_at: 1 },",
                "  { instrument_id: 'b', route_fingerprint: 'r2', price: 3, trend_points: [2], _updated_at: 1 },",
                "] };",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function rowHasLiveQuote(row) { return row?.live_quote === true && Number.isFinite(Number(row?.price)); }",
                "function quoteRowsIncludeCurrentRoute() { return false; }",
                "function applyCurrentScreenerQuote() { return false; }",
                "function currentQuoteRow() { return null; }",
                "function syncLiveQuoteFromScreenerRow() { return false; }",
                "function updateDocumentTitleFromScreenerQuote() {}",
                "function renderInstruments() {}",
                "function setScreenerStateLabel() {}",
                frame_contract_source,
                merge_source,
                handler_source,
                "function quoteRow(instrumentId, routeFingerprint, price) {",
                "  const ts = '2026-07-16T14:45:00+00:00';",
                "  return { key: instrumentId, display: instrumentId, instrument_id: instrumentId, route_fingerprint: routeFingerprint, provider_symbol: instrumentId, price, bid: price - 1, ask: price + 1, last: price, quote_close: null, quote_ts: ts, price_source: 'last', quote_time_basis: 'provider_event', quote_provider_ts: ts, quote_received_at: ts, quote_status: 'live', quote_entitlement: 'live', quote_is_delayed: false, quote_is_stale: false, last_provider_ts: ts, last_status: 'live', bid_ask_received_at: ts, bid_ask_status: 'live', change: null, change_pct: null, previous_session_close: null, change_base: null, source: 'provider:quote-live', live_quote: true, warning: '', contract: null, local_symbol: null, contract_month: null, contract_rollover_due: false, contract_rollover_warning: null, contract_rollover_new: false, contract_rollover_new_message: null };",
                "}",
                "const scope = new Set([JSON.stringify(['a', 'r1']), JSON.stringify(['b', 'r2'])]);",
                "if (admitScreenerCacheRevision({ cacheEpoch: 'epoch-a', cacheGeneration: 9 }) !== false) process.exit(1);",
                "if (state.transport.quote.cacheEpoch !== '') process.exit(11);",
                "if (admitScreenerCacheRevision({ cacheEpoch: 'epoch-a', cacheGeneration: 9, allowEpochChange: true }) !== true) process.exit(12);",
                "mergeScreenerRows([",
                "  quoteRow('a', 'r1', 20),",
                "  quoteRow('b', 'r2', 30),",
                "], { mode: 'snapshot', scopeKeys: scope, cacheEpoch: 'epoch-a', cacheGeneration: 10, allowEpochChange: true });",
                "if (state.screener.length !== 3) process.exit(2);",
                "if (!state.screener.some(row => row.instrument_id === 'outside')) process.exit(3);",
                "const a = state.screener.find(row => row.instrument_id === 'a');",
                "if (!a || a.price !== 20 || Object.hasOwn(a, 'trend_points')) process.exit(4);",
                "state.screener.find(row => row.instrument_id === 'b')._updated_at = 1;",
                "now = 40000;",
                "mergeScreenerRows([quoteRow('a', 'r1', 21)], { mode: 'delta', cacheEpoch: 'epoch-a', cacheGeneration: 11 });",
                "const b = state.screener.find(row => row.instrument_id === 'b');",
                "if (!b || b.price !== 30) process.exit(5);",
                "let partialRejected = false; try { mergeScreenerRows([{ instrument_id: 'a', route_fingerprint: 'r1', price: 999 }], { mode: 'delta', cacheEpoch: 'epoch-a', cacheGeneration: 12 }); } catch (error) { partialRejected = String(error).includes('SCREENER_QUOTE_FRAME_INCOMPLETE'); }",
                "if (!partialRejected || state.transport.quote.cacheGeneration !== 11 || state.screener.find(row => row.instrument_id === 'a')?.price !== 21) process.exit(17);",
                "let malformedRejected = false; try { mergeScreenerRows([{ ...quoteRow('a', 'r1', 999), price: '999' }], { mode: 'delta', cacheEpoch: 'epoch-a', cacheGeneration: 12 }); } catch (error) { malformedRejected = String(error).includes('SCREENER_QUOTE_FRAME_INVALID'); }",
                "if (!malformedRejected || state.transport.quote.cacheGeneration !== 11 || state.screener.find(row => row.instrument_id === 'a')?.price !== 21) process.exit(18);",
                "let rolloverRejected = false; try { mergeScreenerRows([{ ...quoteRow('a', 'r1', 999), contract_rollover_warning: { status: 'rollover_due', days_left: '2', expiry_date: '2026-09-18', contract_month: '202609', message: 'Roll soon' } }], { mode: 'delta', cacheEpoch: 'epoch-a', cacheGeneration: 12 }); } catch (error) { rolloverRejected = String(error).includes('SCREENER_QUOTE_FRAME_INVALID'); }",
                "if (!rolloverRejected || state.transport.quote.cacheGeneration !== 11 || state.screener.find(row => row.instrument_id === 'a')?.price !== 21) process.exit(19);",
                "if (mergeScreenerRows([quoteRow('a', 'r1', 999)], { mode: 'http', cacheEpoch: 'epoch-a', cacheGeneration: 10 }) !== null) process.exit(6);",
                "if (state.screener.find(row => row.instrument_id === 'a')?.price !== 21) process.exit(7);",
                "if (mergeScreenerRows([quoteRow('a', 'r1', 998)], { mode: 'http', cacheEpoch: 'epoch-b', cacheGeneration: 1 }) !== null) process.exit(8);",
                "if (state.screener.find(row => row.instrument_id === 'a')?.price !== 21) process.exit(9);",
                "mergeScreenerRows([quoteRow('a', 'r1', 22)], { mode: 'snapshot', scopeKeys: new Set([JSON.stringify(['a', 'r1'])]), cacheEpoch: 'epoch-b', cacheGeneration: 1, allowEpochChange: true });",
                "if (state.screener.length !== 1 || state.screener[0].price !== 22) process.exit(10);",
                "const rejected = handleQuoteSnapshotRows([quoteRow('a', 'r1', 999)], 'live', { mode: 'snapshot', scopeKeys: new Set([JSON.stringify(['a', 'r1'])]), cacheEpoch: 'epoch-b', cacheGeneration: 0, allowEpochChange: true });",
                "if (rejected.admitted !== false || rejected.currentRouteObserved !== false) process.exit(13);",
                "if (state.screener[0].price !== 22 || state.transport.quote.cacheGeneration !== 1) process.exit(14);",
                "const admittedWithoutCurrentRoute = handleQuoteSnapshotRows([], 'live', { mode: 'delta', cacheEpoch: 'epoch-b', cacheGeneration: 2 });",
                "if (admittedWithoutCurrentRoute.admitted !== true || admittedWithoutCurrentRoute.currentRouteObserved !== false) process.exit(15);",
                "if (state.transport.quote.cacheGeneration !== 2) process.exit(16);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


