def test_quote_stream_transport_requires_shared_worker_and_fails_closed(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/18-stream-sharing.js").read_text(encoding="utf-8")
    transport_source = (
        "const QUOTE_SHARED_WORKER_NAME"
        + source.split(
            "const QUOTE_SHARED_WORKER_NAME",
            1,
        )[1].split("function sharedStreamStorageKey", 1)[0]
    )
    script_path = tmp_path / "quote-shared-transport.js"
    script_path.write_text(
        "\n".join(
            (
                "const telemetry = {};",
                "const timers = new Map(); let nextTimer = 1;",
                "const state = { transport: { quote: { mode: 'idle' } } };",
                "const WebSocket = { CONNECTING: 0, OPEN: 1, CLOSING: 2, CLOSED: 3 };",
                "class FakePort {",
                "  constructor() { this.posts = []; this.closed = false; }",
                "  start() { this.started = true; }",
                "  postMessage(message) { this.posts.push(message); }",
                "  close() { this.closed = true; }",
                "  emit(message) { this.onmessage({ data: message }); }",
                "}",
                "class FakeSharedWorker {",
                "  constructor(url, name) { if (FakeSharedWorker.failCreation) throw new Error('create failed'); this.url = url; this.name = name; this.port = new FakePort(); FakeSharedWorker.instances.push(this); }",
                "  emitError(message) { this.onerror?.({ message, preventDefault() { this.prevented = true; } }); }",
                "}",
                "FakeSharedWorker.instances = []; FakeSharedWorker.failCreation = false;",
                "const window = {",
                "  SharedWorker: FakeSharedWorker, MARTINCALL_QUOTE_WORKER_URL: '/assets/quote-stream-worker.js?v=test',",
                "  setInterval() { return 7; }, clearInterval() {},",
                "  setTimeout(callback) { const id = nextTimer++; timers.set(id, callback); return id; }, clearTimeout(id) { timers.delete(id); },",
                "  mcTelemetrySet(key, value) { telemetry[key] = value; },",
                "  mcTelemetryMax(key, value) { telemetry[key] = Math.max(Number(telemetry[key] || 0), Number(value || 0)); },",
                "  mcTelemetryInc(key) { telemetry[key] = Number(telemetry[key] || 0) + 1; },",
                "};",
                "function requestErrorMessage() { return 'worker failed'; }",
                transport_source,
                "const key = JSON.stringify([[['id-a', 'route-a']], '5m']);",
                "const subscription = { interval: '5m', routes: [{ instrument_id: 'id-a', route_fingerprint: 'route-a' }] };",
                "const shared = createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription);",
                "const firstPort = FakeSharedWorker.instances[0].port;",
                "if (!shared.sharedQuoteTransport || firstPort.posts[0].type !== 'subscribe') process.exit(2);",
                "if (firstPort.posts[0].key !== key || firstPort.posts[0].subscription !== subscription) process.exit(3);",
                "if (FakeSharedWorker.instances[0].name !== 'aef-quote-stream-v1:/assets/quote-stream-worker.js?v=test') process.exit(14);",
                "let opens = 0; let raw = ''; let reportedError = null; shared.onopen = () => { opens += 1; }; shared.onmessage = event => { raw = event.data; }; shared.onerror = event => { reportedError = event; };",
                "firstPort.emit({ type: 'open', key, shared_ports: 2, shared_groups: 1, worker_sent_at: Date.now() });",
                "firstPort.emit({ type: 'error', key, code: 'QUOTE_WORKER_TEST', message: 'typed failure', fatal: true, shared_ports: 2, shared_groups: 1 });",
                "if (reportedError?.code !== 'QUOTE_WORKER_TEST' || reportedError?.fatal !== true || telemetry['quote_transport.last_error_code'] !== 'QUOTE_WORKER_TEST') process.exit(15);",
                "firstPort.emit({ type: 'message', key, data: '{\"type\":\"quote_snapshot\"}', shared_ports: 2, shared_groups: 1 });",
                'if (opens !== 1 || raw !== \'{"type":"quote_snapshot"}\' || shared.readyState !== WebSocket.OPEN) process.exit(4);',
                "if (state.transport.quote.mode !== 'shared_worker' || telemetry['quote_transport.shared_ports'] !== 2 || telemetry['quote_transport.shared_groups'] !== 1) process.exit(5);",
                "let closes = 0; shared.onclose = () => { closes += 1; }; shared.close(1000, 'done');",
                "if (firstPort.posts.at(-1).type !== 'close' || firstPort.posts.at(-1).code !== 1000 || firstPort.closed || shared.readyState !== WebSocket.CLOSING || closes !== 0) process.exit(6);",
                "firstPort.emit({ type: 'close', key, code: 1000, reason: 'done', close_ack: true, shared_ports: 0, shared_groups: 0 });",
                "if (!firstPort.closed || shared.readyState !== WebSocket.CLOSED || closes !== 1) process.exit(10);",
                "const restarting = createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription);",
                "const secondPort = FakeSharedWorker.instances[1].port; restarting.close(4002, 'resync');",
                "if (secondPort.posts.at(-1).type !== 'restart' || secondPort.closed || restarting.readyState !== WebSocket.CLOSING) process.exit(7);",
                "secondPort.emit({ type: 'close', key, code: 4002, reason: 'resync', restart: true, shared_ports: 0, shared_groups: 0 });",
                "if (!secondPort.closed || restarting.readyState !== WebSocket.CLOSED) process.exit(11);",
                "const deadWorker = createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription);",
                "const deadPort = FakeSharedWorker.instances[2].port; let deadClose = null; deadWorker.onclose = event => { deadClose = event; };",
                "deadWorker.close(1000, 'dead worker');",
                "if (deadPort.closed || deadWorker.readyState !== WebSocket.CLOSING || timers.size !== 1) process.exit(12);",
                "Array.from(timers.values())[0]();",
                "if (!deadPort.closed || deadWorker.readyState !== WebSocket.CLOSED || deadClose?.closeAckTimeout !== true) process.exit(13);",
                "delete window.SharedWorker;",
                "let unsupported = null; try { createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription); } catch (error) { unsupported = error; }",
                "if (unsupported?.code !== 'QUOTE_SHARED_WORKER_UNSUPPORTED' || state.transport.quote.mode !== 'unavailable') process.exit(8);",
                "window.SharedWorker = FakeSharedWorker;",
                "window.MARTINCALL_QUOTE_WORKER_URL = ''; let assetMissing = null; try { createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription); } catch (error) { assetMissing = error; }",
                "if (assetMissing?.code !== 'QUOTE_SHARED_WORKER_ASSET_MISSING') process.exit(9); window.MARTINCALL_QUOTE_WORKER_URL = '/assets/quote-stream-worker.js?v=test';",
                "const startupFailed = createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription);",
                "const startupPort = FakeSharedWorker.instances.at(-1).port; let startupClose = null; startupFailed.onclose = event => { startupClose = event; };",
                "const startupCallback = Array.from(timers.values())[0]; startupCallback();",
                "if (!startupPort.closed || startupFailed.readyState !== WebSocket.CLOSED || startupClose?.sharedTransport !== true) process.exit(16);",
                "const startupRetry = createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription);",
                "if (!startupRetry.sharedQuoteTransport) process.exit(17);",
                "const loadFailed = createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription);",
                "const loadWorker = FakeSharedWorker.instances.at(-1); let loadClose = null; loadFailed.onclose = event => { loadClose = event; };",
                "loadWorker.emitError('asset failed');",
                "if (!loadWorker.port.closed || loadFailed.readyState !== WebSocket.CLOSED || loadClose?.sharedTransport !== true) process.exit(18);",
                "FakeSharedWorker.failCreation = true; let createFailure = null; try { createQuoteStreamTransport(key, 'ws://localhost/ws/quotes', subscription); } catch (error) { createFailure = error; }",
                "if (createFailure?.code !== 'QUOTE_SHARED_WORKER_CREATE_ERROR' || telemetry['quote_transport.mode'] !== 'unavailable') process.exit(19);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_quote_stream_page_scope_change_detaches_only_local_shared_adapter(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-live-stream-connect.js").read_text(
        encoding="utf-8"
    )
    connect_source = (
        "function connectQuoteStream(force = false)"
        + source.split(
            "function connectQuoteStream(force = false)",
            1,
        )[1].split("const CHART_STREAM_RECONNECT_MAX_MS", 1)[0]
    )
    script_path = tmp_path / "quote-stream-local-scope-detach.js"
    script_path.write_text(
        "\n".join(
            (
                "const vm = require('vm');",
                f"const connectSource = {json.dumps(connect_source)};",
                "const sharedGroup = [];",
                "function createPage(name) {",
                "  const routes = [['coinbase|contract|BTC-USD', 'coinbase|contract|BTC-USD']];",
                "  const state = { serverSleeping: false, instrumentId: routes[0][0], routeFingerprint: routes[0][1], timeframe: '5m', transport: { quote: { socket: null, key: '', epoch: 0 } } };",
                "  const context = {",
                "    URLSearchParams, WebSocket: { CONNECTING: 0, OPEN: 1, CLOSED: 3 }, state,",
                "    document: { getElementById() { return null; } },",
                "    window: { location: { protocol: 'http:', host: 'terminal.test' }, mcTelemetryInc() {}, setTimeout() { return 1; }, clearTimeout() {} },",
                "    quoteStreamRoutes() { return routes; }, quoteStreamStale() { return false; },",
                "    exactIdentityText(value) { return typeof value === 'string' ? value : ''; },",
                "    instrumentRouteFingerprint() { return state.routeFingerprint; },",
                "    setScreenerStateLabel() {}, debugStep() {},",
                "    closeQuoteStream() { state.transport.quote.socket = null; state.transport.quote.key = ''; state.transport.quote.epoch += 1; },",
                "    createQuoteStreamTransport(key) {",
                "      const socket = { readyState: 0, sharedQuoteTransport: true, closeCalls: [], close(code, reason) { this.closeCalls.push({ code, reason }); this.readyState = 2; } };",
                "      sharedGroup.push({ name, key, socket }); return socket;",
                "    },",
                "  };",
                "  vm.createContext(context); vm.runInContext(connectSource, context); context.connectQuoteStream(false); return context;",
                "}",
                "const first = createPage('first'); const second = createPage('second');",
                "if (sharedGroup.length !== 2 || sharedGroup[0].key !== sharedGroup[1].key) process.exit(2);",
                "first.state.timeframe = '15m';",
                'first.state.transport.quote.socket.onmessage({ data: \'{"type":"quote_heartbeat","interval":"5m","sequence":2}\' });',
                "if (sharedGroup[0].socket.closeCalls.length !== 1) process.exit(3);",
                "if (sharedGroup[0].socket.closeCalls[0].code !== 1000 || sharedGroup[0].socket.closeCalls[0].reason !== 'quote page scope changed') process.exit(4);",
                "if (sharedGroup[0].socket.closeCalls.some(item => item.code === 4002)) process.exit(5);",
                "if (sharedGroup[1].socket.closeCalls.length !== 0) process.exit(6);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


