def test_cross_window_crosshair_is_exact_scoped_coalesced_and_loop_free(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/18-stream-sharing.js").read_text(encoding="utf-8")
    link_source = (
        "const WINDOW_LINK_CHANNEL_NAME"
        + source.split(
            "const WINDOW_LINK_CHANNEL_NAME",
            1,
        )[1]
    )
    script_path = tmp_path / "cross-window-crosshair.js"
    script_path.write_text(
        "\n".join(
            (
                "let now = 10000; Date.now = () => now;",
                "let nextFrame = 1; const frames = [];",
                "function requestAnimationFrame(callback) { const row = { id: nextFrame++, callback, cancelled: false }; frames.push(row); return row.id; }",
                "function cancelAnimationFrame(id) { const row = frames.find(item => item.id === id); if (row) row.cancelled = true; }",
                "function runFrame() { let row; do { row = frames.shift(); } while (row && row.cancelled); if (row) row.callback(); }",
                "class FakeBroadcastChannel {",
                "  constructor(name) { this.name = name; this.posts = []; FakeBroadcastChannel.instance = this; }",
                "  postMessage(payload) { this.posts.push(payload); }",
                "  close() { this.closed = true; }",
                "}",
                "const remotePerf = [];",
                "const window = {",
                "  BroadcastChannel: FakeBroadcastChannel, mcTelemetryInc() {},",
                "  mcPerfStart(label) { return { label, start: now }; },",
                "  mcPerfEnd(token) { if (token) remotePerf.push({ label: token.label, ms: now - token.start }); },",
                "};",
                "const BroadcastChannel = FakeBroadcastChannel;",
                "const state = {",
                "  clientId: 'local', workspaceSlot: '2', instrumentId: 'instrument-a', timeframe: '5m',",
                "  drawing: { drag: null, draft: null }, alerts: { drag: null }, optionTargets: { draggingId: null },",
                "  paperTrading: { dragOrder: null, dragEntryLabel: null }, crosshair: {},",
                "};",
                "const view = { dragActive: false };",
                "let refreshes = 0;",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function normalizeWatchlistPresentation(value) { return value && ['classic', 'trend'].includes(value.display_mode) && Number.isSafeInteger(value.revision) && value.revision >= 0 ? { display_mode: value.display_mode, revision: value.revision } : null; }",
                "let presentationChanged = true; const appliedPresentations = []; function applyWatchlistInstrumentPresentation(instrumentId, presentation, options = {}) { appliedPresentations.push({ instrumentId, presentation, options }); return presentationChanged; }",
                "const trendLoads = []; function loadWatchlistTrends(options = {}) { trendLoads.push(options); }",
                "function instrumentRouteFingerprint() { return 'route-a'; }",
                "function contextMenuCrosshairLocked() { return false; }",
                "function requestErrorMessage(error) { return String(error); }",
                "function debugStep() {}",
                "const isoTs = '2026-07-21T12:00:00.000Z';",
                "const provisionalTs = '2026-07-21T12:05:00.000Z';",
                "const linkedBars = [{ ts: '2026-07-21T11:55:00.000Z', closed: true, state: 'confirmed', authoritative: true }, { ts: isoTs, closed: true, state: 'confirmed', authoritative: true, bar_slot: 5 }, { ts: provisionalTs, closed: false, state: 'forming', authoritative: false }];",
                "function priceChartGeometry() { return { bars: linkedBars, allBars: linkedBars, start: 0, pad: { left: 10, right: 10, top: 0 }, rect: { width: 500 }, priceH: 100, x: index => 20 + index * 10, y: price => 100 - price / 2 }; }",
                "function drawingAxisFromGeo(geo) { return geo; }",
                "function drawingTimestampIdentity(value) { const parsed = Date.parse(value || ''); return Number.isFinite(parsed) ? String(parsed) : ''; }",
                "function barIsConfirmedClosed(bar) { return Boolean(bar?.closed === true && bar?.state === 'confirmed'); }",
                "function isChartPlotXVisible(x, pad, width) { return x >= pad.left && x <= width - pad.right; }",
                "function refreshCrosshairOverlays() { refreshes += 1; }",
                link_source,
                "setupWindowLinkChannel();",
                "for (let index = 0; index < 10; index += 1) publishLinkedCrosshair({ visible: true, source: 'price', ts: isoTs, barSlot: index, price: 100 });",
                "if (frames.length !== 1) process.exit(2);",
                "runFrame();",
                "const channel = FakeBroadcastChannel.instance;",
                "if (channel.posts.length !== 1) process.exit(3);",
                "const sent = channel.posts[0];",
                "if (sent.instrument_id !== 'instrument-a' || sent.route_fingerprint !== 'route-a' || sent.timeframe !== '5m' || sent.workspace_slot !== '2') process.exit(4);",
                "if (Object.hasOwn(sent, 'symbol')) process.exit(5);",
                "if (Object.hasOwn(sent, 'bar_slot') || Object.hasOwn(sent, 'barSlot')) process.exit(28);",
                "now += 300;",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'wrong', sequence: 1, sent_at: now, instrument_id: 'other' });",
                "if (frames.length !== 0) process.exit(6);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 1, sent_at: now, visible: true, bar_slot: 5, price: 100 });",
                "if (frames.length !== 1) process.exit(7);",
                "now += 7;",
                "runFrame();",
                "if (!state.crosshair.visible || state.crosshair.x !== 30 || refreshes !== 1) process.exit(8);",
                "if (channel.posts.length !== 1) process.exit(9);",
                "if (remotePerf.length !== 1 || remotePerf[0].label !== 'crosshairRemoteToCommit' || remotePerf[0].ms !== 7) process.exit(14);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-b', sequence: 1, sent_at: now, visible: false });",
                "runFrame();",
                "if (!state.crosshair.visible) process.exit(10);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 1, sent_at: now, visible: false });",
                "if (frames.length !== 0) process.exit(11);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 2, sent_at: now, visible: false });",
                "runFrame();",
                "if (state.crosshair.visible) process.exit(12);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'stale', sequence: 1, sent_at: now - 2000 });",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'local', sequence: 99, sent_at: now });",
                "if (frames.length !== 0 || channel.posts.length !== 1) process.exit(13);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-c', sequence: 1, sent_at: now, visible: true, bar_slot: 4, price: 100 });",
                "now += 2000; runFrame();",
                "if (state.crosshair.visible) process.exit(15);",
                "publishLinkedCrosshair({ visible: false, source: 'price', ts: isoTs, barSlot: 4, price: 100 }, { visible: false, immediate: true });",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-d', sequence: 1, sent_at: now, visible: true, ts: isoTs, bar_slot: 4, price: 100 });",
                "runFrame();",
                "if (!state.crosshair.visible || state.crosshair.x !== 30) process.exit(16);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-d', sequence: 2, sent_at: now, visible: false }); runFrame();",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 3, sent_at: now, visible: true, ts: isoTs, bar_slot: 6, price: 100 });",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-b', sequence: 2, sent_at: now, visible: false });",
                "if (frames.length !== 1) process.exit(17);",
                "runFrame();",
                "if (!state.crosshair.visible || state.crosshair.x !== 30) process.exit(18);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 4, sent_at: now, visible: true, ts: isoTs, bar_slot: 7, price: 1000 }); runFrame();",
                "if (!state.crosshair.visible || state.crosshair.source !== 'time' || state.crosshair.price !== null) process.exit(19);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 5, sent_at: now, visible: true, ts: provisionalTs, bar_slot: 100, price: 100 }); runFrame();",
                "if (state.crosshair.visible) process.exit(20);",
                "queueLinkedCrosshairMessage({ ...sent, source_client_id: 'peer-a', sequence: 6, sent_at: now, visible: true, ts: 'not-a-date', bar_slot: 3, price: 100 }); runFrame();",
                "if (state.crosshair.visible) process.exit(21);",
                "if (channel.posts.length !== 2) process.exit(22);",
                "publishWatchlistPresentation('instrument-a', { display_mode: 'trend', revision: 4 });",
                "if (channel.posts.length !== 3) process.exit(23);",
                "const presentationMessage = channel.posts[2];",
                "if (presentationMessage.type !== 'watchlist_presentation_changed' || presentationMessage.instrument_id !== 'instrument-a') process.exit(24);",
                "if (Object.hasOwn(presentationMessage, 'workspace_slot') || Object.hasOwn(presentationMessage, 'route_fingerprint') || Object.hasOwn(presentationMessage, 'timeframe') || Object.hasOwn(presentationMessage, 'symbol')) process.exit(25);",
                "channel.onmessage({ data: presentationMessage });",
                "if (appliedPresentations.length !== 0) process.exit(26);",
                "channel.onmessage({ data: { ...presentationMessage, source_client_id: 'peer-presentation' } });",
                "if (appliedPresentations.length !== 1 || appliedPresentations[0].presentation.revision !== 4 || appliedPresentations[0].options.refreshTrend !== false) process.exit(27);",
                "if (channel.posts.length !== 3) process.exit(28);",
                "if (trendLoads.length !== 1 || trendLoads[0].force) process.exit(29);",
                "if (!(trendLoads[0].instrumentIds instanceof Set) || !trendLoads[0].instrumentIds.has('instrument-a')) process.exit(30);",
                "presentationChanged = false;",
                "channel.onmessage({ data: { ...presentationMessage, source_client_id: 'peer-equal-revision' } });",
                "if (appliedPresentations.length !== 2 || trendLoads.length !== 2) process.exit(31);",
                "if (trendLoads[1].force || !trendLoads[1].instrumentIds.has('instrument-a')) process.exit(32);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    interaction = Path(
        "src/aef_terminal/ui/assets/js/60-interactions-drawings-alerts.js"
    ).read_text(encoding="utf-8")
    renderer = Path("src/aef_terminal/ui/assets/js/52-overlays-price-render.js").read_text(
        encoding="utf-8"
    )
    boot = Path("src/aef_terminal/ui/assets/js/70-settings-boot.js").read_text(encoding="utf-8")
    assert "publishLinkedCrosshair(state.crosshair)" in interaction
    assert 'window.mcPerfStart("crosshairPointerToCommit")' in interaction
    assert "window.mcPerfEnd(pointerCommitPerf" in interaction
    snapped_crosshair_body = renderer.split("function snappedCrosshair", 1)[1]
    assert "rawX" not in snapped_crosshair_body
    assert "barSlot" not in snapped_crosshair_body
    assert "setupWindowLinkChannel();" in boot
    assert "closeWindowLinkChannel();" in boot
    assert 'window.addEventListener("pageshow"' in boot
    assert "if (event.persisted) reloadMarketAfterVisibilityResume({ force: true });" in boot
    range_body = interaction.split("async function applyChartRangePreset(key)", 1)[1].split(
        "rangeButton?.addEventListener",
        1,
    )[0]
    assert range_body.index("publishLinkedCrosshair") < range_body.index(
        "state.timeframe = preset.timeframe"
    )


def test_shared_gex_read_model_reapplies_equal_revision_and_bounds_routine_fanout(
    tmp_path: Path,
) -> None:
    source = gex_context_js_source()
    share_source = (
        "function shareGexReadModel(payload)"
        + source.split("function shareGexReadModel(payload)", 1)[1].split(
            "function queueSharedGexContextMessage", 1
        )[0]
    )
    queue_source = (
        "function queueSharedGexContextMessage(message)"
        + source.split("function queueSharedGexContextMessage(message)", 1)[1].split(
            "async function stopGexLiveContext", 1
        )[0]
    )
    candidate_source = (
        "function activeGexContext(snapshot = state.snapshot)"
        + source.split("function activeGexContext(snapshot = state.snapshot)", 1)[1].split(
            "function gexRenderKey", 1
        )[0]
    )
    handoff_source = (
        "function clearGexReadModelHandoff(requestKey)"
        + source.split("function clearGexReadModelHandoff(requestKey)", 1)[1].split(
            "function queueInitialGexAcquire", 1
        )[0]
    )
    script_path = tmp_path / "shared-gex-read-model.js"
    script_path.write_text(
        "\n".join(
            (
                "const instrumentId = 'ibkr|stock|123';",
                "const routeFingerprint = 'route-v1';",
                "const captureMode = 'request';",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function gexContextKey(mode, identity = {}) { return JSON.stringify([identity.instrument_id || instrumentId, identity.route_fingerprint || routeFingerprint, mode]); }",
                "function gexPayloadIdentityMatchesRequest(payload, expectedInstrumentId, expectedRouteFingerprint) { return Boolean(payload?.provider_symbol && payload.instrument_id === expectedInstrumentId && payload.route_fingerprint === expectedRouteFingerprint); }",
                "function gexPayloadMatchesRequest(payload, expectedInstrumentId, expectedRouteFingerprint, expectedMode) { return Boolean(payload?.canonical && payload.instrument_id === expectedInstrumentId && payload.route_fingerprint === expectedRouteFingerprint && payload.capture_mode === expectedMode); }",
                "function gexStatusPayloadMatchesRequest(payload, expectedInstrumentId, expectedRouteFingerprint, expectedMode) { return Boolean(payload?.typedStatus && payload.instrument_id === expectedInstrumentId && payload.route_fingerprint === expectedRouteFingerprint && payload.capture_mode === expectedMode); }",
                "function gexPayloadRevision(payload) { return payload.capture_revision; }",
                "function gexPayloadProviderSymbol(payload) { return payload?.provider_symbol || ''; }",
                "function gexPayloadMarketDataEntitlementIsCanonical(payload) { return payload?.canonical === true; }",
                "function gexOpenInterestAsOf(payload) { return payload?.canonical ? 'previous_settlement' : ''; }",
                "function gexContextMatchesCaptureMode(payload, mode) { return payload?.capture_mode === mode; }",
                "function gexPublicLevelsAreCanonical(payload) { return Array.isArray(payload); }",
                "function gexExpiryProfileIsCanonical(payload) { return Array.isArray(payload); }",
                "function gexHistoryRowsAreCanonical(payload) { return Array.isArray(payload); }",
                "function instrumentRouteFingerprint() { return routeFingerprint; }",
                "function effectiveGexContextMode() { return captureMode; }",
                "function gexLayerVisible() { return true; }",
                "function connectGexLiveStream() {}",
                "const gexLive = { lifecycleGeneration: 0 };",
                "function currentGexLiveState() { return gexLive; }",
                "let ownsReadModel = true; function acquireSharedStreamOwner() { return ownsReadModel; }",
                "function readSharedStreamOwner() { return { expires: Date.now() + 8000 }; }",
                "let loads = 0; function loadGexContext() { loads += 1; }",
                "const shared = []; function shareReadModel(model, scope, payload) { shared.push({ model, scope, payload }); }",
                "let active = null; let renders = 0; let healthRenders = 0;",
                "function setActiveGexContext(payload) { active = payload; }",
                "function renderGexSnapshot() { renders += 1; }",
                "function renderSystemHealth() { healthRenders += 1; }",
                "const sharedGexReadModelThrottleByScope = new Map();",
                "let handoffCallback = null; const window = { mcTelemetryInc() {}, setTimeout(callback) { handoffCallback = callback; return 91; }, clearTimeout() {} };",
                "const SHARED_STREAM_OWNER_TTL_MS = 8000;",
                "const GEX_SOURCE_BY_CAPTURE_MODE = { request: 'gex:ibkr', live: 'gex:ibkr-live' };",
                "const key = gexContextKey(captureMode, { instrument_id: instrumentId, route_fingerprint: routeFingerprint });",
                "const current = { canonical: true, provider_symbol: 'SPY', instrument_id: instrumentId, route_fingerprint: routeFingerprint, source: 'gex:ibkr', capture_mode: captureMode, captured_at: '2026-07-22T10:00:00.000Z', capture_revision: '2026-07-22T10:00:00.000Z', option_universe_expires_at: '2099-12-31T21:00:00+00:00', decision_authoritative: true, frame_complete: true, market_data_entitlement: 'live', open_interest_as_of: 'previous_settlement', comparison_scope: {}, levels: [], expiry_profile: [], visibility_summary: {}, history: [{ captured_at: 'old' }], history_revision: 7, history_status: { status: 'ok' } };",
                "const staleSnapshot = { ...current, instrument_id: 'stale-instrument' };",
                "const state = { clientId: 'local', instrumentId, snapshot: { gex: staleSnapshot }, gexContext: current, gexContexts: { [key]: current }, gexReadModelHandoffTimers: {}, serverSleeping: false };",
                candidate_source,
                share_source,
                handoff_source,
                queue_source,
                "if (activeGexContext(state.snapshot) !== current) process.exit(2);",
                "const localError = { ...current, canonical: false, local_only: true, ok: false, status: 'error', message: 'transport failed', levels: [], expiry_profile: [] };",
                "state.gexContext = localError; state.gexContexts[key] = localError;",
                "if (gexStatusContext(state.snapshot) !== localError) process.exit(3);",
                "state.gexContext = current; state.gexContexts[key] = current;",
                "shareGexReadModel(current);",
                "if (shared.length !== 1 || Object.hasOwn(shared[0].payload, 'history') || Object.hasOwn(shared[0].payload, 'history_revision') || Object.hasOwn(shared[0].payload, 'history_status')) process.exit(4);",
                "shareGexReadModel(current, { includeHistory: true });",
                "if (shared.length !== 2 || Object.hasOwn(shared[1].payload, 'history')) process.exit(5);",
                "const liveOne = { ...current, capture_mode: 'live', source: 'gex:ibkr-live', capture_revision: '2026-07-22T10:01:00.000Z' };",
                "const liveTwo = { ...liveOne, capture_revision: '2026-07-22T10:02:00.000Z' };",
                "const sharedBeforeTrailing = shared.length;",
                "shareGexReadModel(liveOne); shareGexReadModel(liveTwo);",
                "const trailingCallback = handoffCallback;",
                "const liveScopeKey = gexContextKey('live', liveOne);",
                "const liveThrottle = sharedGexReadModelThrottleByScope.get(liveScopeKey);",
                "if (shared.length !== sharedBeforeTrailing + 1 || typeof trailingCallback !== 'function' || liveThrottle?.pendingPayload !== liveTwo) process.exit(13);",
                "shareGexReadModel(current);",
                "if (shared.length !== sharedBeforeTrailing + 2 || liveThrottle?.pendingPayload !== liveTwo || liveThrottle?.timer !== 91) process.exit(14);",
                "const otherLive = { ...liveTwo, route_fingerprint: 'route-v2' };",
                "shareGexReadModel(otherLive);",
                "if (shared.length !== sharedBeforeTrailing + 3 || shared.at(-1).scope.route_fingerprint !== 'route-v2') process.exit(15);",
                "if (sharedGexReadModelThrottleByScope.get(gexContextKey('live', otherLive)) === liveThrottle) process.exit(16);",
                "liveThrottle.lastSharedAt = 0; trailingCallback();",
                "if (shared.length !== sharedBeforeTrailing + 4 || shared.at(-1).payload.capture_revision !== liveTwo.capture_revision) process.exit(17);",
                "handoffCallback = null;",
                "const scope = { instrument_id: instrumentId, route_fingerprint: routeFingerprint, capture_mode: captureMode };",
                "queueSharedGexContextMessage({ type: 'read_model_snapshot', scope, payload: { ...current, history: [{ captured_at: 'peer' }] } });",
                "if (active !== current || renders !== 1 || healthRenders !== 0) process.exit(6);",
                "const authorityDowngrade = { ...current, decision_authoritative: false }; delete authorityDowngrade.history; delete authorityDowngrade.history_revision; delete authorityDowngrade.history_status;",
                "queueSharedGexContextMessage({ type: 'read_model_snapshot', scope, payload: authorityDowngrade });",
                "if (active?.decision_authoritative !== false || state.gexContexts[key]?.decision_authoritative !== false) process.exit(20);",
                "const newer = { ...current, captured_at: '2026-07-22T10:01:00.000Z', capture_revision: '2026-07-22T10:01:00.000Z' }; delete newer.history; delete newer.history_revision; delete newer.history_status;",
                "queueSharedGexContextMessage({ type: 'read_model_snapshot', scope, payload: newer });",
                "if (active.capture_revision !== newer.capture_revision || active.history !== current.history || active.history_revision !== 7) process.exit(7);",
                "const rendersBeforeOlder = renders;",
                "queueSharedGexContextMessage({ type: 'read_model_snapshot', scope, payload: { ...newer, captured_at: '2026-07-22T09:59:00.000Z', capture_revision: '2026-07-22T09:59:00.000Z' } });",
                "if (renders !== rendersBeforeOlder || active.capture_revision !== newer.capture_revision) process.exit(8);",
                "state.gexContexts[key] = { ...current, canonical: false, typedStatus: true };",
                "const recovered = { ...newer, captured_at: '2026-07-22T10:02:00.000Z', capture_revision: '2026-07-22T10:02:00.000Z' };",
                "queueSharedGexContextMessage({ type: 'read_model_snapshot', scope, payload: recovered });",
                "if (healthRenders !== 1 || active.capture_revision !== recovered.capture_revision) process.exit(18);",
                "const routine = { ...recovered, captured_at: '2026-07-22T10:03:00.000Z', capture_revision: '2026-07-22T10:03:00.000Z' };",
                "queueSharedGexContextMessage({ type: 'read_model_snapshot', scope, payload: routine });",
                "if (healthRenders !== 1 || active.capture_revision !== routine.capture_revision) process.exit(19);",
                "ownsReadModel = false; const sharedBeforeRequest = shared.length;",
                "queueSharedGexContextMessage({ type: 'read_model_requested', scope });",
                "if (shared.length !== sharedBeforeRequest + 1 || loads !== 0) process.exit(9);",
                "if (Object.hasOwn(shared.at(-1).payload, 'history')) process.exit(10);",
                "state.gexContexts[key] = { local_only: true, status: 'loading' };",
                "queueGexReadModelHandoff(key); if (!handoffCallback) process.exit(11); handoffCallback();",
                "if (loads !== 1 || state.gexReadModelHandoffTimers[key]) process.exit(12);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_gex_lifecycle_owner_prunes_only_retired_route_work(
    tmp_path: Path,
) -> None:
    source = gex_context_js_source()
    stop_source = (
        "async function stopGexLiveContext(options = {})"
        + source.split("async function stopGexLiveContext(options = {})", 1)[1].split(
            "let gexSnapshotRenderFrame",
            1,
        )[0]
    )
    script_path = tmp_path / "gex-lifecycle-owner.js"
    script_path.write_text(
        "\n".join(
            (
                "const oldInstrumentId = 'ibkr|stock|old'; const oldRoute = 'route-old';",
                "const newInstrumentId = 'ibkr|stock|new'; const newRoute = 'route-new';",
                "const keyFor = (instrumentId, route, mode) => JSON.stringify([instrumentId, route, mode]);",
                "const oldRequest = keyFor(oldInstrumentId, oldRoute, 'request');",
                "const oldLive = keyFor(oldInstrumentId, oldRoute, 'live');",
                "const newRequest = keyFor(newInstrumentId, newRoute, 'request');",
                "const newLive = keyFor(newInstrumentId, newRoute, 'live');",
                "const clearedTimeouts = []; const cancelledFrames = []; const closedSockets = []; const released = [];",
                "const window = { clearTimeout(value) { clearedTimeouts.push(value); }, cancelAnimationFrame(value) { cancelledFrames.push(value); } };",
                "const socket = { close(code, reason) { closedSockets.push([code, reason]); } };",
                "const live = { lifecycleGeneration: 7, socket, streamKey: oldLive, retryTimer: 31, staleTimer: 32, motionTimer: 33, acceptedSessionId: 'session', acceptedFrameSeq: 9, lastMessageAt: 10, blockedReason: 'old route', blockedAt: 1, statusPayload: { old: true } };",
                "const state = {",
                "  instrumentId: newInstrumentId,",
                "  routeFingerprint: newRoute,",
                "  gexLive: live,",
                "  gexContexts: { [oldRequest]: { old: true }, [oldLive]: { old: true }, [newRequest]: { current: true }, [newLive]: { current: true } },",
                "  gexReadModelHandoffTimers: { [oldRequest]: 41, [newRequest]: 42 },",
                "  gexInitialAcquireKeys: { [oldRequest]: { old: true, timer: 46 }, [newRequest]: { current: true, timer: 47 } },",
                "  loadingGexKeys: { [oldRequest]: { old: true }, [newRequest]: { current: true } },",
                "  loadingGex: false,",
                "  gexContext: { instrument_id: oldInstrumentId, route_fingerprint: oldRoute, capture_mode: 'request' },",
                "  snapshot: { gex: { instrument_id: oldInstrumentId, route_fingerprint: oldRoute, capture_mode: 'request' } },",
                "  gexManualRefresh: { active: true, requestKey: oldRequest, pollTimer: 43 },",
                "};",
                "function currentGexLiveState() { return live; }",
                "function clearLocalGexLiveRuntime() {",
                "  for (const key of ['retryTimer', 'staleTimer', 'motionTimer']) {",
                "    if (live[key]) window.clearTimeout(live[key]);",
                "    live[key] = null;",
                "  }",
                "}",
                "function gexContextKey(mode = 'request', identity = {}) {",
                "  return keyFor(identity.instrument_id ?? state.instrumentId, identity.route_fingerprint ?? state.routeFingerprint, mode);",
                "}",
                "const sharedGexReadModelThrottleByScope = new Map([[oldLive, { timer: 44 }], [newLive, { timer: 45 }]]);",
                "function releaseSharedStreamOwner(model, key) { released.push([model, key]); }",
                "function currentGexManualRefresh() { return state.gexManualRefresh; }",
                "function closeWebSocketQuietly(value, reason) { value.close(1000, reason); }",
                "let gexSnapshotRenderTimer = 51; let gexSnapshotRenderFrame = 52;",
                "let gexSnapshotRenderScopeKey = oldRequest; let gexSnapshotSidebarOffVisualKey = 'old';",
                stop_source,
                "(async () => {",
                "  await stopGexLiveContext({ pruneRouteCaches: true, preserveCurrentRoute: true, reason: 'route changed' });",
                "  console.log(JSON.stringify({",
                "    generation: live.lifecycleGeneration, socketCleared: live.socket === null, closedSockets, routeStatusCleared: live.blockedReason === '' && live.blockedAt === 0 && live.statusPayload === null,",
                "    contexts: Object.keys(state.gexContexts).sort(), handoffs: Object.keys(state.gexReadModelHandoffTimers).sort(),",
                "    initial: Object.keys(state.gexInitialAcquireKeys).sort(), loading: Object.keys(state.loadingGexKeys).sort(),",
                "    throttles: [...sharedGexReadModelThrottleByScope.keys()].sort(), activeCleared: state.gexContext === null && !Object.hasOwn(state.snapshot, 'gex'),",
                "    refreshCleared: !state.gexManualRefresh.active && state.gexManualRefresh.requestKey === '' && state.gexManualRefresh.pollTimer === null,",
                "    loadingGex: state.loadingGex, released, clearedTimeouts: clearedTimeouts.sort((a, b) => a - b),",
                "    cancelledFrames, renderCleared: gexSnapshotRenderTimer === 0 && gexSnapshotRenderFrame === 0 && gexSnapshotRenderScopeKey === '' && gexSnapshotSidebarOffVisualKey === '',",
                "  }));",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload["generation"] == 8
    assert payload["socketCleared"] is True
    assert payload["routeStatusCleared"] is True
    assert payload["closedSockets"] == [[1000, "route changed"]]
    new_request = '["ibkr|stock|new","route-new","request"]'
    new_live = '["ibkr|stock|new","route-new","live"]'
    assert payload["contexts"] == sorted([new_request, new_live])
    assert payload["handoffs"] == []
    assert payload["initial"] == []
    assert payload["loading"] == []
    assert payload["throttles"] == [new_live]
    assert payload["activeCleared"] is True
    assert payload["refreshCleared"] is True
    assert payload["loadingGex"] is False
    assert payload["released"] == [
        ["gex-acquire", '["ibkr|stock|old","route-old","request"]'],
        ["gex-acquire", '["ibkr|stock|new","route-new","request"]'],
        ["gex-read", '["ibkr|stock|old","route-old","request"]'],
        ["gex-read", '["ibkr|stock|new","route-new","request"]'],
        ["gex-read", '["ibkr|stock|old","route-old","live"]'],
        ["gex-acquire", '["ibkr|stock|old","route-old","live"]'],
    ]
    assert payload["clearedTimeouts"] == [
        31,
        32,
        33,
        41,
        42,
        43,
        44,
        45,
        46,
        47,
        51,
    ]
    assert payload["cancelledFrames"] == [52]
    assert payload["renderCleared"] is True


def test_gex_stop_clears_generation_bound_work_before_resuming_refresh(
    tmp_path: Path,
) -> None:
    source = gex_context_js_source()
    stop_source = (
        "async function stopGexLiveContext(options = {})"
        + source.split("async function stopGexLiveContext(options = {})", 1)[1].split(
            "let gexSnapshotRenderFrame",
            1,
        )[0]
    )
    script_path = tmp_path / "gex-stop-lifecycle.js"
    script_path.write_text(
        "\n".join(
            (
                "const requestKey = 'request-key'; const liveKey = 'live-key';",
                "const cleared = []; const cancelled = []; const released = []; const resumed = [];",
                "const window = { clearTimeout(value) { cleared.push(value); }, cancelAnimationFrame(value) { cancelled.push(value); } };",
                "const live = { lifecycleGeneration: 2, socket: null, streamKey: liveKey, retryTimer: null, staleTimer: null, motionTimer: null };",
                "const refresh = { active: true, requestKey, pollTimer: 21 };",
                "const state = { serverSleeping: false, gexLive: live, gexManualRefresh: refresh, gexReadModelHandoffTimers: { [requestKey]: 22 }, gexInitialAcquireKeys: { [requestKey]: { timer: 23 } }, loadingGexKeys: { [requestKey]: { lifecycleGeneration: 2 } } };",
                "const throttle = { timer: 24, pendingPayload: { old: true }, lastSharedAt: 1 };",
                "const sharedGexReadModelThrottleByScope = new Map([[requestKey, throttle]]);",
                "function currentGexLiveState() { return live; }",
                "function currentGexManualRefresh() { return refresh; }",
                "function clearLocalGexLiveRuntime() {}",
                "function closeWebSocketQuietly() {}",
                "function releaseSharedStreamOwner(kind, key) { released.push([kind, key]); }",
                "function gexContextKey(mode = 'request') { return mode === 'request' ? requestKey : liveKey; }",
                "function gexLayerVisible() { return true; }",
                "function scheduleGexManualRefreshPoll(key) { resumed.push(key); refresh.pollTimer = 99; }",
                "let gexSnapshotRenderTimer = 25; let gexSnapshotRenderFrame = 26;",
                "let gexSnapshotRenderScopeKey = requestKey; let gexSnapshotSidebarOffVisualKey = 'old';",
                stop_source,
                "(async () => {",
                "  await stopGexLiveContext({ reason: 'mode changed' });",
                "  console.log(JSON.stringify({ generation: live.lifecycleGeneration, handoffs: Object.keys(state.gexReadModelHandoffTimers), acquires: Object.keys(state.gexInitialAcquireKeys), loading: Object.keys(state.loadingGexKeys), loadingGex: state.loadingGex, throttle, refresh, resumed, released, cleared: cleared.sort((a, b) => a - b), cancelled, renderCleared: gexSnapshotRenderTimer === 0 && gexSnapshotRenderFrame === 0 && gexSnapshotRenderScopeKey === '' && gexSnapshotSidebarOffVisualKey === '' }));",
                "})().catch(error => { console.error(error); process.exit(1); });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload["generation"] == 3
    assert payload["handoffs"] == []
    assert payload["acquires"] == []
    assert payload["loading"] == []
    assert payload["loadingGex"] is False
    assert payload["throttle"]["timer"] == 0
    assert payload["throttle"]["pendingPayload"] is None
    assert payload["refresh"]["active"] is True
    assert payload["refresh"]["pollTimer"] == 99
    assert payload["resumed"] == ["request-key"]
    assert payload["released"] == [
        ["gex-acquire", "request-key"],
        ["gex-read", "request-key"],
        ["gex-read", "live-key"],
    ]
    assert payload["cleared"] == [21, 22, 23, 24, 25]
    assert payload["cancelled"] == [26]
    assert payload["renderCleared"] is True


