                "const WATCHLIST_TREND_STATUSES = new Set(['ready', 'insufficient_data', 'storage_unavailable', 'storage_error']);",
                "const route = { instrument_id: 'ibkr|stock|123', route_fingerprint: 'route-v1' };",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function screenerRowIdentityKey(value) { return `${value.instrument_id}|${value.route_fingerprint}`; }",
                "function watchlistTrendRoutes() { return [route]; }",
                "let renders = 0; function renderInstruments() { renders += 1; }",
