                "queueSharedWatchlistTrendMessage({ type: 'read_model_snapshot', scope, payload: { ...payload, rows: [{ ...payload.rows[0], as_of: '2026-07-22T10:04:00.000Z', points: [{ ts: '2026-07-22T09:55:00.000Z', price: 90 }] }] } });",
                "if (state.watchlistTrendsByIdentity.get(key).points[0].price !== 101) process.exit(4);",
