def test_system_health_latest_request_wins_out_of_order_scheduler_responses(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/19-reference-data.js").read_text(encoding="utf-8")
    health_source = (
        "const SYSTEM_HEALTH_MEMORY_TTL_MS"
        + source.split("const SYSTEM_HEALTH_MEMORY_TTL_MS", 1)[1]
    )
    script_path = tmp_path / "system-health-latest-response.js"
    script_path.write_text(
        "\n".join(
            (
                "const requests = [];",
                "function fetchJson() { return new Promise((resolve, reject) => requests.push({ resolve, reject })); }",
                "const state = { settings: { open: false, gexSchedulerEnabled: false, gexSchedulerInstrumentIds: [] }, systemHealth: null, serverSleeping: false };",
                "let renders = 0; let applies = 0; let schedulerRenders = 0;",
                "function renderSystemHealth() { renders += 1; } function applySettings() { applies += 1; }",
                "function renderGexSchedulerInstrumentOptions() { schedulerRenders += 1; }",
                "function closeQuoteStream() {} function closeChartStream() {}",
                "function requestErrorMessage(error) { return String(error); }",
                health_source,
                "(async () => {",
                "  const staleLoad = loadSystemHealth({ force: true });",
                "  const latestLoad = loadSystemHealth({ force: true });",
                "  if (requests.length !== 2) process.exit(2);",
                "  requests[1].resolve({ status: 'ok', sleep: { sleeping: false }, gex: { scheduler: { enabled: true, instrument_ids: ['ibkr|stock|123'] } }, options: { premium_caps: {} } });",
                "  if (await latestLoad !== true) process.exit(3);",
                "  if (!state.settings.gexSchedulerEnabled || state.settings.gexSchedulerInstrumentIds[0] !== 'ibkr|stock|123') process.exit(4);",
                "  requests[0].resolve({ status: 'ok', sleep: { sleeping: false }, gex: { scheduler: { enabled: false, instrument_ids: [] } }, options: { premium_caps: {} } });",
                "  if (await staleLoad !== false) process.exit(5);",
                "  if (!state.settings.gexSchedulerEnabled || state.settings.gexSchedulerInstrumentIds[0] !== 'ibkr|stock|123') process.exit(6);",
                "  if (renders !== 1 || applies !== 1 || schedulerRenders !== 1) process.exit(7);",
                "})().catch(error => { console.error(error); process.exit(8); });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


