def test_future_axis_maps_provider_timestamps_from_relative_offsets_without_historical_slots(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(encoding="utf-8")
    axis_source = (
        "function axisSlotStep(axis)"
        + source.split("function axisSlotStep(axis)", 1)[1].split(
            "function maxScreenIndexForAxis",
            1,
        )[0]
    )
    script_path = tmp_path / "future-axis-relative-offset.js"
    script_path.write_text(
        "\n".join(
            (
                'const anchor = "2026-07-17T20:55:00.000Z";',
                'const monday = "2026-07-20T13:30:00.000Z";',
                'const state = { timeframe: "5m", snapshot: { future_axis: null } };',
                "function intervalMinutesFromState() { return 5; }",
                "function drawingLogicalIndexForPoint() { return null; }",
                "function drawingScreenIndexForLogicalIndex() { return null; }",
                axis_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                'const futureAxis = { kind: "provider_session_future_axis", timeframe: "5m", schedule_state: "verified", anchor_ts: anchor, slots: [{ ts: monday, bar_offset: 1 }] };',
                "state.snapshot.future_axis = futureAxis;",
                "const bars = [",
                "  { ts: '2026-07-16T20:55:00.000Z', closed: true, state: 'confirmed', bar_slot: 10, bar_slot_authoritative: true },",
                "  { ts: anchor, closed: true, state: 'confirmed', bar_slot: 900, bar_slot_authoritative: true },",
                "];",
                "const axis = { allBars: bars, bars, futureAxis, start: 0, slotStep: 5 };",
                "const indexed = providerFutureAxisIndex(axis);",
                'check(indexed.slots.length === 1 && indexed.slots[0].barOffset === 1, "future timestamp must be indexed by relative offset");',
                'check(indexed.slots[0].barSlot === 10, "transient future slot must expose the historical-slot collision fixture");',
                'check(indexed.byTimestamp.get(Date.parse(monday))?.ts === monday, "future timestamp must resolve to its typed axis record");',
                'check(screenIndexForTimestampPoint({ ts: monday, barSlot: 900 }, axis) === 2, "future timestamp geometry must ignore the colliding historical provider slot");',
                'check(!Object.hasOwn(futureAxis.slots[0], "bar_slot"), "wire future axis must not carry schedule-ranked slots");',
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


