                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function chartVisualHitForLocalX(_bars, pad, xStep, localX) { return { index: Math.round((localX - pad.left - xStep * 0.5) / xStep), gap: null }; }",
                "function drawingAxisFromGeo(geo) { return geo; }",
