                "];",
                "const futureAxis = { kind: 'provider_session_future_axis', timeframe: '5m', schedule_state: 'verified', anchor_ts: anchor, slots: [{ ts: forming, bar_offset: 1 }, { ts: future, bar_offset: 2 }] };",
                "state.snapshot.future_axis = futureAxis;",
                "const xStep = 100 / 7;",
                "const geo = { bars: allBars, allBars, start: 0, timeframe: '5m', futureAxis, slotStep: 5, rightGapBars: 4, width: 100, pad: { left: 0, right: 0, top: 0 }, xStep, priceH: 100, minP: 90, maxP: 110, x: index => (index + 0.5) * xStep };",
                "function priceChartGeometry() { return geo; }",
                "const point = chartPointFromLocal(3.5 * xStep, 50);",
                "check(point?.ts === future, 'drag must use the exact provider timestamp instead of the colliding historical slot');",
