def test_gex_delayed_overlay_render_rechecks_scope_and_visibility(tmp_path: Path) -> None:
    source = gex_context_js_source()
    render_source = (
        "let gexSnapshotRenderFrame = 0;"
        + source.split("let gexSnapshotRenderFrame = 0;", 1)[1].split(
            "function setGexManualRefresh",
            1,
        )[0]
    )
    script_path = tmp_path / "gex-delayed-render.js"
    script_path.write_text(
        "\n".join(
            (
                "let scopeKey = 'scope-a';",
                "let layerVisible = true;",
                "const state = { snapshot: { id: 1 }, indicators: { gexContext: { profile: true, zoneStyle: 'off' } } };",
                "const gexLive = { lifecycleGeneration: 0 };",
                "function currentGexLiveState() { return gexLive; }",
                "function gexContextKey() { return scopeKey; }",
                "function gexLayerVisible() { return layerVisible; }",
                "function gexZoneMode(value) { return value; }",
                "function renderCharts() { throw new Error('live update reached full chart render'); }",
                "const gexLayers = [];",
                "function renderPriceGexLayers(snapshot) { gexLayers.push(snapshot); }",
                "const timers = []; const frames = [];",
                "const window = {",
                "  setTimeout(callback) { timers.push(callback); return timers.length; },",
                "  clearTimeout(id) { timers[id - 1] = null; },",
                "  requestAnimationFrame(callback) { frames.push(callback); return frames.length; },",
                "  cancelAnimationFrame(id) { frames[id - 1] = null; },",
                "};",
                render_source,
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "const staleScopeTimer = timers[0];",
                "scopeKey = 'scope-b'; staleScopeTimer();",
                "if (frames.length !== 0 || gexLayers.length !== 0) process.exit(2);",
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "timers.at(-1)(); const hiddenFrame = frames.at(-1);",
                "layerVisible = false; hiddenFrame();",
                "if (gexLayers.length !== 0) process.exit(3);",
                "layerVisible = true; renderGexSnapshot({ reason: 'gex-stream' });",
                "timers.at(-1)(); const routeChangedFrame = frames.at(-1);",
                "scopeKey = 'scope-c'; routeChangedFrame();",
                "if (gexLayers.length !== 0) process.exit(4);",
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "timers.at(-1)(); frames.at(-1)();",
                "if (gexLayers.length !== 1 || gexLayers[0] !== state.snapshot) process.exit(5);",
                "state.indicators.gexContext.profile = false;",
                "const timerCount = timers.length;",
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "if (timers.length !== timerCount) process.exit(6);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_gex_sidebar_off_live_render_skips_unchanged_visual_payload(
    tmp_path: Path,
) -> None:
    source = gex_context_js_source()
    render_source = (
        "let gexSnapshotRenderFrame = 0;"
        + source.split("let gexSnapshotRenderFrame = 0;", 1)[1].split(
            "function setGexManualRefresh",
            1,
        )[0]
    )
    script_path = tmp_path / "gex-sidebar-off-render-dedupe.js"
    script_path.write_text(
        "\n".join(
            (
                "let visualKey = 'visual-a';",
                "const state = { snapshot: { id: 1 }, indicators: { gexContext: { profile: false, zoneStyle: 'lines' } } };",
                "const gexLive = { lifecycleGeneration: 0 };",
                "function currentGexLiveState() { return gexLive; }",
                "function gexContextKey() { return 'scope-a'; }",
                "function gexSidebarOffVisualKey() { return visualKey; }",
                "function gexLayerVisible() { return true; }",
                "function gexZoneMode(value) { return value; }",
                "function renderCharts() { throw new Error('live update reached full chart render'); }",
                "const gexLayers = [];",
                "function renderPriceGexLayers(snapshot) { gexLayers.push(snapshot); }",
                "const timers = []; const frames = []; const counters = {};",
                "const window = {",
                "  setTimeout(callback) { timers.push(callback); return timers.length; },",
                "  clearTimeout(id) { timers[id - 1] = null; },",
                "  requestAnimationFrame(callback) { frames.push(callback); return frames.length; },",
                "  cancelAnimationFrame(id) { frames[id - 1] = null; },",
                "  mcTelemetryInc(key) { counters[key] = (counters[key] || 0) + 1; },",
                "};",
                render_source,
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "timers.at(-1)(); frames.at(-1)();",
                "if (gexLayers.length !== 1) process.exit(2);",
                "const timerCount = timers.length;",
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "if (timers.length !== timerCount || gexLayers.length !== 1) process.exit(3);",
                "if (counters['gex.render.skipped_unchanged'] !== 1) process.exit(4);",
                "visualKey = 'visual-b';",
                "renderGexSnapshot({ reason: 'gex-stream' });",
                "timers.at(-1)(); frames.at(-1)();",
                "if (gexLayers.length !== 2) process.exit(5);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


