def test_gex_history_markers_remain_visible_on_fifteen_minute_zoomed_axis(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/50-overlays-gex-history.js").read_text(
        encoding="utf-8"
    )
    interval_source = (
        "function gexHistorySnapshotTs"
        + source.split(
            "function gexHistorySnapshotTs",
            1,
        )[1].split("function visibleGexHistoryCount", 1)[0]
    )
    draw_source = (
        "function drawGexHistoryTrail"
        + source.split(
            "function drawGexHistoryTrail",
            1,
        )[1]
    )
    script_path = tmp_path / "gex-history-marker-width.js"
    script_path.write_text(
        "\n".join(
            (
                "const segments = [];",
                "let segmentStart = null;",
                "function gexHistoryTimestampMs(item) { return item.timestamp_unix_ms; }",
                "function gexNullableNumber(value) { return typeof value === 'number' && Number.isFinite(value) ? value : null; }",
                "function effectiveGexContextMode() { return 'request'; }",
                "function gexHistoryView() { return '1d'; }",
                "function gexMarketDataEntitlement(payload) { return ['live', 'frozen', 'delayed', 'delayed_frozen'].includes(payload?.market_data_entitlement) ? payload.market_data_entitlement : ''; }",
                "function gexComparisonScopesEqual(left, right) { return left?.lane === right?.lane; }",
                "const CHART_VIEW_DAY_MS = 86400000;",
                "function visibleTimeWindowForBars() { return { start: 0, end: Number.MAX_SAFE_INTEGER }; }",
                "function gexVisibleLevels(levels) { return levels; }",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function chartX(pad, xStep) { return index => pad.left + index * xStep + xStep * 0.5; }",
                "function genericOverlayLookupForVisible(visible, bars, allBars) { return { times: allBars.map(bar => Date.parse(bar.ts)), indexOffset: visible.start }; }",
                "function gexLevelStrengthValue(level) { return level.strength; }",
                "function gexKindColor() { return '#00aaff'; }",
                "function rgbaFromCssColor(color) { return color; }",
                "function gexLevelIntensity() { return ''; }",
                "const state = { indicators: { gexContext: { zones: false } }, settings: { theme: 'dark' } };",
                "const ctx = { save() {}, restore() {}, setLineDash() {}, beginPath() {}, moveTo(x, y) { segmentStart = [x, y]; }, lineTo(x, y) { segments.push([segmentStart[0], x, y]); }, stroke() {} };",
                interval_source,
                draw_source,
                "const bars = ['2026-07-21T10:00:00Z', '2026-07-21T10:15:00Z', '2026-07-21T10:30:00Z'].map(ts => ({ ts }));",
                "const capturedAt = '2026-07-21T10:05:00Z';",
                "const timestampUnixMs = Date.parse(capturedAt);",
                "const base = { captured_at: capturedAt, capture_mode: 'request', market_data_entitlement: 'live', comparison_scope: { lane: 'exact' }, timestamp_unix_ms: timestampUnixMs, valid_from_unix_ms: timestampUnixMs, valid_until_unix_ms: timestampUnixMs + 300000, levels: [{ price: 100, strength: 1, zone_half_width: 0 }] };",
                "const snapshot = { bars, features: {} };",
                "const visible = { bars, start: 0, end: bars.length };",
                "const pad = { left: 10, right: 10, top: 0 };",
                "const checkMarker = mode => { segments.length = 0; const validUntil = mode === 'sample' ? timestampUnixMs + 1800000 : base.valid_until_unix_ms; drawGexHistoryTrail(ctx, { capture_mode: 'request', market_data_entitlement: 'live', comparison_scope: { lane: 'exact' }, history: [{ ...base, valid_until_unix_ms: validUntil, projection_mode: mode, projection_bucket_minutes: mode === 'sample' ? 15 : null }], levels: [] }, snapshot, visible, pad, 100, 100, () => 50, 2, { labels: false, shadows: false, tooltips: false }); const segment = segments.find(item => item[2] === 50); if (!segment) process.exit(mode === 'sample' ? 2 : 3); const markerWidth = segment[1] - segment[0]; if (markerWidth < 1 || markerWidth > 2.001) process.exit(mode === 'sample' ? 4 : 5); if (Math.abs((segment[0] + segment[1]) / 2 - (11 + 2 / 3)) > 0.001) process.exit(mode === 'sample' ? 6 : 7); };",
                "checkMarker('sample');",
                "checkMarker('interval');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


