def test_gex_renderers_reject_untyped_numeric_facts_and_do_not_infer_local_sign() -> None:
    js = martincall_js_source()
    canonical_level_consumers = "\n".join(
        Path(path).read_text(encoding="utf-8")
        for path in (
            "src/aef_terminal/ui/assets/js/50-overlays-gex.js",
            "src/aef_terminal/ui/assets/js/50-overlays-gex-levels.js",
            "src/aef_terminal/ui/assets/js/50-overlays-gex-history.js",
        )
    )
    for removed_field in (
        "score",
        "is_weak",
        "selection_score",
        "bias",
        "gex_unit",
        "note",
        "label",
        "history_stats",
        "timeline_anchors",
    ):
        assert f"level.{removed_field}" not in canonical_level_consumers
        assert f"level?.{removed_field}" not in canonical_level_consumers

    gamma_sign_body = js.split("function gexGammaSign", 1)[1].split(
        "function gexGammaModeLines", 1
    )[0]
    assert "gexNullableNumber(level?.net_gex)" in gamma_sign_body
    assert "call_gex" not in gamma_sign_body
    assert "put_gex" not in gamma_sign_body
    assert "global_gamma_regime" not in gamma_sign_body
    assert "return Number(level" not in gamma_sign_body

    tooltip_body = js.split("function gexLevelTooltip", 1)[1].split(
        "function gexNumericStrikeKey", 1
    )[0]
    assert "gexNullableNumber(level?.price)" in tooltip_body
    assert "gexNullableNumber(level?.net_gex)" in tooltip_body
    assert "gexNullableNumber(level?.call_gex)" in tooltip_body
    assert "gexNullableNumber(level?.put_gex)" in tooltip_body
    assert 'Net GEX ${netGexValue !== null ? gexDollarText(netGexValue) : "-"}' in tooltip_body
    assert (
        'Call GEX ${callGexValue !== null ? gexDollarText(callGexValue) : "-"} / Put GEX ${putGexValue !== null ? gexDollarText(putGexValue) : "-"}'
        in tooltip_body
    )
    assert "Math.round(netGexValue)" not in tooltip_body
    assert 'sign === 0 ? "NEUTRAL GEX"' in tooltip_body
    assert "Gross = |Call GEX| + |Put GEX|" in tooltip_body
