def test_gex_visible_levels_uses_only_canonical_rank_and_never_legacy_price_truncation(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/50-overlays-gex-levels.js").read_text(
        encoding="utf-8"
    )
    selection_source = (
        "function gexLevelSelectionRank"
        + source.split(
            "function gexLevelSelectionRank",
            1,
        )[1].split("function gexLevelVisibilitySummary", 1)[0]
    )
    script_path = tmp_path / "gex-visible-levels.js"
    script_path.write_text(
        "\n".join(
            (
                "const GEX_DISPLAY_LEVEL_COUNTS = Object.freeze([11, 15, 21]);",
                "const GEX_DEFAULT_DISPLAY_LEVEL_COUNT = 21;",
                "const state = { indicators: { gexContext: { displayLevels: 21 } } };",
                "function gexNumericStrikeKey(value) { return typeof value === 'number' && Number.isFinite(value) ? value : null; }",
                selection_source,
                "const canonical = Array.from({ length: 21 }, (_, index) => ({ price: 5000 + (20 - index) * 5, selection_rank: index + 1 }));",
                "const topEleven = gexVisibleLevels(canonical, { displayLevels: 11 });",
                "if (topEleven.length !== 11) process.exit(2);",
                "if (Math.max(...topEleven.map(level => level.selection_rank)) !== 11) process.exit(3);",
                "if (!topEleven.every((level, index, rows) => index === 0 || rows[index - 1].price <= level.price)) process.exit(4);",
                "const invalid = canonical.map(level => ({ ...level }));",
                "delete invalid[5].selection_rank;",
                "if (gexVisibleLevels(invalid, { displayLevels: 11 }).length !== 0) process.exit(5);",
                "if (gexVisibleLevels(canonical, { displayLevels: 21 }).length !== 21) process.exit(6);",
                "if (gexVisibleLevels(canonical, { displayLevels: 15 }).length !== 15) process.exit(7);",
                "if (gexVisibleLevels(canonical, { displayLevels: 5 }).length !== 21) process.exit(8);",
                "const exhaustiveFive = canonical.slice(0, 5);",
                "if (gexVisibleLevels(exhaustiveFive, { displayLevels: 21 }).length !== 5) process.exit(9);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


