                "const GEX_OPTION_VOLUME_EVENT_FIELDS = Object.freeze(['call_volume_delta', 'put_volume_delta', 'total_volume_delta', 'bias', 'call_participation', 'put_participation', 'turnover', 'acceleration', 'flow_per_point', 'spot_move_points', 'material', 'interaction', 'cross_direction', 'state', 'window_seconds', 'source']);",
                "const GEX_HISTORY_WIRE_FIELDS = Object.freeze(['captured_at', 'timestamp_unix_ms', 'capture_mode', 'source', 'capture_revision', 'option_universe_expires_at', 'market_data_entitlement', 'open_interest_as_of', 'comparison_scope', 'spot', 'gamma_flip', 'levels', 'valid_until_unix_ms', 'projection_mode', 'projection_bucket_minutes']);",
