                "const level = { price: 5000, kind: 'GEX_NODE', kind_class: 'neutral_node', strength: 1, power_class: 'EXTREME', selection_rank: 1, net_gex: 0, call_gex: 0, put_gex: 0, abs_gex: 0, abs_flow_1pt: 0, distance_from_spot: 0, zone_half_width: 1, spot_side: 'inside', option_volume_context: { current, event: null } };",
