    assert "return usableServiceLines(support);" in pro_body
    assert "return usableServiceLines(risk);" in con_body
    assert '...pro.map(value => tooltipLine(`+ ${value}`, "pro"))' in standard_body
    assert '...con.map(value => tooltipLine(`- ${value}`, "con"))' in standard_body
    assert "function tooltipTokenRoles" in source
    assert "function tooltipMetricTokenRole" in source
