    assert "tooltipFieldValue" not in source
    assert 'warning: "warning"' in source
    assert 'neutral: "muted"' in source
    assert "const serviceSeen = new Set(lines.map(tooltipLineKey).filter(Boolean));" in source
    assert ".canvas-tooltip .tooltip-warning" in css
    assert ".canvas-tooltip .tooltip-muted" in css

    rich_line_source = (
        "function tooltipLine(text"
        + source.split(
            "function tooltipLine(text",
            1,
        )[1].split("function typedTooltipContextLines", 1)[0]
    )
    token_pattern_source = (
        "function tooltipLineTokenPattern"
        + source.split(
            "function tooltipLineTokenPattern",
            1,
        )[1].split("function appendHighlightedTooltipLine", 1)[0]
    )
    script_path = tmp_path / "typed-tooltip-lines.js"
    script_path.write_text(
        "\n".join(
            (
                "function normalizedTypedDirection(value) { const text = String(value || '').trim().toLowerCase(); return text === 'long' ? 'LONG' : text === 'short' ? 'SHORT' : ''; }",
                "function tooltipTextValue(value) { return String(value ?? '').trim(); }",
                "function fmt(value) { return Number(value).toFixed(2); }",
                "function formatPlanNumber(value) { const number = Number(value); return Number.isFinite(number) ? fmt(number) : '-'; }",
                rich_line_source,
                token_pattern_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const entry = tooltipPriceLine('ENTRY', 123.45, 'entry');",
                "check(entry.role === 'entry' && entry.token_roles['123.45'] === 'price', 'entry price must keep an explicit price role');",
                "const metrics = tooltipMetricLines({ level: { value: 123.45, digits: 2, kind: 'price' }, confidence: { value: 87, digits: 0, suffix: '%', kind: 'strength' }, bias: { value: 'LONG', tone: 'positive' } });",
                "check(metrics.length === 3, 'typed metrics must remain separate lines');",
                "check(metrics[0].token_roles.LEVEL === 'type' && metrics[0].token_roles['123.45'] === 'price', 'price metric roles must be explicit');",
                "check(metrics[1].token_roles.CONFIDENCE === 'type' && metrics[1].token_roles['87%'] === 'strength', 'strength metric roles must be explicit');",
                "check(metrics[2].token_roles.LONG === 'positive', 'typed metric tone must control emphasis');",
                "const neutralNumber = tooltipMetricLines({ stop: { value: 120.25, digits: 2 } })[0];",
                "check(!neutralNumber.token_roles['120.25'], 'an untyped numeric metric must remain neutral');",
                "const warningMetric = tooltipMetricLines({ state: { value: 'PENDING', tone: 'warning' } })[0];",
                "check(warningMetric.token_roles.PENDING === 'warning', 'typed warning metrics must keep warning emphasis');",
                "const mutedMetric = tooltipMetricLines({ bias: { value: 'FLAT', tone: 'neutral' } })[0];",
                "check(mutedMetric.token_roles.FLAT === 'muted', 'typed neutral metrics must stay muted');",
                "const direction = tooltipLabeledLine('DIR', 'LONG', 'meta', tooltipDirectionTokenRole('long'));",
                "check(direction.token_roles.DIR === 'type' && direction.token_roles.LONG === 'positive', 'direction emphasis must come from the typed direction');",
                "const phasePattern = tooltipLineTokenPattern({ role: 'title', token_roles: { IN: 'positive' } });",
                "const phaseMatches = Array.from('LINDA — IN LONG'.matchAll(phasePattern), match => match[0]);",
                "check(phaseMatches.length === 1 && phaseMatches[0] === 'IN', 'short role tokens must not highlight substrings inside words');",
                "const pricePattern = tooltipLineTokenPattern({ role: 'entry', token_roles: {} });",
                "check(pricePattern.test('ENTRY: 123.45'), 'entry price matching must remain available');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


