def test_indicator_table_numeric_cells_preserve_unknown_zero_and_linda_prices(
    tmp_path: Path,
) -> None:
    overlay_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    cell_source = (
        'const INDICATOR_TABLE_INVALID_CELL_TEXT = "N/A";'
        + overlay_source.split('const INDICATOR_TABLE_INVALID_CELL_TEXT = "N/A";', 1)[1].split(
            "function drawGenericIndicatorTable",
            1,
        )[0]
    )
    linda_source = Path("src/aef_terminal/indicators/modules/linda_volume/client.js").read_text(
        encoding="utf-8"
    )
    linda_model_source = linda_source.split("function lindaVolumeOverlayFilter", 1)[0]
    script_path = tmp_path / "indicator-table-nullable-numbers.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                cell_source,
                linda_model_source,
                'for (const kind of ["integer", "percent", "fixed", "price"]) {',
                '  assert.equal(indicatorTableCellText({ kind, value: null, empty: "--" }), "--");',
                '  assert.equal(indicatorTableCellText({ kind, value: undefined, empty: "--" }), "--");',
                '  assert.equal(indicatorTableCellText({ kind, value: "", empty: "--" }), "--");',
                "}",
                'assert.equal(indicatorTableCellText({ kind: "price", value: 0 }), "0.0000");',
                'assert.equal(indicatorTableCellText({ kind: "price", value: -1.25, digits: 2 }), "-1.25");',
                'assert.equal(indicatorTableCellText({ value: { code: "raw_object" } }), "N/A");',
                'assert.equal(indicatorTableCellText({ unknown: "object" }), "N/A");',
                'assert.equal(indicatorTableCellText({ kind: "legacy", value: "text" }), "N/A");',
                'assert.equal(indicatorTableCellText({ kind: "price", value: "101.25" }), "N/A");',
                "const columns = lindaVolumeTableColumns({ model: {",
                '  entry: { state: "wait", rr: null, level: null, detail_code: "none" },',
                '  risk: { state: "wide_range", value: null, detail_code: "wide_range" },',
                '  opponent: { state: "none", level: 0, relation: "above" },',
                '  invalidation: { state: "plan_stop", level: 101.25 },',
                "} });",
                'assert.equal(indicatorTableCellText(columns[0].cells[2]), "-");',
                'assert.equal(indicatorTableCellText(columns[1].cells[2]), "WIDE");',
                'assert.equal(indicatorTableCellText(columns[2].cells[2]), "> 0.0000");',
                'assert.equal(indicatorTableCellText(columns[3].cells[2]), "101.2500");',
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_option_reversal_why_cells_use_typed_fact_presentation(tmp_path: Path) -> None:
    overlay_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    cell_source = (
        'const INDICATOR_TABLE_INVALID_CELL_TEXT = "N/A";'
        + overlay_source.split('const INDICATOR_TABLE_INVALID_CELL_TEXT = "N/A";', 1)[1].split(
            "function drawGenericIndicatorTable",
            1,
        )[0]
    )
    tooltip_source = Path("src/aef_terminal/ui/assets/js/39-tooltip-content.js").read_text(
        encoding="utf-8"
    )
    fact_cell_source = (
        "function domainCodeLabel"
        + tooltip_source.split("function domainCodeLabel", 1)[1].split(
            "function domainFactText",
            1,
        )[0]
    )
    option_reversal_source = Path(
        "src/aef_terminal/indicators/modules/option_reversal/client.js"
    ).read_text(encoding="utf-8")
    assert "domainFactText" not in option_reversal_source
    assert "reasonWords" not in option_reversal_source
    assert ".split(/\\s+/)" not in option_reversal_source

    script_path = tmp_path / "option-reversal-typed-why-cells.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                fact_cell_source,
                cell_source,
                "function registerIndicatorTableModel() {}",
                option_reversal_source,
                "const columns = optionReversalTableColumns({",
                '  state: "BUY", score: 87, option_side: "CALL",',
                '  trigger_event: { code: "premium_compression_entry_candidate" },',
                "  target: {}, metrics: {},",
                "});",
                "const why = columns.find(column => column.cells[0] === 'WHY');",
                "assert.deepEqual(why.cells[1], { kind: 'domain_fact', value: { code: 'premium_compression_entry_candidate' }, part: 'primary' });",
                "assert.deepEqual(why.cells[2], { kind: 'domain_fact', value: { code: 'premium_compression_entry_candidate' }, part: 'secondary' });",
                "assert.equal(indicatorTableCellText(why.cells[1]), 'PREMIUM COMP.');",
                "assert.equal(indicatorTableCellText(why.cells[2]), 'ENTRY CANDIDATE');",
                "assert.equal(indicatorTableCellText({ kind: 'domain_fact', value: { code: 'future_typed_reason' }, part: 'primary' }), 'FUTURE TYPED REASON');",
                "assert.equal(indicatorTableCellText({ kind: 'domain_fact', value: { code: 'future_typed_reason' }, part: 'secondary' }), '-');",
                "assert.equal(indicatorTableCellText({ kind: 'domain_fact', value: 'legacy prose', part: 'primary' }), 'N/A');",
                "assert.equal(indicatorTableCellText({ kind: 'domain_fact', value: { code: 'option_edge_absent' }, part: 'legacy' }), 'N/A');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_projected_indicator_endpoint_uses_bar_axis_across_overnight_break(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    endpoint_source = (
        "function genericOverlayLookupForVisible(visible, bars, allBars = bars)"
        + source.split(
            "function genericOverlayLookupForVisible(visible, bars, allBars = bars)",
            1,
        )[1].split("function drawGenericOverlayBox", 1)[0]
    )
    script_path = tmp_path / "indicator-projected-endpoint.js"
    script_path.write_text(
        "\n".join(
            (
                "function intervalMinutesFromState() { return 5; }",
                "function timestampKey(ts) { return new Date(Date.parse(ts)).toISOString(); }",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "const chartRenderVersions = { bars: 0 };",
                "const genericOverlayLookupCache = new WeakMap();",
                endpoint_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const friday = Date.parse('2026-07-17T19:55:00.000Z');",
                "const monday = Date.parse('2026-07-20T13:30:00.000Z');",
                "const lookup = { times: [friday, monday], absoluteByTimestamp: new Map([[friday, 0], [monday, 1]]), indexOffset: 0 };",
                "const x = index => index * 10;",
                "const projected = { end_anchor_ts: '2026-07-17T19:55:00.000Z', end_anchor_bar_slot: 100, end_bar_offset: 28 };",
                "check(xForOverlayEnd(projected, lookup, 10, x) === 280, '28-bar projection must not collapse into the overnight wall-clock gap');",
                "const exact = { end_ts: '2026-07-20T13:30:00.000Z', end_bar_slot: 9000 };",
                "check(xForOverlayEnd(exact, lookup, 10, x) === 10, 'historical exact timestamp endpoint must retain timestamp mapping');",
                "const malformed = { end_anchor_ts: 'bad', end_bar_offset: 28, end_ts: '2026-07-20T13:30:00.000Z' };",
                "check(xForOverlayEnd(malformed, lookup, 10, x) === null, 'malformed typed projection must fail closed without wall-clock fallback');",
                "check(xForOverlayEnd({ end_anchor_ts: projected.end_anchor_ts, end_bar_offset: 0 }, lookup, 10, x) === null, 'zero-length projected endpoint must fail closed');",
                "const visible = { start: 1, end: 2 };",
                "const axisBars = [{ ts: projected.end_anchor_ts, bar_slot: 100 }, { ts: exact.end_ts, bar_slot: 500 }];",
                "const fullAxisLookup = genericOverlayLookupForVisible(visible, axisBars.slice(1), axisBars);",
                "check(xForOverlayTime(fullAxisLookup, friday, 10, x) === -10, 'offscreen start must remain addressable on the full canonical axis');",
                "check(xForOverlayEnd({ end_anchor_ts: projected.end_anchor_ts, end_bar_offset: 2 }, fullAxisLookup, 10, x) === 10, 'projected line crossing the left viewport edge must remain drawable');",
                "check(xForOverlayTime(genericOverlayLookupForVisible({ start: 0 }, axisBars, axisBars), friday, 10, x) === 0, 'first axis timestamp must map to the first x coordinate');",
                "const prunedLookup = genericOverlayLookupForVisible({ start: 0 }, axisBars.slice(1), axisBars.slice(1));",
                "check(xForOverlayTime(prunedLookup, friday, 10, x) === null, 'pruned timestamp without a slot must fail closed');",
                "check(xForOverlayTime(prunedLookup, friday, 10, x, 100) === null, 'schedule-ranked slot must never rescue a missing confirmed timestamp');",
                "const clipped = clipOverlayLineToPlotX(-10, 20, 10, 40, 0, 100);",
                "check(clipped.x1 === 0 && clipped.y1 === 30 && clipped.x2 === 10 && clipped.y2 === 40, 'line clipping must interpolate the retained boundary');",
                "const oneBarBox = clipOverlayBoxToPlotX(10, 10, 0, 100, 10);",
                "check(oneBarBox.left === 5.5 && oneBarBox.right === 14.5, 'same-timestamp box must receive one visible candle footprint');",
                "const edgeBox = clipOverlayBoxToPlotX(0, 0, 0, 100, 10);",
                "check(edgeBox.left === 0 && edgeBox.right >= 2, 'edge box must remain visible inside the plot');",
                "axisBars.push({ ts: '2026-07-20T13:35:00.000Z', bar_slot: 110 });",
                "const appendedLookup = genericOverlayLookupForVisible({ start: 0 }, axisBars, axisBars);",
                "check(appendedLookup.times.length === 3, 'same-array append must invalidate cached axis coordinates');",
                "axisBars[1] = { ts: '2026-07-20T13:31:00.000Z', bar_slot: 105 };",
                "chartRenderVersions.bars += 1;",
                "const correctedLookup = genericOverlayLookupForVisible({ start: 0 }, axisBars, axisBars);",
                "check(correctedLookup.times[1] === Date.parse(axisBars[1].ts), 'bar-axis version bump must invalidate a same-length in-place correction');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


