def test_indicator_renderer_refs_do_not_register_direct_frontend_painters() -> None:
    js = martincall_js_source()
    manifest = indicator_manifest()
    core_manager_source = Path("src/aef_terminal/ui/assets/js/48-overlays-manager.js").read_text(
        encoding="utf-8"
    )
    core_overlay_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    manager_body = js.split("function createPriceOverlayDrawManager()", 1)[1].split(
        "function drawManagedPriceOverlays", 1
    )[0]
    renderer_items = {
        indicator_id: item
        for indicator_id, item in manifest.items()
        if item["renderer_kind"] in {"custom", "service"} and item["overlay_collect"] is not False
    }

    assert renderer_items
    assert "rendererContract: spec.renderer_contract || {}" in js
    assert "function indicatorPriceOverlayProvider(rendererRef, call)" not in js
    assert (
        "registerUniqueProvider(manager, seen, indicatorPriceOverlayProvider(spec.ref, call));"
        not in js
    )
    custom_renderer_refs = set(
        re.findall(
            r'registerIndicatorCustomOverlayRenderer\(\s*"([^"]+)"',
            js,
        )
    )
    for indicator_id, item in renderer_items.items():
        renderer_ref = item["renderer_ref"]
        assert f"{renderer_ref}: () =>" not in manager_body, indicator_id
        requirements = set(
            item["renderer_contract"]["custom_requirements"]
            + item["renderer_contract"]["service_requirements"]
        )
        if item["renderer_kind"] == "custom":
            assert "price_overlay_provider" in requirements, indicator_id
            if "custom" in item["renderer_contract"]["primitives"]:
                assert renderer_ref in custom_renderer_refs, indicator_id
        if item["renderer_kind"] == "service":
            assert requirements, indicator_id
    assert "function registerIndicatorCustomOverlayRenderer" in js
    assert "function drawIndicatorCustomOverlay(rendererRef, context)" in js
    assert "drawIndicatorCustomOverlay(item.renderer_ref, {" in js
    assert "payload: item.payload" in js
    assert "martin_carlo_forecast" not in core_manager_source
    assert "martin_carlo_forecast" not in core_overlay_source


