def test_drawing_object_edits_use_commit_redraw_and_drag_overlay() -> None:
    js = martincall_js_source()

    assert "function renderDrawingOverlay(options = {})" in js
    assert "let drawingOverlayFrame = 0;" in js
    assert "drawingOverlayFrame = requestAnimationFrame(() => {" in js
    assert "function renderInteractionOverlay(options = {})" in js
    assert (
        'if (typeof renderPriceObjects === "function")'
        not in js.split("function renderDrawingOverlay", 1)[1].split(
            "function renderInteractionOverlay", 1
        )[0]
    )
    selected_body = js.split("function updateSelectedDrawing(patch)", 1)[1].split(
        "function deleteSelectedDrawing()", 1
    )[0]
    handle_body = js.split("function updateDrawingHandle(handle, localX, localY)", 1)[1].split(
        "function startDrawingHandleDrag", 1
    )[0]
    drag_body = js.split("function startDrawingHandleDrag(canvas, event, handle)", 1)[1].split(
        "function syncObjectControls()", 1
    )[0]
    mouse_body = js.split('canvas.addEventListener("mousemove", event =>', 1)[1].split(
        'canvas.addEventListener("mouseleave"', 1
    )[0]
    mouseleave_body = js.split('canvas.addEventListener("mouseleave", () =>', 1)[1].split(
        'canvas.addEventListener("wheel"', 1
    )[0]

    assert 'requestObjectLayerRedraw("drawing updated", { force: true });' in selected_body
    assert "renderCharts(state.snapshot)" not in selected_body
    assert "renderInteractionOverlay();" in handle_body
    assert "renderDrawingOverlay();" not in handle_body
    assert "renderCharts(state.snapshot)" not in handle_body
    assert "object.points[handle.index] = point;" in handle_body
    assert "...object.points[handle.index]" not in handle_body
    assert 'requestObjectLayerRedraw("drawing drag committed", { force: true });' in drag_body
    assert "renderCharts(state.snapshot)" not in drag_body
    assert "renderDrawingBaseWithout(handle.id);" in drag_body
    assert "state.drawing.localEditUntil = Date.now() + DRAWING_LOCAL_EDIT_GRACE_MS;" in drag_body
    assert 'canvas.addEventListener("pointercancel", onCancel);' in drag_body
    assert 'canvas.addEventListener("lostpointercapture", onCancel);' in drag_body
    assert "function resolvedChannelOffset(object, axis)" in js
    assert "object.offsetPoint || object.points[2]" not in js
    assert "object.offset_point" not in js
    assert "function normalizeDrawingChannel(item)" not in js
