def test_snapshot_range_slicing_only_mutates_declared_bar_aligned_sections(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(encoding="utf-8")
    slice_source = (
        "function sliceKnownBarAlignedArray"
        + source.split("function sliceKnownBarAlignedArray", 1)[1].split(
            "function canonicalLiveTailKey",
            1,
        )[0]
    )
    script_path = tmp_path / "snapshot-aligned-slicing.js"
    script_path.write_text(
        "\n".join(
            (
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                slice_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const bars = [0, 1, 2, 3].map(index => ({ ts: `2026-01-01T00:0${index}:00Z` }));",
                "const events = bars.map((_, index) => ({ id: `event-${index}` }));",
                "const overlays = bars.map((_, index) => ({ id: `overlay-${index}` }));",
                "const snapshot = { bars, indicators: { demo: { events, overlays } }, chart_guides: { ema: { 20: [10, 11, 12, 13] }, vwap: [20, 21, 22, 23], context: { coincidental: [1, 2, 3, 4] }, meta: { bar_count: 4 } }, vsa_volume: { series: [30, 31, 32, 33], events, status: { series_count: 4 } }, features: { coincidental: [40, 41, 42, 43] }, meta: {} };",
                "const sliced = sliceSnapshotAlignedRange(snapshot, 1, 3);",
                "check(sliced.bars.length === 2 && sliced.bars[0] === bars[1], 'bars must be sliced');",
                "check(sliced.chart_guides.ema[20].join(',') === '11,12', 'EMA must be sliced');",
                "check(sliced.chart_guides.vwap.join(',') === '21,22', 'VWAP must be sliced');",
                "check(sliced.vsa_volume.series.join(',') === '31,32', 'VSA series must be sliced');",
                "check(sliced.vsa_volume.status.series_count === 2, 'VSA status must match sliced series');",
                "check(sliced.indicators.demo.events === events, 'indicator events must not be inferred as bar-aligned');",
                "check(sliced.indicators.demo.overlays === overlays, 'overlays must not be inferred as bar-aligned');",
                "check(sliced.features.coincidental.length === 4, 'unknown arrays must remain untouched');",
                "check(sliced.chart_guides.context.coincidental.length === 4, 'guide context arrays must remain untouched');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_client_overlay_compaction_preserves_active_geometry(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(encoding="utf-8")
    compact_source = (
        "function compactOverlayTail"
        + source.split("function compactOverlayTail", 1)[1].split(
            "function compactIndicatorArray",
            1,
        )[0]
    )
    script_path = tmp_path / "active-overlay-compaction.js"
    script_path.write_text(
        "\n".join(
            (
                compact_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const active = Array.from({ length: 12 }, (_, index) => ({ id: `active-${index}`, retention: 'active' }));",
                "const history = Array.from({ length: 140 }, (_, index) => ({ id: `history-${index}` }));",
                "const compacted = compactOverlayTail([...active, ...history], 120);",
                "check(compacted.length === 120, 'soft limit must be respected when active geometry fits');",
                "check(compacted.slice(0, 12).every((item, index) => item === active[index]), 'all active geometry must survive');",
                "check(compacted[12].id === 'history-32' && compacted.at(-1).id === 'history-139', 'remaining slots must retain the newest history');",
                "const activeOverflow = Array.from({ length: 121 }, (_, index) => ({ id: `overflow-${index}`, retention: 'active' }));",
                "check(compactOverlayTail(activeOverflow, 120).length === 121, 'active geometry must outrank the soft limit');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


