def test_range_preset_clears_chart_before_loading_timeframe_objects(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/60-interactions-drawings-alerts.js").read_text(
        encoding="utf-8"
    )
    handler_source = (
        "async function applyChartRangePreset(key)"
        + source.split("async function applyChartRangePreset(key)", 1)[1].split(
            'rangeButton?.addEventListener("click"',
            1,
        )[0]
    )
    script_path = tmp_path / "range-preset-object-order.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const events = []; const DEFAULT_RIGHT_GAP_BARS = 8;",
                "const rangePresets = { '1m': { label: '1M', timeframe: '15m', loadRange: '31d' } };",
                "const state = { instrumentId: 'instrument-a', timeframe: '5m', range: '5d', requests: { history: { exhausted: true } }, crosshair: { visible: true }, snapshot: { stale: true }, gexContexts: {}, loadingGexKeys: {} };",
                "const view = { offset: 4, historyPullOffsetBars: 3, rightGapBars: 2, rightGapManual: true, followLatest: false };",
                "function setRangeMenuOpen() {} function publishLinkedCrosshair() { events.push('crosshair'); } function closeQuoteStream() { events.push('close-quote'); }",
                "function workspaceSet() {} function setServerSettingValue() {} function rangeStorageKey() { return 'range'; } function setUiNotice(_owner, code) { events.push(`notice-${code}`); }",
                "function clearChartStateForRouteSwitch() { events.push('clear-chart'); state.snapshot = null; }",
                "function loadIndicatorSettingsForCurrent() { events.push('load-indicators'); }",
                "function loadDrawingsForCurrent() { events.push('load-drawings'); }",
                "function loadPriceAlertsForCurrent() { events.push('duplicate-alert-load'); }",
                "function gexContextKey() { return 'gex'; } function setActiveGexContext() {} function applySettings() { events.push('settings'); } function renderPanel() { events.push('render-stale'); }",
                "async function load(options) { events.push('load-market'); assert.equal(options.historyPreset, true); return true; } function fitLoadedRangeToScreen() { events.push('fit'); } function loadScreener() {} function connectQuoteStream() {} function syncWorkspacePageState() {}",
                handler_source,
                "(async () => { await applyChartRangePreset('1m');",
                "  assert.ok(events.indexOf('clear-chart') < events.indexOf('load-indicators')); assert.ok(events.indexOf('clear-chart') < events.indexOf('load-drawings')); assert.ok(events.indexOf('load-drawings') < events.indexOf('notice-HISTORY_PRESET_LOADING')); assert.ok(events.indexOf('notice-HISTORY_PRESET_LOADING') < events.indexOf('load-market'));",
                "  assert.equal(events.includes('duplicate-alert-load'), false, 'range switch loaded alerts twice'); assert.equal(events.includes('render-stale'), false, 'old snapshot rendered after route clear');",
                "})().catch(error => { console.error(error); process.exitCode = 1; });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


