def test_market_chart_transition_retry_is_exact_scoped_bounded_and_settles_preset_notice(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(encoding="utf-8")
    helper_source = (
        "function settleHistoryPresetNotice(options, failure = null)"
        + source.split("function settleHistoryPresetNotice(options, failure = null)", 1)[1].split(
            "function paperJournalRefreshOptions", 1
        )[0]
    )
    scope_source = (
        "function marketSnapshotMatchesExactScope("
        + source.split("function marketSnapshotMatchesExactScope(", 1)[1].split(
            "function isValidFutureAxisPayload", 1
        )[0]
    )
    load_source = source.split("async function load(options = {})", 1)[1].split(
        "async function loadPaperJournal", 1
    )[0]
    assert "const requestOwnsExactMarketScope = () => (" in load_source
    assert "requestOwnsMarketState()" in load_source
    assert "!state.requests.market.pending" in load_source
    assert "exactIdentityText(state.instrumentId) === requestInstrumentId" in load_source
    assert "instrumentRouteFingerprint() === requestRouteFingerprint" in load_source
    assert "state.dataSource === requestSource" in load_source
    assert "state.timeframe === requestTimeframe" in load_source
    assert "state.range === range" in load_source
    assert "marketSnapshotMatchesExactScope(" in load_source
    assert 'const mismatchCode = "MARKET_SNAPSHOT_SCOPE_MISMATCH";' in load_source
    assert "projectMarketChartLoadFailure(options, mismatchCode, mismatchMessage);" in load_source
    assert (
        'if (error?.name === "AbortError") {\n          settleHistoryPresetNotice(options);'
        in load_source
    )
    route_mismatch_branch = load_source.split('if (errorCode === "ROUTE_SELECTION_MISMATCH")', 1)[
        1
    ].split('console.warn("market refresh failed", error);', 1)[0]
    assert "options.routeResyncAttempted !== true" in route_mismatch_branch
    assert "state.requests.market.pending = true;" in route_mismatch_branch
    assert (
        "projectMarketChartLoadFailure(options, errorCode, failureMessage);"
        in route_mismatch_branch
    )
    assert "return await load" not in load_source
    assert "scopeEpoch" not in source
    assert "marketChartTransitionRetryAttempt" not in source
    script_path = tmp_path / "market-chart-transition-retry.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const MARKET_CHART_TRANSITION_RETRY_MAX_ATTEMPTS = 3;",
                "const MARKET_CHART_TRANSITION_RETRY_BASE_DELAY_MS = 150;",
                "const MARKET_CHART_TRANSITION_RETRY_CODES = new Set(['MARKET_CHART_GENERATION_CHANGED', 'CHART_BARS_WRITE_IN_PROGRESS']);",
                "const calls = []; const delays = []; const unavailable = []; let outcomes = []; let ownsScope = true;",
                "const state = { snapshot: null, notices: { history: { code: 'HISTORY_PRESET_LOADING' } } };",
                "const window = { setTimeout(callback, delay) { delays.push(delay); callback(); return 1; } };",
                "function exactIdentityText(value) { return String(value || ''); }",
                "function requestErrorCode(error) { return String(error?.payload?.error?.code || ''); }",
                "function clearUiNotice(owner) { if (!state.notices[owner]) return false; delete state.notices[owner]; return true; }",
                "function setUiNotice(owner, code, message, options = {}) { state.notices[owner] = { code, message, ...options }; return state.notices[owner]; }",
                "function renderChartTransitionFailureCanvases(code, message) { unavailable.push({ code, message }); }",
                "async function fetchJson(url, options) { calls.push({ url, options }); const outcome = outcomes.shift(); if (outcome instanceof Error) throw outcome; return outcome; }",
                helper_source,
                scope_source,
                "function typedError(code) { const error = new Error(code); error.payload = { error: { code } }; return error; }",
                "const generationError = typedError('MARKET_CHART_GENERATION_CHANGED');",
                "const writeError = typedError('CHART_BARS_WRITE_IN_PROGRESS');",
                "(async () => {",
                "  const signal = {}; outcomes = [generationError, { bars: [{ timeframe: '15m' }] }];",
                "  const recovered = await fetchMarketSnapshotWithTransitionRetry('/market?timeframe=15m&range=31d', { signal }, () => ownsScope);",
                "  assert.equal(recovered.bars[0].timeframe, '15m'); assert.equal(calls.length, 2); assert.equal(calls[0].options.signal, signal); assert.equal(calls[1].options.signal, signal); assert.deepEqual(delays, [150]);",
                "  assert.equal(state.notices.history.code, 'HISTORY_PRESET_LOADING'); settleHistoryPresetNotice({ historyPreset: true }); assert.equal(state.notices.history, undefined);",
                "  const exactSnapshot = { meta: { instrument_id: 'instrument-spy', route_fingerprint: 'route-spy', timeframe: '15m', chart_range: '31d' } };",
                "  assert.equal(marketSnapshotMatchesExactScope(exactSnapshot, 'instrument-spy', 'route-spy', '15m', '31d'), true);",
                "  assert.equal(marketSnapshotMatchesExactScope({ meta: { ...exactSnapshot.meta, timeframe: '5m' } }, 'instrument-spy', 'route-spy', '15m', '31d'), false);",
                "  assert.equal(marketSnapshotMatchesExactScope({ meta: { ...exactSnapshot.meta, chart_range: '5d' } }, 'instrument-spy', 'route-spy', '15m', '31d'), false);",
                "  state.notices.history = { code: 'HISTORY_PRESET_LOADING' }; settleHistoryPresetNotice({ historyPreset: true }, { code: 'SERVER_SLEEPING', message: 'sleeping', state: 'sleeping' }); assert.equal(state.notices.history.state, 'sleeping');",
                "  calls.length = 0; delays.length = 0; state.notices.history = { code: 'HISTORY_PRESET_LOADING' }; outcomes = [writeError, writeError, writeError, writeError];",
                "  let terminalError = null; try { await fetchMarketSnapshotWithTransitionRetry('/market', { signal }, () => ownsScope); } catch (error) { terminalError = error; }",
                "  assert.equal(requestErrorCode(terminalError), 'CHART_BARS_WRITE_IN_PROGRESS');",
                "  assert.equal(calls.length, 4, 'retry bound must allow only the initial request plus three retries'); assert.deepEqual(delays, [150, 300, 450]);",
                "  projectMarketChartLoadFailure({ historyPreset: true }, requestErrorCode(terminalError), 'write still in progress'); assert.equal(state.notices.history.code, 'CHART_BARS_WRITE_IN_PROGRESS'); assert.equal(state.notices.market.code, 'CHART_BARS_WRITE_IN_PROGRESS'); assert.equal(unavailable.at(-1).code, 'CHART_BARS_WRITE_IN_PROGRESS');",
                "  calls.length = 0; delays.length = 0; ownsScope = true; state.notices.history = { code: 'HISTORY_PRESET_LOADING' }; outcomes = [generationError, { bars: [{ timeframe: 'stale' }] }];",
                "  window.setTimeout = callback => { ownsScope = false; callback(); return 1; };",
                "  await assert.rejects(() => fetchMarketSnapshotWithTransitionRetry('/market', { signal }, () => ownsScope), error => error.name === 'AbortError');",
                "  assert.equal(calls.length, 1, 'a superseded request must not issue a stale retry');",
                "})().catch(error => { console.error(error); process.exitCode = 1; });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


