def test_directional_rocket_canvas_renderers_flip_only_for_typed_short(
    tmp_path: Path,
) -> None:
    drawing_source = Path("src/aef_terminal/ui/assets/js/40-chart-drawing-utils.js").read_text(
        encoding="utf-8"
    )
    label_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicator-labels.js").read_text(
        encoding="utf-8"
    )
    overlay_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    drawing_subset = (
        "function normalizePointerLabelLines"
        + drawing_source.split("function normalizePointerLabelLines", 1)[1].split(
            "function drawSignalTick",
            1,
        )[0]
    )
    label_dispatch_subset = (
        "function drawIndicatorTextLabel"
        + label_source.split("function drawIndicatorTextLabel", 1)[1].split(
            "function verticalIndicatorTextLines",
            1,
        )[0]
    )
    stacked_subset = (
        "function drawStackedTextMark" + label_source.split("function drawStackedTextMark", 1)[1]
    )
    lifecycle_subset = (
        "function drawLifecycleMarker"
        + overlay_source.split("function drawLifecycleMarker", 1)[1].split(
            "function drawRoundPivotMarker",
            1,
        )[0]
    )
    script_path = tmp_path / "directional-rocket-canvas.js"
    script_path.write_text(
        "\n".join(
            (
                """
const GO_MARK = "🚀";
const rgbaColorCache = new Map();
const state = { settings: { indicatorLabelStyle: "box" } };
const document = { body: { classList: { contains: () => false } } };
function clamp(value, low, high) { return Math.min(Math.max(value, low), high); }
function compactLabelToken(value) { return String(value || ""); }
function normalizeIndicatorLabelStyle(value) { return value === "box" ? "box" : "text"; }
function normalizedTypedDirection(value) {
  const text = String(value || "").trim().toLowerCase();
  return text === "long" ? "LONG" : text === "short" ? "SHORT" : "";
}
function normalizedOverlaySignal(item) {
  return { direction: normalizedTypedDirection(item?.direction) };
}
function themeColor() { return "#f3d35b"; }
function css() { return "#dbe7f5"; }
function readableTextForBg(_bg, fallback) { return fallback || "#fff"; }
function rgbaFromCssColor(color) { return color; }
function isLightTheme() { return false; }
function canvasShadowBlur(value) { return value; }
function isChartPlotXVisible() { return true; }
function indicatorOverlayColor() { return "#f3d35b"; }
function registerCanvasTooltip() {}
function standardSignalTooltip() { return ""; }

class FakeContext {
  constructor() {
    this.ops = [];
    this.stack = [];
    this.scaleY = 1;
    this.font = "900 12px sans-serif";
    this.textAlign = "center";
    this.textBaseline = "top";
    this.lineWidth = 1;
    this.strokeStyle = "#000";
    this.fillStyle = "#fff";
    this.shadowColor = "transparent";
    this.shadowBlur = 0;
  }
  save() {
    this.stack.push({
      scaleY: this.scaleY,
      font: this.font,
      textAlign: this.textAlign,
      textBaseline: this.textBaseline,
      lineWidth: this.lineWidth,
      strokeStyle: this.strokeStyle,
      fillStyle: this.fillStyle,
      shadowColor: this.shadowColor,
      shadowBlur: this.shadowBlur,
    });
  }
  restore() { Object.assign(this, this.stack.pop()); }
  translate() {}
  scale(_x, y) { this.scaleY *= y; }
  measureText(text) {
    return { width: String(text).includes(GO_MARK) ? 12 : Math.max(6, [...String(text)].length * 7) };
  }
  strokeText(text) { this.ops.push({ kind: "stroke", text: String(text), scaleY: this.scaleY }); }
  fillText(text) { this.ops.push({ kind: "fill", text: String(text), scaleY: this.scaleY }); }
  beginPath() {}
  moveTo() {}
  lineTo() {}
  quadraticCurveTo() {}
  closePath() {}
  fill() {}
  stroke() {}
  arc() {}
  setLineDash() {}
}

function check(condition, message) {
  if (!condition) throw new Error(message);
}
function rocketOps(ctx) { return ctx.ops.filter(op => op.text.includes(GO_MARK)); }
function exactOps(ctx, text) { return ctx.ops.filter(op => op.text === text); }
function assertDirection(ctx, expectedScale, name) {
  const rockets = rocketOps(ctx);
  check(rockets.length > 0, `${name}: rocket was not drawn`);
  check(rockets.every(op => op.scaleY === expectedScale), `${name}: wrong rocket orientation`);
  check(exactOps(ctx, "↓").every(op => op.scaleY === 1), `${name}: direction arrow was mirrored`);
  check(exactOps(ctx, "SET").every(op => op.scaleY === 1), `${name}: SET was mirrored`);
  check(exactOps(ctx, "ABS").every(op => op.scaleY === 1), `${name}: ABS was mirrored`);
}
""",
                drawing_subset,
                label_dispatch_subset,
                stacked_subset,
                lifecycle_subset,
                """
for (const style of ["box", "text"]) {
  for (const direction of ["long", "short"]) {
    state.settings.indicatorLabelStyle = style;
    const ctx = new FakeContext();
    drawIndicatorTextLabel(ctx, 80, 80, [`${GO_MARK}↓`, "SET"], {
      direction,
      side: "above",
      minX: 0,
      maxX: 180,
      minY: 0,
      maxY: 180,
    });
    assertDirection(ctx, direction === "short" ? -1 : 1, `${style}/${direction}`);
  }
}

for (const direction of ["long", "short"]) {
  const ctx = new FakeContext();
  drawLifecycleMarker(
    ctx,
    { direction, role: "setup_state" },
    80,
    80,
    [`${GO_MARK}↓`],
    "setup_state",
    {},
    Number.NaN,
  );
  assertDirection(ctx, direction === "short" ? -1 : 1, `lifecycle/${direction}`);
  if (direction === "short") {
    check(
      rocketOps(ctx).some(op => op.kind === "stroke")
        && rocketOps(ctx).some(op => op.kind === "fill"),
      "lifecycle/short: fill and outline must share the mirrored transform",
    );
  }
}

for (const direction of ["long", "short"]) {
  state.settings.indicatorLabelStyle = "text";
  const ctx = new FakeContext();
  drawIndicatorTextLabel(ctx, 80, 80, [GO_MARK, "ABS"], {
    direction,
    side: "above",
    absorptionWall: true,
    wallDirection: direction === "short" ? "down" : "up",
    minX: 0,
    maxX: 180,
    minY: 0,
    maxY: 180,
  });
  assertDirection(ctx, direction === "short" ? -1 : 1, `absorption/${direction}`);
}

state.settings.indicatorLabelStyle = "text";
const untyped = new FakeContext();
drawIndicatorTextLabel(untyped, 80, 80, [`${GO_MARK}↓`, "SET"], {
  side: "above",
  minX: 0,
  maxX: 180,
  minY: 0,
  maxY: 180,
});
assertDirection(untyped, 1, "untyped");
""",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


def test_directional_rocket_dom_contract_uses_typed_direction(
    tmp_path: Path,
) -> None:
    tooltip_source = (
        Path("src/aef_terminal/ui/assets/js/39-tooltip-content.js").read_text(encoding="utf-8")
        + "\n"
        + Path("src/aef_terminal/ui/assets/js/39-chart-tooltips.js").read_text(encoding="utf-8")
    )
    tooltip_line_subset = (
        "function tooltipLine"
        + tooltip_source.split("function tooltipLine", 1)[1].split(
            "function tooltipPriceLine",
            1,
        )[0]
    )
    tooltip_value_subset = (
        "function tooltipLineText"
        + tooltip_source.split("function tooltipLineText", 1)[1].split(
            "function tooltipContextValueLines",
            1,
        )[0]
    )
    direction_subset = (
        "function normalizedTypedDirection"
        + tooltip_source.split("function normalizedTypedDirection", 1)[1].split(
            "function normalizedOverlaySignal",
            1,
        )[0]
    )
    tooltip_class_subset = (
        "function tooltipImportantSpanClass"
        + tooltip_source.split("function tooltipImportantSpanClass", 1)[1].split(
            "function tooltipCellText",
            1,
        )[0]
    )
    script_path = tmp_path / "directional-rocket-dom.js"
    script_path.write_text(
        "\n".join(
            (
                'const GO_MARK = "🚀";',
                direction_subset,
                tooltip_line_subset,
                tooltip_value_subset,
                tooltip_class_subset,
                """
function check(condition, message) {
  if (!condition) throw new Error(message);
}
const longLine = tooltipLabeledLine("ACTION", `${GO_MARK} Вход`, "meta", "positive", "long");
const shortLine = tooltipLabeledLine("ACTION", `${GO_MARK} Вход`, "meta", "positive", "short");
check(longLine.token_roles[GO_MARK] === "go-long", "long tooltip must carry typed rocket direction");
check(shortLine.token_roles[GO_MARK] === "go-short", "short tooltip must carry typed rocket direction");
check(
  tooltipImportantSpanClass(GO_MARK, longLine) === "tooltip-key tooltip-positive directional-go-mark",
  "long tooltip rocket class is incorrect",
);
check(
  tooltipImportantSpanClass(GO_MARK, shortLine) === "tooltip-key tooltip-negative directional-go-mark short",
  "short tooltip rocket class is incorrect",
);
check(!directionalGoMarkHtml("long").includes("directional-go-mark short"), "long DOM rocket was mirrored");
check(directionalGoMarkHtml("short").includes("directional-go-mark short"), "short DOM rocket was not mirrored");
""",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


def test_indicator_fact_renderer_is_strict_and_cache_keys_include_nested_facts(
    tmp_path: Path,
) -> None:
    tooltip_source = Path("src/aef_terminal/ui/assets/js/39-tooltip-content.js").read_text(
        encoding="utf-8"
    )
    chart_source = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(
        encoding="utf-8"
    )
    domain_source = (
        "function domainCodeLabel"
        + tooltip_source.split(
            "function domainCodeLabel",
            1,
        )[1].split("function actionPhaseGlyph", 1)[0]
    )
    facts_source = (
        "function indicatorFactsForDisplay"
        + tooltip_source.split(
            "function indicatorFactsForDisplay",
            1,
        )[1].split("function actionCardFromItem", 1)[0]
    )
    stable_source = (
        "function chartStableJson"
        + chart_source.split(
            "function chartStableJson",
            1,
        )[1].split("const chartRenderVersions", 1)[0]
    )
    hash_source = (
        "function chartHashParts"
        + chart_source.split(
            "function chartHashParts",
            1,
        )[1].split("function chartIndicatorVisualItemKey", 1)[0]
    )
    cache_source = (
        "function compactTooltipCacheValue"
        + tooltip_source.split(
            "function compactTooltipCacheValue",
            1,
        )[1].split("function standardSignalTooltip(item", 1)[0]
    )
    candidate_source = Path("src/aef_terminal/ui/assets/js/30-market-panel-runtime.js").read_text(
        encoding="utf-8"
    )
    candidate_body = candidate_source.split("function renderCandidateRow(candidate)", 1)[1].split(
        "function sentimentSourceLabel",
        1,
    )[0]

    assert "const triggerEvent = candidate?.trigger_event;" in candidate_body
    assert 'typeof triggerEvent.code === "string"' in candidate_body
    assert "domainFactText(triggerEvent)" in candidate_body
    assert "candidate?.facts" not in candidate_body
    assert "candidate?.reason" not in candidate_body
    assert "candidate?.reason_code" not in candidate_body
    assert "fact.content || fact.detail || fact.value || fact.status" not in domain_source
    assert (
        "const typedDetails = [fact.content, fact.state, fact.detail_code, fact.direction]"
        in domain_source
    )
    assert 'if (typeof value !== "string") return "";' in domain_source
    assert (
        "chartSnapshotRenderId"
        not in tooltip_source.split("function standardTooltipScopeKey", 1)[1].split(
            "function resetStandardTooltipCachesIfNeeded",
            1,
        )[0]
    )

    script_path = tmp_path / "strict-indicator-facts.js"
    script_path.write_text(
        "\n".join(
            (
                domain_source,
                facts_source,
                stable_source,
                hash_source,
                cache_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const typed = indicatorFactsForDisplay({ direction: 'long', scenario: 'breakout', setup: 'momentum', trigger_event: { code: 'breakout_confirmed' }, evidence: { supporting: [{ code: 'momentum_aligned', content: 'EMA stack supports breakout' }, 'legacy scalar'], opposing: [{ code: 'late_entry' }], context: [{ code: 'high_rvol' }, 'legacy context'] }, risk: { code: 'risk_invalidated', content: 'below_vwap', blocks: [{ code: 'short' }, 'legacy block'] }, quality: { code: 'quality_high' }, fact_groups: [{ kind: 'validation', items: [{ code: 'volume_confirmed' }, 'legacy item'] }, { kind: 'legacy', rows: [['display row']] }], metrics: { score: 87 } });",
                "check(typed.trigger_label === 'Breakout confirmed', 'typed trigger event must render');",
                "check(typed.pro.length === 2 && typed.pro[0] === 'Momentum aligned: EMA stack supports breakout', 'typed evidence content must survive while scalar facts are ignored');",
                "check(typed.pro.length === 2 && typed.pro.includes('Risk invalidated: Below vwap'), 'opposite-side risk block must support the active direction');",
                "check(typed.con.length === 1 && typed.con[0] === 'Late entry', 'opposite-side block must not be rendered against the active direction');",
                "check(typed.context_lines.length === 1 && typed.context_lines[0] === 'High rvol', 'scalar context must be ignored');",
                "check(typed.risk_text === 'Risk invalidated: Below vwap' && typed.quality_text === 'Quality high', 'risk and quality Fact objects must render');",
                "check(typed.tables.length === 1 && typed.tables[0].rows.length === 1, 'legacy fact-group rows must be ignored');",
                "check(!JSON.stringify(typed).includes('[object Object]'), 'typed facts must never stringify as object placeholders');",
                "const legacy = indicatorFactsForDisplay({ trigger_label: 'legacy trigger', risk: 'legacy risk', quality: 'legacy quality', evidence: ['legacy evidence'] });",
                "check(legacy.trigger_event === null && legacy.risk === null && legacy.quality === null && legacy.evidence.context.length === 0, 'legacy scalar facts must not survive normalization');",
                "check(legacy.trigger_label === '' && legacy.risk_text === '' && legacy.quality_text === '' && legacy.context_lines.length === 0, 'scalar fact fallbacks must fail closed');",
                "check(domainFactText('legacy scalar') === '' && domainFactText(['legacy scalar']) === '', 'fact renderer must reject scalar and array rescue paths');",
                "check(domainFactText({ code: 'option_market_data_pending' }) === 'Waiting for broker option data', 'Option Reversal pending state must identify broker data');",
                "check(domainFactText({ code: 'option_market_data_stale' }) === 'Broker option data stale', 'Option Reversal stale state must not ask for another point');",
                "check(domainFactText({ code: 'linda_turtle_sweep_rejected', level: 101.6, side: 'high' }) === 'Swept prior high 101.60; closed back below.', 'Linda sweep fact must render from typed attributes');",
                "check(domainFactText({ code: 'linda_hv_squeeze_break', short_length: 6, long_length: 100, stdev_ratio: 0.424, direction: 'long' }) === '6/100 stdev ratio 0.42; range break long.', 'Linda squeeze fact must render from typed attributes');",
                "const firstKey = standardSignalTooltipCacheKey({ trigger_event: { code: 'first_trigger' }, risk: { code: 'risk_one' } });",
                "const secondKey = standardSignalTooltipCacheKey({ trigger_event: { code: 'second_trigger' }, risk: { code: 'risk_two' } });",
                "check(firstKey !== secondKey, 'nested typed facts must invalidate the tooltip cache');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


