def test_indicator_numeric_zero_survives_settings_manifest_and_request_serialization(
    tmp_path: Path,
) -> None:
    preferences = Path("src/aef_terminal/ui/assets/js/07-preferences.js").read_text(
        encoding="utf-8"
    )
    helper_source = (
        "function numericValueOrFallback"
        + preferences.split("function numericValueOrFallback", 1)[1].split(
            "function storedGlobalIndicatorNumber",
            1,
        )[0]
    )
    script_path = tmp_path / "indicator-zero-numeric-contract.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                helper_source,
                "assert.equal(numericValueOrFallback(0, 42), 0);",
                "assert.equal(numericValueOrFallback('0', 42), 0);",
                "assert.equal(numericValueOrFallback('', 42), 42);",
                "assert.equal(numericValueOrFallback('invalid', 42), 42);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr
    settings_state = Path("src/aef_terminal/ui/assets/js/11-indicator-settings-state.js").read_text(
        encoding="utf-8"
    )
    settings_boot = Path("src/aef_terminal/ui/assets/js/70-settings-boot.js").read_text(
        encoding="utf-8"
    )
    settings_bindings = Path("src/aef_terminal/ui/assets/js/70-settings-bindings.js").read_text(
        encoding="utf-8"
    )
    data_services = Path("src/aef_terminal/ui/assets/js/20-data-services.js").read_text(
        encoding="utf-8"
    )
    manifest_consumers = "\n".join(
        Path(path).read_text(encoding="utf-8")
        for path in (
            "src/aef_terminal/ui/assets/js/11-indicator-settings-state.js",
            "src/aef_terminal/ui/assets/js/20-live-candle-sync.js",
            "src/aef_terminal/ui/assets/js/30-panels-indicator-controls.js",
            "src/aef_terminal/ui/assets/js/48-overlays-manager.js",
            "src/aef_terminal/ui/assets/js/49-overlays-indicators.js",
        )
    )
    assert "managerOrder: numericValueOrFallback(ui.manager_order, 500)" in settings_state
    assert "runtimeOrder: numericValueOrFallback(ui.runtime_order, 500)" in settings_state
    assert "Number(ui.manager_order) || 500" not in manifest_consumers
    assert "Number(spec.ui.manager_order) || 500" not in manifest_consumers
    assert "runtime_order) || 500" not in manifest_consumers
    assert "numericValueOrFallback(state.indicators.globalDefaults.scorePre, 42)" in settings_boot
    assert "numericValueOrFallback(event.target.value, fallback)" in settings_bindings
    assert (
        "global_score_pre: String(clamp(numericValueOrFallback("
        "state.indicators.globalDefaults.scorePre, 42), 0, 99))" in data_services
    )
    assert "Number(state.indicators.globalDefaults.scorePre) || 42" not in data_services


