def test_manual_fib_price_change_uses_first_vertex_as_percentage_base(
    tmp_path: Path,
) -> None:
    js = martincall_js_source()
    signed_source = (
        'function signed(value, suffix = "")'
        + js.split('function signed(value, suffix = "")', 1)[1].split(
            "function escapeHtml",
            1,
        )[0]
    )
    price_change_source = (
        "function drawingPriceChangePct(points)"
        + js.split("function drawingPriceChangePct(points)", 1)[1].split(
            "function drawingLineMeasurementFacts",
            1,
        )[0]
    )
    script_path = tmp_path / "drawing-fib-price-change.js"
    script_path.write_text(
        "\n".join(
            (
                signed_source,
                price_change_source,
                "const points = (first, second) => [{ price: first }, { price: second }];",
                "if (drawingPriceChangePct(points(100, 110)) !== 10) process.exit(1);",
                "if (drawingPriceChangeLabel(points(100, 110)) !== '+10.00%') process.exit(2);",
                "if (drawingPriceChangeLabel(points(100, 90)) !== '-10.00%') process.exit(3);",
                "if (drawingPriceChangeLabel(points(100, 100)) !== '0.00%') process.exit(4);",
                "if (drawingPriceChangeLabel(points(0, 110)) !== '—') process.exit(5);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


