def test_vsa_render_history_setting_filters_elapsed_hours_and_reuses_cache(
    tmp_path: Path,
) -> None:
    js = martincall_js_source()
    render_source = (
        "const VSA_VOLUME_RENDER_HOUR_OPTIONS"
        + js.split("const VSA_VOLUME_RENDER_HOUR_OPTIONS", 1)[1].split(
            "function volumeStructureSeries",
            1,
        )[0]
    )
    script_path = tmp_path / "vsa-render-hours.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = { indicators: { vsaVolume: { renderHours: 6 } } };",
                render_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const base = Date.parse('2026-01-01T00:00:00Z');",
                "const rows = Array.from({ length: 13 }, (_, hour) => ({ ts: new Date(base + hour * 3600000).toISOString(), hour }));",
                "const snapshot = { vsa_volume: { series: rows } };",
                "const six = vsaRenderSourceSeries(snapshot);",
                "check(six.length === 6 && six[0].hour === 7 && six.at(-1).hour === 12, 'default must retain the latest six elapsed hours');",
                "check(vsaRenderSourceSeries(snapshot) === six, 'stable setting must reuse the bounded series cache');",
                "state.indicators.vsaVolume.renderHours = 2;",
                "const two = vsaRenderSourceSeries(snapshot);",
                "check(two !== six && two.length === 2 && two[0].hour === 11, 'two-hour setting must invalidate and narrow the cache');",
                "state.indicators.vsaVolume.renderHours = 12;",
                "const twelve = vsaRenderSourceSeries(snapshot);",
                "check(twelve.length === 12 && twelve[0].hour === 1, 'twelve-hour setting must retain the full elapsed tail without the boundary row');",
                "check(vsaVolumeRenderHours('4') === 4, 'stored enum strings must normalize');",
                "check(vsaVolumeRenderHours('invalid') === 6, 'invalid values must fail to the six-hour default');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


