def test_ny_range_box_and_levels_use_separate_toggles_and_distinct_session_bounds(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    renderer = "function drawOpeningRange" + source.split("function drawOpeningRange", 1)[1]
    script_path = tmp_path / "ny-range-geometry.js"
    script_path.write_text(
        "\n".join(
            (
                "const calls = []; let box = null;",
                "const state = { indicators: { nyRange: { enabled: true, priceLines: true, opacity: 14, style: 'dotted' } }, marketContext: { openingRange: { high: 110, low: 100, mid: 105, startTs: '2026-08-12T13:30:00Z', endTs: '2026-08-12T14:00:00Z', sessionEndTs: '2026-08-12T20:00:00Z' } } };",
                "function css() { return '#4aa3ff'; }",
                "function rgbaFromCssColor(value) { return value; }",
                "function lineDashForStyle() { return [1, 2]; }",
                "function clamp(value, low, high) { return Math.min(Math.max(value, low), high); }",
                "function openingRangeIntersectsVisible(bars, range) { const first = Date.parse(bars[0].ts); const last = Date.parse(bars[bars.length - 1].ts); return Date.parse(range.endTs) >= first && Date.parse(range.startTs) <= last; }",
                "function xForTime(times, timestamp, xStep, x) { for (let i = 1; i < times.length; i += 1) { if (timestamp <= times[i]) { const ratio = (timestamp - times[i - 1]) / (times[i] - times[i - 1]); return x(i - 1) + ratio * (x(i) - x(i - 1)); } } return x(times.length - 1) + ((timestamp - times[times.length - 1]) / (times[times.length - 1] - times[times.length - 2])) * xStep; }",
                "function drawHorizontalLevel(_ctx, _pad, _width, _y, label, _color, _dash, _lineWidth, options) { calls.push({ label, ...options }); }",
                renderer,
                "const bars = [{ ts: '2026-08-12T13:00:00Z' }, { ts: '2026-08-12T14:30:00Z' }, { ts: '2026-08-12T20:30:00Z' }];",
                "const ctx = { save() {}, restore() {}, setLineDash() {}, fillRect(...args) { box = args; }, strokeRect() {} };",
                "drawOpeningRange(ctx, bars, { left: 10, right: 10 }, 400, 300, index => 100 + index * 300, price => price, 910);",
                "if (!box || Math.abs(box[0] - 200) > 0.001 || Math.abs(box[2] - 100) > 0.001) throw new Error(`box geometry ${JSON.stringify(box)}`);",
                "if (calls.length !== 3 || calls.map(item => item.label).join(',') !== 'OR H,OR L,OR M') throw new Error(`level calls ${JSON.stringify(calls)}`);",
                "if (calls.some(item => Math.abs(item.startX - 200) > 0.001 || Math.abs(item.endX - 675) > 0.001)) throw new Error(`line geometry ${JSON.stringify(calls)}`);",
                "state.indicators.nyRange.priceLines = false; calls.length = 0; box = null;",
                "drawOpeningRange(ctx, bars, { left: 10, right: 10 }, 400, 300, index => 100 + index * 300, price => price, 910);",
                "if (!box || calls.length) throw new Error('NY lines toggle must preserve the box and hide only H/L/M');",
                "state.indicators.nyRange.enabled = false; calls.length = 0; box = null;",
                "drawOpeningRange(ctx, bars, { left: 10, right: 10 }, 400, 300, index => 100 + index * 300, price => price, 910);",
                "if (box || calls.length) throw new Error('NY master toggle must disable box and levels');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


