def test_ui_presentation_matrix_and_bbo_freshness_are_behavioral(tmp_path: Path) -> None:
    labels_source = Path("src/aef_terminal/ui/assets/js/06-labels.js").read_text(encoding="utf-8")
    matrix_source = (
        "const UI_PRESENTATION_STATE_MATRIX"
        + labels_source.split("const UI_PRESENTATION_STATE_MATRIX", 1)[1].split(
            "const COMPACT_LABELS", 1
        )[0]
    )
    drive_source = Path("src/aef_terminal/ui/assets/js/17-option-drive-runtime.js").read_text(
        encoding="utf-8"
    )
    bbo_source = (
        "function optionDriveLiveBbo"
        + drive_source.split("function optionDriveLiveBbo", 1)[1].split(
            "function optionDriveQuotePresentationState", 1
        )[0]
    )
    script_path = tmp_path / "presentation-state-matrix.js"
    script_path.write_text(
        "\n".join(
            (
                "const state = {};",
                "function effectiveDataQuality() { return {}; }",
                "function makeNode() { return {",
                "  textContent: '', title: '', dataset: {}, attributes: {}, children: [],",
                "  setAttribute(key, value) { this.attributes[key] = value; },",
                "  replaceChildren() { this.children = []; },",
                "  appendChild(value) { this.children.push(value); },",
                "}; }",
                "const document = { createElement() { return makeNode(); } };",
                matrix_source,
                bbo_source,
                "const status = makeNode();",
                "const descriptor = applyUiPresentationState(status, 'delayed_frozen');",
                "const execution = makeNode();",
                "renderExecutionEligibility(execution, 'blocked', [",
                "  { label: 'ROUTE', state: 'ready' },",
                "  { label: 'BBO', state: 'stale' },",
                "]);",
                "const now = Date.parse('2026-08-12T12:00:00Z');",
                "const exact = {",
                "  bid: 10, ask: 11, market_data_entitlement: 'live', is_delayed: false,",
                "  bid_ask_received_at: new Date(now - 9999).toISOString(),",
                "};",
                "console.log(JSON.stringify({",
                "  descriptor, status,",
                "  action: execution.children[0]?.textContent,",
                "  facts: execution.children.slice(1).map(node => node.textContent),",
                "  fresh: Boolean(optionDriveLiveBbo(exact, now)),",
                "  stale: Boolean(optionDriveLiveBbo({ ...exact, bid_ask_received_at: new Date(now - 10001).toISOString() }, now)),",
                "  delayed: Boolean(optionDriveLiveBbo({ ...exact, is_delayed: true }, now)),",
                "}));",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload["descriptor"]["state"] == "delayed_frozen"
    assert payload["descriptor"]["kind"] == "stale"
    assert payload["status"]["textContent"] == "DELAYED/FROZEN"
    assert payload["status"]["attributes"]["aria-busy"] == "false"
