def test_typed_ui_notices_preserve_owner_priority_and_route_generation(tmp_path: Path) -> None:
    feedback_source = Path("src/aef_terminal/ui/assets/js/12-ui-feedback.js").read_text(
        encoding="utf-8"
    )
    notice_source = (
        "const UI_NOTICE_PRIORITY"
        + feedback_source.split("const UI_NOTICE_PRIORITY", 1)[1].split(
            "function uiFeedbackEventKey", 1
        )[0]
    )
    script_path = tmp_path / "typed-ui-notices.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const state = { instrumentId: 'instrument-a', timeframe: '5m', notices: Object.create(null), noticeSequence: 0 };",
                "let currentRoute = 'route-a';",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function instrumentRouteFingerprint() { return currentRoute; }",
                "function uiPresentationStateDescriptor(value) { const requestedState = String(value || 'unknown'); const kinds = { error: 'error', blocked: 'error', armed: 'attention', stale: 'stale', degraded: 'degraded', loading: 'loading', empty: 'empty', sleeping: 'disabled', ready: 'ready' }; return { state: requestedState, kind: kinds[requestedState] || 'degraded' }; }",
                notice_source,
                "setUiNotice('storage', 'STORAGE_FAILED', 'storage failed', { state: 'error', routeScoped: false });",
                "setUiNotice('screener', 'SCREENER_FAILED', 'screener failed', { state: 'error', routeScoped: false });",
                "assert.equal(uiNoticeMessage(), 'screener failed');",
                "clearUiNotice('storage');",
                "assert.equal(uiNoticeMessage(), 'screener failed');",
                "setUiNotice('market', 'ROUTE_STALE', 'route-a stale', { state: 'stale' });",
                "clearUiNotice('screener');",
                "assert.equal(uiNoticeMessage(), 'route-a stale');",
                "currentRoute = 'route-b';",
                "assert.equal(uiNoticeMessage(), '');",
                "setUiNotice('market', 'ROUTE_READY', 'route-b ready', { state: 'ready' });",
                "setUiNotice('history', 'HISTORY_LOADING', 'loading history', { state: 'loading' });",
                "assert.equal(activeUiNotice().owner, 'history');",
                "clearUiNotices({ routeScopedOnly: true });",
                "assert.equal(uiNoticeMessage(), '');",
                "setUiNotice('system', 'SLEEPING', 'sleeping', { state: 'sleeping', routeScoped: false });",
                "setUiNotice('orders', 'ARMED', 'armed', { state: 'armed', routeScoped: false });",
                "assert.equal(activeUiNotice().owner, 'orders');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


