def test_option_target_toggles_reload_after_server_settings_hydration(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/11-indicator-settings-state.js").read_text(
        encoding="utf-8"
    )
    reload_source = (
        "state.indicators.optionTargets.enabled"
        + source.split("state.indicators.optionTargets.enabled", 1)[1].split(
            "state.indicators.gexContext.enabled",
            1,
        )[0]
    )
    script_path = tmp_path / "option-target-settings-hydration.js"
    script_path.write_text(
        "\n".join(
            (
                "const calls = [];",
                "const values = new Map([",
                "  ['optionTargetsEnabled', 'false'],",
                "  ['optionTargetsFastStatus', 'false'],",
                "  ['optionTargetsPulse', 'false'],",
                "]);",
                "const state = { instrumentId: 'instrument-es', indicators: { optionTargets: { enabled: true, fastStatus: true, pulse: true } } };",
                "function storedInstrumentIndicatorBool(key, fallback, instrumentId) {",
                "  calls.push([key, instrumentId]);",
                "  const value = instrumentId === 'instrument-es' ? values.get(key) : undefined;",
                "  return value === undefined ? fallback : value !== 'false';",
                "}",
                "function reload() {",
                reload_source,
                "}",
                "reload();",
                "console.log(JSON.stringify({ optionTargets: state.indicators.optionTargets, calls }));",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr
    payload = json.loads(result.stdout)
    assert payload["optionTargets"] == {
        "enabled": False,
        "fastStatus": False,
        "pulse": False,
    }
    assert payload["calls"] == [
        ["optionTargetsEnabled", "instrument-es"],
        ["optionTargetsFastStatus", "instrument-es"],
        ["optionTargetsPulse", "instrument-es"],
    ]


