def test_impulse_overlay_filter_obeys_patterns_labels_zones_pb_and_style(tmp_path: Path) -> None:
    client_source = Path("src/aef_terminal/indicators/modules/impulse_fib/client.js").read_text(
        encoding="utf-8"
    )
    script_path = tmp_path / "impulse-overlay-filter.js"
    script_path.write_text(
        "\n".join(
            (
                "const assert = require('node:assert/strict');",
                "let filter;",
                "function registerIndicatorOverlayFilter(_id, callback) { filter = callback; }",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function rgbaFromCssColor(_color, alpha) { return `rgba:${alpha}`; }",
                "function themeColor() { return '#fff'; }",
                client_source,
                "const hidden = { style: 'both', zones: false, patterns: false, labels: false, pbZones: false, zoneOpacity: 10 };",
                "assert.deepEqual(filter({ type: 'box', role: 'impulse_zone', has_trade_plan: true }, hidden), []);",
                "assert.deepEqual(filter({ type: 'line', role: 'impulse_zone', has_trade_plan: true }, hidden), []);",
                "assert.deepEqual(filter({ type: 'label', role: 'impulse_fib', has_trade_plan: true }, hidden), []);",
                "assert.deepEqual(filter({ type: 'box', role: 'pullback_zone', has_trade_plan: true }, hidden), []);",
                "assert.deepEqual(filter({ type: 'line', role: 'continuation_pattern', control_key: 'patterns' }, hidden), []);",
                "assert.equal(filter({ type: 'line', role: 'entry' }, hidden).length, 1);",
                "assert.equal(filter({ type: 'line', role: 'continuation_pattern', control_key: 'patterns' }, { ...hidden, style: 'minimal', patterns: true }).length, 1);",
                "const linesOnly = { ...hidden, zones: true, style: 'lines' };",
                "assert.deepEqual(filter({ type: 'box', role: 'impulse_zone' }, linesOnly), []);",
                "assert.equal(filter({ type: 'line', role: 'impulse_zone' }, linesOnly).length, 1);",
                "assert.equal(filter({ type: 'label', role: 'impulse_fib' }, { ...hidden, labels: true }).length, 1);",
                "assert.equal(filter({ type: 'box', role: 'pullback_zone' }, { ...hidden, pbZones: true }).length, 1);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_overlay_manager_preflight_reports_invalid_geometry_and_orphan_markers(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/48-overlays-manager.js").read_text(
        encoding="utf-8"
    )
    helper_source = (
        "function managedOverlayFiniteNumber"
        + source.split("function managedOverlayFiniteNumber", 1)[1].split(
            "class OverlayManager",
            1,
        )[0]
    )
    script_path = tmp_path / "overlay-preflight.js"
    script_path.write_text(
        "\n".join(
            (
                "const assert = require('node:assert/strict');",
                "function timestampKey(value) { return String(value || ''); }",
                helper_source,
                "const ts = '2026-01-01T14:30:00+00:00';",
                "const snapshot = { bars: [{ ts }, { ts: '2026-01-01T14:32:00+00:00' }] };",
                "assert.equal(managedOverlayPreflightReason({ type: 'box', start_ts: ts, end_ts: ts, top: 101, bottom: 99 }, snapshot), '');",
                "assert.equal(managedOverlayPreflightReason({ type: 'box', start_ts: 'bad', end_ts: ts, top: 101, bottom: 99 }, snapshot), 'invalid_start_timestamp');",
                "assert.equal(managedOverlayPreflightReason({ type: 'box', start_ts: '2026-01-01 14:30:00', end_ts: ts, top: 101, bottom: 99 }, snapshot), 'invalid_start_timestamp');",
                "assert.equal(managedOverlayPreflightReason({ type: 'line', start_ts: ts, end_ts: ts, price: null }, snapshot), 'invalid_line_price');",
                "assert.equal(managedOverlayPreflightReason({ type: 'marker', ts, price: 100, code: 'OK' }, snapshot), '');",
                "assert.equal(managedOverlayPreflightReason({ type: 'marker', ts, price: 100, lines: ['  '] }, snapshot), 'empty_marker_content');",
                "assert.equal(managedOverlayPreflightReason({ type: 'label', ts, price: 100, label: '  ' }, snapshot), 'empty_label_content');",
                "assert.equal(managedOverlayPreflightReason({ type: 'marker', ts: '2026-01-01T14:31:00+00:00', price: 100, code: 'BAD' }, snapshot), 'orphan_timestamp');",
                "assert.equal(managedOverlayPreflightReason({ type: 'marker', ts: '2026-01-01T14:29:00+00:00', price: 100, code: 'OLD' }, snapshot), 'outside_axis');",
                "snapshot.bars[1].ts = '2026-01-01T14:31:00+00:00';",
                "assert.equal(managedOverlayPreflightReason({ type: 'marker', ts: '2026-01-01T14:31:00+00:00', price: 100, code: 'FIXED' }, snapshot), '');",
                "assert.equal(managedOverlayPreflightReason({ type: 'marker', ts: '2026-01-01T14:32:00+00:00', price: 100, code: 'STALE' }, snapshot), 'outside_axis');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


