def test_invalid_drawing_objects_are_highlighted_in_object_manager(tmp_path: Path) -> None:
    js = martincall_js_source()
    css = Path("src/aef_terminal/ui/assets/css/40-overlays-alerts.css").read_text(encoding="utf-8")
    constants = Path("src/aef_terminal/ui/assets/js/04-constants.js").read_text(encoding="utf-8")
