def test_gex_compact_current_volume_label_is_not_gated_by_material(tmp_path: Path) -> None:
    source = gex_context_js_source()
    compact_source = (
        "function gexOptionVolumeCompactLabel(row)"
        + source.split(
            "function gexOptionVolumeCompactLabel(row)",
            1,
        )[1].split("function gexOptionVolumeFrameMs(row)", 1)[0]
    )
    script_path = tmp_path / "gex-current-volume-label.js"
    script_path.write_text(
        "\n".join(
            (
                "function gexOptionVolumeSection(row, section) { return row.option_volume_context?.[section] || null; }",
                "function gexOptionVolumeNumber(row, section, key) { const value = gexOptionVolumeSection(row, section)?.[key]; return Number.isFinite(Number(value)) ? Number(value) : null; }",
                "function gexOptionVolumeInteractionLabel() { return ''; }",
                compact_source,
                "const rows = [0.1782, 0.8665, 1.1476].map(turnover => ({ option_volume_context: { current: { turnover, material: false }, event: null } }));",
                "const labels = rows.map(gexOptionVolumeCompactLabel);",
                "if (JSON.stringify(labels) !== JSON.stringify(['VOL 0.18×', 'VOL 0.87×', 'VOL 1.15×'])) process.exit(2);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


