def test_focus_signal_density_keeps_latest_typed_signal_per_source(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicator-labels.js").read_text(
        encoding="utf-8"
    )
    density_source = (
        "function overlayActionTier"
        + source.split("function overlayActionTier", 1)[1].split(
            "function drawStackedTextMark",
            1,
        )[0]
    )
    script_path = tmp_path / "focus-signal-density.js"
    script_path.write_text(
        "\n".join(
            (
                "let density = 'focus';",
                "const state = { snapshot: { bars: [] } };",
                "function timestampKey(value) { return String(value || '').replace('.000Z', 'Z'); }",
                "function overlayTimestampKeys(item) { return [item?.ts].map(timestampKey).filter(Boolean); }",
                "function advisorLatestBarTs(bars) { return bars.length ? timestampKey(bars[bars.length - 1].ts) : ''; }",
                "function advisorEffectiveSignalDensity() { return density; }",
                "function isLifecycleExecutionMarker(item) { return item?.role === 'entry_fill'; }",
                "function allowLifecycleExecutionMarkerByDensity() { return density === 'research'; }",
                "function activeIndicatorLifecycle(snapshot) { return snapshot?.lifecycle?.active ? snapshot.lifecycle : null; }",
                density_source,
                "const bars = [",
                "  { ts: '2026-08-14T10:00:00.000Z' },",
                "  { ts: '2026-08-14T10:05:00.000Z' },",
                "  { ts: '2026-08-14T10:10:00.000Z' },",
                "];",
                "const alphaOld = { type: 'label', source: 'alpha', ts: bars[0].ts, signal_overlay: true };",
                "const alphaLatest = { type: 'label', source: 'alpha', ts: bars[1].ts, signal_overlay: true };",
                "const betaLatest = { type: 'marker', source: 'beta', ts: bars[0].ts, signal_overlay: true };",
                "const currentPlan = { type: 'label', source: 'plan', ts: bars[2].ts, role: 'entry' };",
                "const context = { type: 'label', source: 'context', ts: bars[0].ts, code: 'CTX' };",
                "const items = [alphaOld, alphaLatest, betaLatest, currentPlan, context];",
                "const latest = latestIndicatorSignalOverlays(items);",
                "const allow = item => allowOverlayLabelByDensity(item, bars, { bars }, latest);",
                "if (allow(alphaOld)) throw new Error('focus retained an older signal from the same source');",
                "if (!allow(alphaLatest)) throw new Error('focus dropped the latest alpha signal');",
                "if (!allow(betaLatest)) throw new Error('focus dropped an older-bar latest beta signal');",
                "if (!allow(currentPlan)) throw new Error('focus dropped the current plan label');",
                "if (allow(context)) throw new Error('focus retained historical context');",
                "density = 'minimal';",
                "if (allow(alphaLatest) || allow(betaLatest)) throw new Error('minimal retained indicator signals');",
                "const command = { type: 'label', ts: bars[0].ts, action_card: { tier: 'command' } };",
                "if (!allowOverlayLabelByDensity(command, bars, { bars }, latest)) throw new Error('minimal dropped command tier');",
                "density = 'research';",
                "if (!allow(context) || !allow(alphaOld)) throw new Error('research did not retain full history');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


