def test_gex_scheduler_api_rejection_reconciles_toggle_and_shows_error(tmp_path: Path) -> None:
    _run_gex_scheduler_binding_scenario(tmp_path, "rejection")


def test_option_reversal_fast_projection_has_independent_exact_scope_reducer(
    tmp_path: Path,
) -> None:
    js = martincall_js_source()
    worker = Path("src/aef_terminal/ui/assets/workers/quote-stream-shared-worker.js").read_text(
        encoding="utf-8"
    )

    assert '"fast_indicators_snapshot"' in js
    assert "function applyFastIndicatorSnapshots(scopes, options = {})" in js
    assert "function applyFastIndicatorProjectionToSnapshot(snapshot, options = {})" in js
    assert 'indicator.execution?.lane === "fast"' in js
    assert 'indicator.execution?.authority === "advisory_only"' in js
    assert "fast indicator scope revision regressed" in js
    assert "barCanonicalGeneration" in js
    assert "bar_canonical_generation" in worker
    assert "const seenScopeKeys = new Set();" in js
    assert "const missingRouteKeys = new Set();" in js
    assert "primaryOptionReversalByScope: {}" in js
    assert "applyFastIndicatorProjectionToSnapshot(mergedSnapshot, { primarySnapshot: true })" in js
    assert "state.snapshot = applyFastIndicatorProjectionToSnapshot(state.snapshot);" in js
    assert '"fast_indicators_snapshot"' in worker
    assert "function quoteValidatedFastIndicatorScopes(group, scopes)" in worker
    assert "message.fast_indicators = group.state.fastIndicators" in worker

    option_target_source = Path("src/aef_terminal/ui/assets/js/59-option-targets.js").read_text(
        encoding="utf-8"
    )
    reducer_source = (
        "function optionTargetScopeKey"
        + option_target_source.split("function optionTargetScopeKey", 1)[1].split(
            "function applyFastIndicatorSnapshots",
            1,
        )[0]
    )
    script_path = tmp_path / "fast-option-reversal-primary-fallback.js"
    script_path.write_text(
        "\n".join(
            (
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function instrumentRouteFingerprint() { return 'route-1'; }",
                "const state = { instrumentId: 'instrument-1', timeframe: '5m', snapshot: null, fastIndicators: { aggregateByScope: {}, revisionsByScope: {}, optionReversalByTargetIdentity: {}, primaryOptionReversalByScope: {} } };",
                reducer_source,
                "const primary = { latest: { state: 'WAIT' }, execution: { lane: 'primary' } };",
                "const fast = { latest: { state: 'REVERSAL' }, execution: { lane: 'fast', authority: 'advisory_only', trigger: 'option_target_sample' } };",
                "const scopeKey = fastIndicatorScopeKey(state.instrumentId, instrumentRouteFingerprint(), state.timeframe);",
                "state.snapshot = applyFastIndicatorProjectionToSnapshot({ indicators: { option_reversal: primary } }, { primarySnapshot: true });",
                "if (state.snapshot.indicators.option_reversal !== primary) process.exit(1);",
                "state.fastIndicators.aggregateByScope[scopeKey] = { revision: 1, indicator: fast };",
                "state.fastIndicators.revisionsByScope[scopeKey] = 1;",
                "state.snapshot = applyFastIndicatorProjectionToSnapshot(state.snapshot);",
                "if (state.snapshot.indicators.option_reversal !== fast) process.exit(2);",
                "clearFastIndicatorSnapshotsForRoutes(new Set([JSON.stringify([state.instrumentId, instrumentRouteFingerprint()])]), state.timeframe);",
                "if (state.snapshot.indicators.option_reversal !== primary) process.exit(3);",
                "if (state.fastIndicators.primaryOptionReversalByScope[scopeKey] !== primary) process.exit(4);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


