def test_boot_hydrates_server_settings_before_instruments_and_route_storage() -> None:
    js = martincall_js_source()
    boot_body = js.split("async function boot()", 1)[1].split("function startHeartbeat", 1)[0]

    assert boot_body.index("await loadProviders();") < boot_body.index(
        "await loadServerSettings();"
    )
    for binding in (
        "setupInstrumentList();",
        "setupWatchlistControls();",
        "setupPaperTradingControls();",
        "setupSettings();",
    ):
        assert boot_body.index("await loadServerSettings();") < boot_body.index(binding)
    assert boot_body.index("await loadServerSettings();") < boot_body.index(
        "await loadInstruments({ activate: false });"
    )
    assert boot_body.index("await loadInstruments({ activate: false });") < boot_body.index(
        "await loadServerStorage();"
    )
    assert boot_body.index("await loadServerStorage();") < boot_body.index(
        "activateLoadedWatchlistRuntime();"
    )
    assert boot_body.index("activateLoadedWatchlistRuntime();") < boot_body.index(
        "const initialMarketLoad = instrumentForId()"
    )


