def test_option_drift_and_discord_reads_are_fenced_by_generation_calc_and_scope(
    tmp_path: Path,
) -> None:
    option_source = Path("src/aef_terminal/indicators/modules/option_drift/client.js").read_text(
        encoding="utf-8"
    )
    option_sync_source = (
        "const optionDriftState"
        + option_source.split("const optionDriftState", 1)[1].split(
            "function optionDriftMoney",
            1,
        )[0]
    )
    discord_source = Path(
        "src/aef_terminal/indicators/modules/discord_signals/client.js"
    ).read_text(encoding="utf-8")
    discord_sync_source = (
        "const discordSignalsFeedState"
        + discord_source.split("const discordSignalsFeedState", 1)[1].split(
            "function discordSignalsEventControlKey",
            1,
        )[0]
    )
    script_path = tmp_path / "indicator-read-generation-fences.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "const requests = [];",
                "function fetchJson(url, options = {}) {",
                "  let resolveRequest; let rejectRequest;",
                "  const promise = new Promise((resolve, reject) => { resolveRequest = resolve; rejectRequest = reject; });",
                "  const entry = { url, signal: options.signal, resolve: resolveRequest, reject: rejectRequest };",
                "  options.signal?.addEventListener('abort', () => rejectRequest(new DOMException('aborted', 'AbortError')), { once: true });",
                "  requests.push(entry);",
                "  return promise;",
                "}",
                "let calc = { option_drift: true, discord_signals: true };",
                "function indicatorCalcForId(id) { return calc[id]; }",
                "function exactIdentityText(value) { return String(value || ''); }",
                "function instrumentRouteFingerprint() { return state.snapshot.meta.route_fingerprint; }",
                "function requestErrorMessage(error) { return error.message; }",
                "function bumpChartRenderVersion() {} function renderCharts() {}",
                "function refreshIndicatorSettingsStatusBadges() {}",
                "let state = { instrumentId: 'A', timeframe: '5m', indicators: { optionDrift: { captureMode: 'live' } }, snapshot: { meta: { instrument_id: 'A', route_fingerprint: 'route-A', timeframe: '5m' }, bars: [{ ts: '2026-08-23T10:00:00Z' }] } };",
                option_sync_source,
                discord_sync_source,
                "(async () => {",
                "  const optionOffRead = syncOptionDrift({ force: true });",
                "  const optionOffRequest = requests.at(-1);",
                "  calc.option_drift = false;",
                "  await syncOptionDrift();",
                "  await optionOffRead;",
                "  assert.equal(optionOffRequest.signal.aborted, true);",
                "  assert.equal(optionDriftState.payload, null);",
                "  assert.equal(optionDriftState.loading, false);",
                "  calc.option_drift = true;",
                "  state.snapshot = { meta: { instrument_id: 'A', route_fingerprint: 'route-A', timeframe: '5m' }, bars: [{ ts: '2026-08-23T10:00:00Z' }] };",
                "  const staleOptionRead = syncOptionDrift({ force: true });",
                "  const staleOptionRequest = requests.at(-1);",
                "  state.instrumentId = 'B';",
                "  state.snapshot = { meta: { instrument_id: 'B', route_fingerprint: 'route-B', timeframe: '5m' }, bars: [{ ts: '2026-08-23T10:05:00Z' }] };",
                "  const currentOptionRead = syncOptionDrift({ force: true });",
                "  const currentOptionRequest = requests.at(-1);",
                "  assert.equal(staleOptionRequest.signal.aborted, true);",
                "  currentOptionRequest.resolve({ ok: true, advisory_only: true, decision_eligible: false, instrument_id: 'B', route_fingerprint: 'route-B', capture_mode: 'live' });",
                "  await Promise.all([staleOptionRead, currentOptionRead]);",
                "  assert.equal(optionDriftState.payload.instrument_id, 'B');",
                "  state.instrumentId = 'A';",
                "  state.snapshot = { meta: { instrument_id: 'A', route_fingerprint: 'route-A', timeframe: '5m' }, bars: [{ ts: '2026-08-23T10:00:00Z' }] };",
                "  const discordOffRead = syncDiscordSignalsFeed({ force: true });",
                "  const discordOffStatus = requests.at(-1);",
                "  calc.discord_signals = false;",
                "  await syncDiscordSignalsFeed();",
                "  await discordOffRead;",
                "  assert.equal(discordOffStatus.signal.aborted, true);",
                "  assert.equal(requests.filter(item => item.url.includes('/feed?')).length, 0);",
                "  assert.equal(discordSignalsFeedState.payload, null);",
                "  calc.discord_signals = true;",
                "  const staleDiscordRead = syncDiscordSignalsFeed({ force: true });",
                "  const staleDiscordStatus = requests.at(-1);",
                "  state.instrumentId = 'B';",
                "  state.snapshot = { meta: { instrument_id: 'B', route_fingerprint: 'route-B', timeframe: '5m' }, bars: [{ ts: '2026-08-23T10:05:00Z' }] };",
                "  const currentDiscordRead = syncDiscordSignalsFeed({ force: true });",
                "  const currentDiscordStatus = requests.at(-1);",
                "  assert.equal(staleDiscordStatus.signal.aborted, true);",
                "  currentDiscordStatus.resolve({ ok: true, configured: true, gate: { active: true } });",
                "  await new Promise(resolve => setImmediate(resolve));",
                "  const currentDiscordFeed = requests.at(-1);",
                "  assert.match(currentDiscordFeed.url, /instrument_id=B/);",
                "  currentDiscordFeed.resolve({ ok: true, instrument_id: 'B', route_fingerprint: 'route-B', timeframe: '5m' });",
                "  await Promise.all([staleDiscordRead, currentDiscordRead]);",
                "  assert.equal(discordSignalsFeedState.payload.instrument_id, 'B');",
                "})().catch(error => { console.error(error); process.exitCode = 1; });",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


def test_chart_events_map_to_containing_bar_without_crossing_gaps(tmp_path: Path) -> None:
    core_source = Path("src/aef_terminal/ui/assets/js/40-chart-core.js").read_text(encoding="utf-8")
    containing_bar_source = (
        "function chartBarIndexForEventTimestamp"
        + core_source.split("function chartBarIndexForEventTimestamp", 1)[1].split(
            "function overlayRangeOutsidePlot",
            1,
        )[0]
    )
    paper_source = Path("src/aef_terminal/ui/assets/js/18-paper-trading.js").read_text(
        encoding="utf-8"
    )
    paper_index_source = (
        "function paperFillBarIndex"
        + paper_source.split("function paperFillBarIndex", 1)[1].split(
            "function paperTradeEntryLineStartX",
            1,
        )[0]
    )
    discord_source = Path(
        "src/aef_terminal/indicators/modules/discord_signals/client.js"
    ).read_text(encoding="utf-8")
    discord_anchor_source = (
        "function discordSignalsAnchorBar"
        + discord_source.split("function discordSignalsAnchorBar", 1)[1].split(
            "function discordSignalsContractText",
            1,
        )[0]
    )
    tick_source = Path("src/aef_terminal/indicators/modules/tick_flow/overlays.js").read_text(
        encoding="utf-8"
    )
    tick_bucket_source = (
        "function tickVisibleBarsKey"
        + tick_source.split("function tickVisibleBarsKey", 1)[1].split(
            "function recentTickDeltaSummary",
            1,
        )[0]
    )
    script_path = tmp_path / "chart-event-containing-bar.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                "function intervalMsFromState() { return 300000; }",
                containing_bar_source,
                paper_index_source,
                discord_anchor_source,
                "const bars = [",
                "  { ts: '2026-08-23T16:20:00.000Z' },",
                "  { ts: '2026-08-23T16:25:00.000Z' },",
                "  { ts: '2026-08-23T16:35:00.000Z' },",
                "];",
                "const fillTs = '2026-08-23T16:23:45.004680Z';",
                "assert.equal(chartBarIndexForEventTimestamp(bars, Date.parse(fillTs)), 0);",
                "assert.equal(paperFillBarIndex({ filled_at: fillTs }, bars), 0);",
                "assert.equal(discordSignalsAnchorBar(fillTs, bars), bars[0]);",
                "assert.equal(chartBarIndexForEventTimestamp(bars, Date.parse('2026-08-23T16:25:00Z')), 1);",
                "assert.equal(chartBarIndexForEventTimestamp(bars, Date.parse('2026-08-23T16:29:59.999Z')), 1);",
                "assert.equal(chartBarIndexForEventTimestamp(bars, Date.parse('2026-08-23T16:30:00Z')), -1);",
                "assert.equal(discordSignalsAnchorBar('2026-08-23T16:34:59Z', bars), null);",
                "assert.equal(chartBarIndexForEventTimestamp(bars, Date.parse('2026-08-23T16:35:00Z')), 2);",
                "assert.equal(chartBarIndexForEventTimestamp(bars, Date.parse('2026-08-23T16:40:00Z')), -1);",
                "assert.equal(chartBarIndexForEventTimestamp([{ ts: 'bad' }], Date.parse(fillTs)), -1);",
                "let tickVisibleDeltaCacheKey = '';",
                "let tickVisibleDeltaCache = null;",
                "const state = { tickContext: { delta: [",
                "  { ts: fillTs, total_volume: 1, net_delta: 1, trade_count: 1 },",
                "  { ts: '2026-08-23T16:30:00Z', total_volume: 9, net_delta: 9, trade_count: 9 },",
                "  { ts: '2026-08-23T16:36:00Z', total_volume: 2, net_delta: -2, trade_count: 2 },",
                "] } };",
                "function genericOverlayLookupForVisible(_visible, visibleBars) {",
                "  return { times: visibleBars.map(bar => Date.parse(bar.ts)) };",
                "}",
                tick_bucket_source,
                "const buckets = tickDeltaByVisibleBars(bars);",
                "assert.deepEqual(buckets.map(item => item.total_volume), [1, 0, 2]);",
                "assert.deepEqual(buckets.map(item => item.trade_count), [1, 0, 2]);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


