def test_gex_profile_geometry_is_price_anchored_and_clips_offscreen_rows(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/ui/assets/js/50-overlays-gex-profile.js").read_text(
        encoding="utf-8"
    )
    geometry_source = (
        "function gexProfileGeometryRows"
        + source.split(
            "function gexProfileGeometryRows",
            1,
        )[1].split("function gexProfileRowMagnitude", 1)[0]
    )
    script_path = tmp_path / "gex-profile-price-geometry.js"
    script_path.write_text(
        "\n".join(
            (
                "function gexNullableNumber(value) { return typeof value === 'number' && Number.isFinite(value) ? value : null; }",
                "function clamp(value, low, high) { return Math.max(low, Math.min(high, value)); }",
                "function gexProfileRowMagnitude(row) { return Math.abs(gexNullableNumber(row?.abs_gex) ?? 0); }",
                "function gexLevelStrengthValue(row) { return gexNullableNumber(row?.strength); }",
                "function gexNumericStrikeKey(value) { return gexNullableNumber(value); }",
                "const GEX_EXPIRY_PROFILE_LANE_GAP = 30;",
                geometry_source,
                f"const sourceIncludesScreenLayout = {str('gexProfileCollisionLayout' in source).lower()};",
                "const input = [",
                "  { price: 80, strength: 1, abs_gex: 100 },",
                "  { price: 79, strength: 0.8, abs_gex: 80 },",
                "  { price: 200, strength: 0.6, abs_gex: 60 },",
                "  { price: -50, strength: 0, abs_gex: 0 },",
                "];",
                "const pad = { top: 10 };",
                "const first = gexProfileGeometryRows(input, price => 100 - price, pad, 100, { includeEmpty: true });",
                "const shifted = gexProfileGeometryRows(input, price => 160 - price, pad, 100, { includeEmpty: true });",
                "if (first.length !== 2 || shifted.length !== 2) process.exit(2);",
                "if (first[0].strike !== 80 || first[0].profile_y !== 20) process.exit(3);",
                "if (first[1].strike !== 79 || first[1].profile_y !== 21) process.exit(4);",
                "if (shifted[0].profile_y - first[0].profile_y !== 60) process.exit(5);",
                "if (shifted[1].profile_y - first[1].profile_y !== 60) process.exit(6);",
                "if (first.some(row => row.strike === 200 || row.strike === -50)) process.exit(7);",
                "if (sourceIncludesScreenLayout) process.exit(8);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert "includeOffscreen" not in source
    assert "display_y" not in source
    assert result.returncode == 0, result.stderr


