def test_indicator_table_tooltip_reuses_typed_cell_renderer_without_object_leakage(
    tmp_path: Path,
) -> None:
    overlay_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    tooltip_source = Path("src/aef_terminal/ui/assets/js/39-tooltip-content.js").read_text(
        encoding="utf-8"
    )
    cell_source = (
        'const INDICATOR_TABLE_INVALID_CELL_TEXT = "N/A";'
        + overlay_source.split('const INDICATOR_TABLE_INVALID_CELL_TEXT = "N/A";', 1)[1].split(
            "function drawGenericIndicatorTable",
            1,
        )[0]
    )
    standard_table_source = (
        "function standardTableTooltip"
        + tooltip_source.split("function standardTableTooltip", 1)[1]
    )
    script_path = tmp_path / "indicator-table-typed-tooltip.js"
    script_path.write_text(
        "\n".join(
            (
                'const assert = require("node:assert/strict");',
                cell_source,
                "const standardTableTooltipCache = new Map();",
                "function resetStandardTooltipCachesIfNeeded() {}",
                "function compactTooltipCacheValue(value) { return JSON.stringify(value); }",
                "function normalizedSignalSource(value, fallback) { return String(value || fallback).toUpperCase(); }",
                "function tooltipLine(text, role = '', tokenRoles = null) { return { text: String(text), role, token_roles: tokenRoles || {} }; }",
                "function tooltipTokenRoles() { return {}; }",
                "function tooltipLabeledLine(label, value, role = 'meta') { return tooltipLine(`${label}: ${value}`, role); }",
                "function tooltipTypedTokenRole() { return ''; }",
                "function tooltipDirectionTokenRole() { return ''; }",
                "function signalDirectionLabel() { return ''; }",
                "function structuredTradePlan() { return null; }",
                "function formatPlanNumber() { return ''; }",
                "function typedTooltipContextLines() { return []; }",
                "function typedTooltipSections() { return []; }",
                "function typedTooltipTables() { return []; }",
                "function serviceTooltipLines() { return []; }",
                "function tooltipLineText(line) { return String(line?.text ?? line ?? ''); }",
                "function tooltipLineKey(line) { return tooltipLineText(line).toLowerCase(); }",
                standard_table_source,
                "const overlay = { source: 'absorption_trap', table: { id: 'absorption_trap' } };",
                "const typedColumn = { cells: ['PLAN', { kind: 'price', prefix: 'E ', value: 101.25, digits: 2 }, { parts: [{ kind: 'price', prefix: 'S ', value: 99.5, digits: 1 }, { kind: 'price', prefix: 'T ', value: 104.75, digits: 2 }], separator: ' / ' }] };",
                "const typed = standardTableTooltip(overlay, typedColumn).lines.map(tooltipLineText);",
                "assert(typed.includes('Value: E 101.25'));",
                "assert(typed.includes('Context: S 99.5 / T 104.75'));",
                "assert(!typed.join(' ').includes('[object Object]'));",
                "const malformed = standardTableTooltip(overlay, { cells: ['PLAN', { value: { code: 'raw_object' } }, 'still renders'] }).lines.map(tooltipLineText);",
                "assert(malformed.includes('Value: N/A'));",
                "assert(malformed.includes('Context: still renders'));",
                "assert(!malformed.join(' ').includes('[object Object]'));",
                "const afterMalformed = standardTableTooltip(overlay, { cells: ['NEXT', { kind: 'integer', value: 0 }, 'OK'] }).lines.map(tooltipLineText);",
                "assert(afterMalformed.includes('Value: 0') && afterMalformed.includes('Context: OK'));",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_indicator_table_typed_tooltip_sections_are_bounded_and_role_safe(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/39-tooltip-content.js").read_text(encoding="utf-8")
    section_source = (
        "function tooltipSectionLine"
        + source.split("function tooltipSectionLine", 1)[1].split(
            "function normalizedTypedDirection",
            1,
        )[0]
    )
    script = tmp_path / "typed-tooltip-sections.js"
    script.write_text(
        "\n".join(
            (
                "function tooltipTextValue(value) { return String(value ?? '').trim(); }",
                "function tooltipLine(text, role = '', tokenRoles = null) { const line = { text: String(text ?? ''), role }; if (tokenRoles) line.token_roles = { ...tokenRoles }; return line; }",
                "function tooltipLineText(line) { return line && typeof line === 'object' ? String(line.text ?? '') : String(line ?? ''); }",
                "function tooltipTypedTokenRole(value) { const roles = new Set(['call', 'put', 'type', 'strength', 'positive', 'negative', 'warning', 'muted']); const role = String(value || '').toLowerCase(); return roles.has(role) ? role : ''; }",
                "function indicatorFactsForDisplay(value) { return value; }",
                section_source,
                "function check(value, message) { if (!value) throw new Error(message); }",
                "const tableSection = { title: 'THEORY · TABLE', lines: [{ text: 'CALL + / PUT +', role: 'flow', token_roles: { CALL: 'call', PUT: 'put', BAD: 'script' } }] };",
                "const directSection = { title: 'THEORY · CALL', lines: [{ text: '+CALL is bullish', role: 'positive', token_roles: { '+CALL': 'positive' } }] };",
                "const direct = typedTooltipSections({ tooltip_sections: [directSection], table: { tooltip_sections: [tableSection] } });",
                "check(direct.length === 1 && direct[0].title === 'THEORY · CALL', 'column section must override the table section');",
                "check(direct[0].lines[0].role === 'positive' && direct[0].lines[0].token_roles['+CALL'] === 'positive', 'typed line role must survive');",
                "const fallback = typedTooltipSections({ table: { tooltip_sections: [tableSection] } });",
                "check(fallback.length === 1 && fallback[0].title === 'THEORY · TABLE', 'table section must serve the header');",
                "check(fallback[0].lines[0].token_roles.CALL === 'call' && !fallback[0].lines[0].token_roles.BAD, 'unknown emphasis roles must be rejected');",
                "const tooMany = typedTooltipSections({ tooltip_sections: Array.from({ length: 7 }, (_, index) => ({ title: `S${index}`, lines: Array.from({ length: 20 }, () => 'line') })) });",
                "check(tooMany.length === 4 && tooMany.every(section => section.lines.length === 12), 'sections and lines must be bounded');",
            )
        ),
        encoding="utf-8",
    )
    result = subprocess.run(["node", str(script)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


