def test_linda_overlay_filter_gates_controls_without_dropping_other_signals(
    tmp_path: Path,
) -> None:
    source = Path("src/aef_terminal/indicators/modules/linda_volume/client.js").read_text(
        encoding="utf-8"
    )
    filter_source = (
        "function lindaVolumeOverlayFilter(item, group)"
        + source.split("function lindaVolumeOverlayFilter(item, group)", 1)[1].split(
            "function renderLindaPlaybookPanel",
            1,
        )[0]
    )
    script_path = tmp_path / "linda-overlay-filter.js"
    script_path.write_text(
        "\n".join(
            (
                "const assert = require('node:assert/strict');",
                filter_source,
                "const alwaysOnRoles = [",
                "  'linda_poi_core', 'linda_poi_deep', 'linda_poi_label',",
                "  'linda_exhaustion_sm_buy', 'linda_exhaustion_sm_sell',",
                "  'linda_exhaustion_clx_long', 'linda_exhaustion_clx_short',",
                "  'linda_exhaustion_short_watch', 'linda_exhaustion_long_watch',",
                "  'linda_exhaustion_reversal_warning',",
                "  'linda_vwap_pullback_long', 'linda_vwap_pullback_short',",
                "  'linda_vwap_upper_2_reversal', 'linda_vwap_upper_2_ride', 'linda_vwap_upper_2_touch',",
                "  'linda_vwap_lower_2_reversal', 'linda_vwap_lower_2_ride', 'linda_vwap_lower_2_touch',",
                "];",
                "for (const role of alwaysOnRoles) {",
                "  const item = { type: 'label', role };",
                "  assert.strictEqual(lindaVolumeOverlayFilter(item, {})[0], item, role);",
                "}",
                "const controlledRoles = {",
                "  linda_indian_price_mark: 'indians',",
                "  linda_grail_buy: 'grail',",
                "  linda_grail_buy_watch: 'grail',",
                "  linda_grail_sell: 'grail',",
                "  linda_grail_sell_watch: 'grail',",
                "  entry: 'plan', stop: 'plan', target: 'plan', trail: 'plan', track: 'plan',",
                "  linda_setup_turtle_soup: 'turtleSoup',",
                "  linda_setup_turtle_soup_plus_one: 'turtleSoupPlusOne',",
                "  linda_setup_eighty_twenty: 'eightyTwenty',",
                "  linda_setup_the_anti: 'theAnti',",
                "  linda_setup_momentum_pinball: 'momentumPinball',",
                "  linda_setup_hv_squeeze: 'hvSqueeze',",
                "  linda_setup_adx_gapper: 'adxGapper',",
                "};",
                "for (const [role, key] of Object.entries(controlledRoles)) {",
                "  const item = { type: 'label', role };",
                "  assert.strictEqual(lindaVolumeOverlayFilter(item, { [key]: true })[0], item, role);",
                "  assert.deepEqual(lindaVolumeOverlayFilter(item, { [key]: false }), [], role);",
                "  assert.deepEqual(lindaVolumeOverlayFilter(item, {}), [], role);",
                "}",
                "const futureSignal = { type: 'label', role: 'linda_future_signal' };",
                "assert.strictEqual(lindaVolumeOverlayFilter(futureSignal, {})[0], futureSignal);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


