def test_trade_setup_zone_badges_keep_setup_direction_distinct_from_trend_context(
    tmp_path: Path,
) -> None:
    assembled = martincall_js_source()
    direction_function = (
        "function indicatorDirectionArrow"
        + assembled.split("function indicatorDirectionArrow", 1)[1].split(
            "function indicatorCodeLabel",
            1,
        )[0]
    )
    renderer = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    badge_function = (
        "function indicatorOverlayBadgeText"
        + renderer.split("function indicatorOverlayBadgeText", 1)[1].split(
            "function genericOverlayLookupForVisible",
            1,
        )[0]
    )
    assert "const close = Number(value.close)" not in badge_function
    assert "const fast = Number(value.ema_fast)" not in badge_function
    assert "const slow = Number(value.ema_slow)" not in badge_function

    script_path = tmp_path / "trade-setup-badges.js"
    script_path.write_text(
        "\n".join(
            (
                "const assert = require('node:assert/strict');",
                direction_function,
                badge_function,
                "assert.equal(indicatorOverlayBadgeText({ code: 'setup_zone', mode: 'bd', direction: 'short', state: 'armed', action: 'block' }), 'BD BLOCKED ↓');",
                "assert.equal(indicatorOverlayBadgeText({ code: 'setup_zone', mode: 'mr', direction: 'short', state: 'armed', action: 'arm' }), 'MR ARMED ↓');",
                "assert.equal(indicatorOverlayBadgeText({ code: 'trend_context', trend_direction: 'long', alignment: 'countertrend', close: 105, ema_fast: 104, ema_slow: 103 }), 'COUNTER');",
                "assert.equal(indicatorOverlayBadgeText({ code: 'setup_zone', mode: 'mr', direction: 'long', state: 'armed', action: 'arm' }), 'MR ARMED ↑');",
                "assert.equal(indicatorOverlayBadgeText({ code: 'trend_context', trend_direction: 'short', alignment: 'countertrend' }), 'COUNTER');",
                "assert.equal(indicatorOverlayBadgeText({ code: 'trend_context', trend_direction: 'short', alignment: 'aligned' }), 'TREND+');",
                "assert.equal(indicatorOverlayBadgeText({ code: 'trend_context', trend_direction: 'short', alignment: 'pullback' }), 'PULLBACK');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr


