def test_server_price_alert_refresh_preserves_active_drag() -> None:
    js = martincall_js_source()

    assert "const draggingId = state.alerts.drag" in js
    assert "const preserved = { ...localDragging, dragging: true }" in js
    assert "state.alerts.drag = draggingId || null" in js
    drag_body = js.split("function startPriceAlertDrag(canvas, event, alert)", 1)[1].split(
        "const onMove = move => updateFromEvent(move);", 1
    )[0]
    assert "const alertId = alert.id;" in drag_body
    assert "const dragAlert = () => {" in drag_body
