    assert "renderPriceObjects(state.snapshot, { excludePriceAlertIds: [alertId] });" in drag_body
    assert "renderInteractionOverlay({ immediate: true });" not in drag_body
    move_body = drag_body.split("const updateFromEvent = move => {", 1)[1]
    assert "renderCharts(state.snapshot)" not in move_body
    release_body = js.split("const onUp = move => {", 1)[1].split("const onCancel = () =>", 1)[0]
    assert "state.alerts.drag = null;" in release_body
