def test_canvas_text_contrast_uses_every_gradient_stop(tmp_path: Path) -> None:
    drawing_source = Path("src/aef_terminal/ui/assets/js/40-chart-drawing-utils.js").read_text(
        encoding="utf-8"
    )
    color_helpers = (
        "function parseCanvasColor"
        + drawing_source.split("function parseCanvasColor", 1)[1].split(
            "function themeColor",
            1,
        )[0]
    )
    table_source = Path("src/aef_terminal/ui/assets/js/49-overlays-indicators.js").read_text(
        encoding="utf-8"
    )
    script_path = tmp_path / "gradient-text-contrast.js"
    script_path.write_text(
        "\n".join(
            (
                "let chartBackground = '#ffffff';",
                "const mcThemeCache = { parsed: new Map(), blended: new Map(), readable: new Map() };",
                "function clamp(value, low, high) { return Math.min(Math.max(value, low), high); }",
                "function css(name) { return name === '--chart-bg' ? chartBackground : '#142033'; }",
                "function themeColor(name) { return name === 'label-light' ? '#ffffff' : '#061a2f'; }",
                color_helpers,
                "const lightGradient = ['rgba(13, 13, 13, 0.14)', 'rgba(13, 13, 13, 0.05)'];",
                "if (readableTextForBg(lightGradient, '#ffffff') !== '#061a2f') throw new Error('light gradient must use dark text');",
                "chartBackground = '#000000';",
                "const darkGradient = ['rgba(13, 13, 13, 0.90)', 'rgba(13, 13, 13, 0.75)'];",
                "if (readableTextForBg(darkGradient, '#ffffff') !== '#ffffff') throw new Error('dark gradient must preserve light text');",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(
        ["node", str(script_path)],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr
    assert "const tableGradientStops = tableGradient" in table_source
    assert "tableGradient && colBg === tableGradient ? tableGradientStops : colBg" in table_source


