def test_gex_scheduler_reconciliation_rejects_older_settings_revision() -> None:
    instrument_a = route_instrument(_test_identity("ES", asset_class="index")).instrument_id
    instrument_b = route_instrument(_test_identity("SPY", asset_class="index")).instrument_id

    class Store:
        snapshot = ({"enabled": True, "instrument_ids": [instrument_a]}, True, 8)

        def read_setting_snapshot(self, scope, key):
            assert (scope, key) == ("server", GEX_SCHEDULER_SETTING_KEY)
            return self.snapshot

    store = Store()
    runtime = gex_scheduler_service.GexSchedulerSettingsRuntime()
    runtime.configure(store_factory=lambda: store)

    assert runtime.settings()["instrument_ids"] == [instrument_a]
    store.snapshot = ({"enabled": True, "instrument_ids": [instrument_b]}, True, 7)
    assert runtime.publish_committed_snapshot(*store.snapshot)["instrument_ids"] == [instrument_a]
    store.snapshot = ({"enabled": True, "instrument_ids": [instrument_b]}, True, 9)
    assert runtime.publish_committed_snapshot(*store.snapshot)["instrument_ids"] == [instrument_b]


