def test_telegram_interactive_runtime_settings_retries_storage_error(monkeypatch) -> None:
    class FlakyStore:
        def __init__(self) -> None:
            self.reads = 0

        def read_setting(self, _scope: str, _key: str):
            self.reads += 1
            if self.reads == 1:
                raise RuntimeError("server settings unavailable")
            return {"enabled": True}

    store = FlakyStore()
    monkeypatch.setattr(
        ui_telegram_runtime,
        "_DEPS",
        replace(ui_telegram_runtime._deps(), store_factory=lambda: store),
    )
    monkeypatch.setattr(ui_telegram_runtime, "_TELEGRAM_INTERACTIVE_SETTINGS", None)
    monkeypatch.setattr(
        ui_telegram_runtime,
        "AppConfig",
        lambda: SimpleNamespace(
            telegram_interactive_enabled=True,
            telegram_bot_token="token",
            telegram_chat_id="chat",
        ),
    )

    unavailable = ui_telegram_runtime.telegram_interactive_runtime_settings()
    recovered = ui_telegram_runtime.telegram_interactive_runtime_settings()

    assert unavailable["enabled"] is False
    assert unavailable["configured"] is True
    assert unavailable["source"] == "unavailable"
    assert unavailable["settings_error"] == "server settings unavailable"
    assert recovered["enabled"] is True
    assert recovered["source"] == "server"
    assert store.reads == 2


