def test_screener_snapshot_requests_provider_specific_watchlist_quotes(monkeypatch) -> None:
    captured = {}

    monkeypatch.setattr(screener_services, "screener_bases", lambda instruments, interval: {})

    instruments = [
        _test_identity("ES", "ibkr", asset_class="future"),
        _test_identity("BTC", "coinbase", "BTC-USD", asset_class="crypto"),
    ]

    def fake_wanted(key, symbols, ttl_seconds):
        captured["wanted_key"] = key
        captured["wanted"] = list(symbols)

    def fake_cache(cache_instruments):
        captured["cache_instruments"] = list(cache_instruments)
        rows = {
            "ES": {"price": 7548.0, "ts": "2026-07-03T15:00:00+00:00", "source": "ibkr:quote-live"},
            "BTC-USD": {
                "price": 62125.0,
                "ts": "2026-07-03T15:05:04+00:00",
                "source": "coinbase:quote-live",
            },
        }
        return (
            {
                route_instrument(instrument).fingerprint: rows[
                    route_instrument(instrument).provider_symbol
                ]
                for instrument in cache_instruments
            },
            "",
            QuoteCacheRevision(
                "00000000-0000-4000-8000-000000000001",
                1,
            ),
        )

    monkeypatch.setattr(
        screener_services,
        "_DEPS",
        screener_services.ScreenerRuntimeDeps(
            store_factory=lambda: None,
            apply_ibkr_runtime_settings_async=lambda: asyncio.sleep(0),
            selected_instruments=lambda instrument_ids=None: (
                instruments
                if instrument_ids is None
                else [
                    {
                        route_instrument(instrument).instrument_id: instrument
                        for instrument in instruments
                    }[instrument_id]
                    for instrument_id in instrument_ids
                ]
            ),
            server_sleeping=lambda: False,
            set_transient_quote_wanted=fake_wanted,
            quote_cache_for_instruments=fake_cache,
        ),
    )

    requested_routes = [
        {
            "instrument_id": route_instrument(instrument).instrument_id,
            "route_fingerprint": route_instrument(instrument).fingerprint,
        }
        for instrument in instruments
    ]
    payload = asyncio.run(screener_services.screener_snapshot(json.dumps(requested_routes), "5m"))
    rows = payload["rows"]
    by_key = {row["key"]: row for row in rows}

    assert captured["wanted"] == sorted(
        route_instrument(instrument).instrument_id for instrument in instruments
    )
    assert json.loads(captured["wanted_key"].removeprefix("screener:")) == requested_routes
    assert [item["key"] for item in captured["cache_instruments"]] == ["ES", "BTC"]
    assert payload["cache_epoch"] == "00000000-0000-4000-8000-000000000001"
    assert payload["cache_generation"] == 1
    assert by_key["BTC"]["source"] == "coinbase:quote-live"
    assert by_key["BTC"]["quote_ts"] == "2026-07-03T15:05:04+00:00"


