def test_deferred_analysis_refresh_rejects_hidden_or_changed_scope(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/20-live-candle-sync.js").read_text(
        encoding="utf-8"
    )
    scheduler_source = (
        "function analysisRefreshBusy()"
        + source.split("function analysisRefreshBusy()", 1)[1].split(
            'function maybeScheduleIndicatorAnalysisRefresh(reason = "chart-stream")',
            1,
        )[0]
    )
    script_path = tmp_path / "analysis-refresh-scope.js"
    script_path.write_text(
        "\n".join(
            (
                "const timers = new Map(); let nextTimer = 1;",
                "const window = {",
                "  setTimeout(callback) { const id = nextTimer++; timers.set(id, callback); return id; },",
                "  clearTimeout(id) { timers.delete(id); },",
                "};",
                "const document = { visibilityState: 'visible' };",
                "const state = {",
                "  instrumentId: 'instrument-a', routeFingerprint: 'route-a', timeframe: '5m', range: '3d',",
                "  serverSleeping: false, snapshot: { meta: {} },",
                "  requests: { market: { loading: false }, analysis: { loading: false } },",
                "  refreshTimer: null, refreshKey: '', lastRefreshAt: 0,",
                "};",
                "function exactIdentityText(value) { return typeof value === 'string' ? value : ''; }",
                "function instrumentRouteFingerprint() { return state.routeFingerprint; }",
                "function snapshotMatchesCurrentRoute() { return true; }",
                "function acquireSharedStreamOwner() { return true; }",
                "function releaseSharedStreamOwner() {}",
                "function debugStep() {}",
                "let loads = 0; let retries = 0;",
                "function load() { loads += 1; return Promise.resolve(); }",
                scheduler_source,
                "scheduleAnalysisRefreshOnce({",
                "  latestKey: 'old-version', activeBarStateKey: 'refreshKey',",
                "  timerStateKey: 'refreshTimer', lastRefreshStateKey: 'lastRefreshAt',",
                "  delayMs: 10, reason: 'test', debugLabel: 'test', loadOptions: { analysisVersionKey: 'old-version' },",
                "});",
                "const staleCallback = timers.get(state.refreshTimer);",
                "state.instrumentId = 'instrument-b'; state.routeFingerprint = 'route-b';",
                "staleCallback();",
                "if (loads !== 0 || state.refreshTimer !== null || state.refreshKey !== '') process.exit(2);",
                "scheduleAnalysisRefreshOnce({",
                "  latestKey: 'hidden-version', activeBarStateKey: 'refreshKey',",
                "  timerStateKey: 'refreshTimer', lastRefreshStateKey: 'lastRefreshAt',",
                "  delayMs: 10, reason: 'test', debugLabel: 'test', loadOptions: { analysisVersionKey: 'hidden-version' },",
                "  retry: () => { retries += 1; },",
                "});",
                "const hiddenCallback = timers.get(state.refreshTimer);",
                "document.visibilityState = 'hidden'; hiddenCallback();",
                "if (loads !== 0 || retries !== 0 || state.refreshTimer !== null || state.refreshKey !== '') process.exit(3);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


def test_throttled_market_render_drops_previous_instrument_snapshot(tmp_path: Path) -> None:
    source = Path("src/aef_terminal/ui/assets/js/30-market-panel-runtime.js").read_text(
        encoding="utf-8"
    )
    chart_throttle_source = (
        "let pendingLiveMarketChartSnapshot"
        + source.split("let pendingLiveMarketChartSnapshot", 1)[1].split(
            "function renderLiveMarketVisuals",
            1,
        )[0]
    )
    panel_throttle_source = (
        "let pendingPanelSnapshot"
        + source.split("let pendingPanelSnapshot", 1)[1].split(
            "function marketAnalysisLifecyclePresentation",
            1,
        )[0]
        + "function renderPanel(snapshot, options = {})"
        + source.split("function renderPanel(snapshot, options = {})", 1)[1].split(
            "function renderPanelNow",
            1,
        )[0]
    )
    script_path = tmp_path / "market-render-scope.js"
    script_path.write_text(
        "\n".join(
            (
                "let now = 1000; Date.now = () => now;",
                "const timers = new Map(); let nextTimer = 1;",
                "const window = {",
                "  setTimeout(callback) { const id = nextTimer++; timers.set(id, callback); return id; },",
                "  clearTimeout(id) { timers.delete(id); },",
                "};",
                "const state = { instrumentId: 'instrument-a', routeFingerprint: 'route-a', timeframe: '5m', range: '1d' };",
                "function snapshotMatchesCurrentRoute(snapshot) {",
                "  return snapshot?.meta?.instrument_id === state.instrumentId",
                "    && snapshot?.meta?.route_fingerprint === state.routeFingerprint",
                "    && snapshot?.meta?.timeframe === state.timeframe;",
                "}",
                "function panelSnapshotReady(snapshot) { return Boolean(snapshot?.meta && snapshot?.decision); }",
                "function renderMarketHealthStatus() {}",
                "const chartRenders = []; function renderCharts(snapshot) { chartRenders.push(snapshot.meta.instrument_id); }",
                "const panelRenders = []; function renderPanelNow(snapshot) { panelRenders.push(snapshot.meta.instrument_id); }",
                "const snapshotA = { meta: { instrument_id: 'instrument-a', route_fingerprint: 'route-a', timeframe: '5m', chart_range: '1d' }, decision: {} };",
                "const snapshotB = { meta: { instrument_id: 'instrument-b', route_fingerprint: 'route-b', timeframe: '5m', chart_range: '5d' }, decision: {} };",
                chart_throttle_source,
                panel_throttle_source,
                "renderLiveMarketChart(snapshotA); chartRenders.length = 0;",
                "renderLiveMarketChart(snapshotA, { chartThrottleMs: 100 });",
                "const chartCallback = timers.get(liveMarketChartRenderTimer);",
                "renderPanel(snapshotA, { immediate: true }); panelRenders.length = 0; renderPanel(snapshotA); const panelCallback = timers.get(panelRenderTimer);",
                "state.range = '5d'; resetDeferredMarketRenders(); chartCallback(); panelCallback();",
                "if (chartRenders.length !== 0 || panelRenders.length !== 0 || timers.size !== 0) process.exit(5);",
                "if (pendingLiveMarketChartSnapshot !== null || pendingPanelSnapshot !== null) process.exit(6);",
                "lastLiveMarketChartRenderAt = now; renderLiveMarketChart(snapshotA, { chartThrottleMs: 100 });",
                "const scopedChartCallback = timers.get(liveMarketChartRenderTimer);",
                "state.instrumentId = 'instrument-b'; state.routeFingerprint = 'route-b';",
                "scopedChartCallback();",
                "if (chartRenders.length !== 0 || liveMarketChartRenderTimer !== null) process.exit(2);",
                "renderPanel(snapshotB, { immediate: true }); panelRenders.length = 0;",
                "renderPanel(snapshotA);",
                "if (panelRenders.length !== 0 || panelRenderTimer !== null) process.exit(3);",
                "renderPanel(snapshotB, { immediate: true });",
                "if (panelRenders.length !== 1 || panelRenders[0] !== 'instrument-b') process.exit(4);",
            )
        ),
        encoding="utf-8",
    )

    result = subprocess.run(["node", str(script_path)], capture_output=True, text=True, check=False)

    assert result.returncode == 0, result.stderr


